function buildGeoProbesV2(domain: string): GeoProbeV2Doc[] {
  const engines = ["gpt", "claude", "gemini", "perplexity"] as const;
  const questions: Array<{ question: string; category: GeoProbeV2Doc["category"]; sourceKeywords: string[] }> = [
    { question: "민감성 피부에 좋은 비건 스킨케어 브랜드 추천해줘", category: "product", sourceKeywords: ["비건 스킨케어", "민감성 피부"] },
    { question: "한국 클린뷰티 브랜드 중 발효 원료를 쓰는 곳은 어디야?", category: "brand", sourceKeywords: ["클린뷰티", "발효 원료"] },
    { question: "저자극 세럼 Glow Lab vs Sample Brand 비교", category: "comparison", sourceKeywords: ["저자극 세럼", "Glow Lab"] },
    { question: "K-beauty 저자극 루틴 순서 알려줘", category: "howto", sourceKeywords: ["K뷰티 루틴"] },
    { question: "서울에서 Sample Brand 오프라인 매장 어디에 있어?", category: "local", sourceKeywords: ["Sample Brand 매장"] },
    { question: "vegan skincare for sensitive skin top brands", category: "product", sourceKeywords: ["vegan skincare", "sensitive skin"] },
    { question: "fermented essence best korean brand", category: "brand", sourceKeywords: ["fermented essence"] },
    { question: "Petal & Dew vs Sample Brand which is better for dry skin", category: "comparison", sourceKeywords: ["Petal & Dew", "dry skin"] },
    { question: "how to layer ceramide serum and fermented essence", category: "howto", sourceKeywords: ["ceramide", "essence"] },
    { question: "best clean beauty store in Gangnam Seoul", category: "local", sourceKeywords: ["clean beauty", "Gangnam"] },
  ];

  // 40개 probe: 엔진 4 × 질문 10. exposure/mention은 engine-level 목표치와 일치하도록 결정적 분포.
  // 목표: gpt exposed 26/40 mentioned 16, claude 22/14, gemini 20/12, perplexity 24/13
  const enginePlan: Record<typeof engines[number], { exposed: number; mentioned: number }> = {
    gpt: { exposed: 26, mentioned: 16 },
    claude: { exposed: 22, mentioned: 14 },
    gemini: { exposed: 20, mentioned: 12 },
    perplexity: { exposed: 24, mentioned: 13 },
  };

  // engine당 10개 질문. 스케일 ×4 → engine당 exposed/mentioned 는 목표치의 1/4 반올림.
  const perEngineQuestions = 10;
  const probes: GeoProbeV2Doc[] = [];
  for (const engine of engines) {
    const planExposed = Math.round(enginePlan[engine].exposed / 4);
    const planMentioned = Math.round(enginePlan[engine].mentioned / 4);
    for (let i = 0; i < perEngineQuestions; i++) {
      const q = questions[i];
      const exposed = i < planExposed;
      const mentioned = i < planMentioned;
      probes.push({
        engine,
        question: q.question,
        category: q.category,
        sourceKeywords: q.sourceKeywords,
        ourSiteInResults: exposed,
        ourSiteMentioned: mentioned,
        ourMentionContext: mentioned
          ? `...${domain} 의 발효 에센스 라인은 민감성 피부에서 특히 호평...`
          : "",
        answer: mentioned
          ? `Sample Brand(${domain})는 발효 기반 저자극 라인으로 국내 클린뷰티 시장에서 입지를 넓히고 있는 브랜드입니다.`
          : "여러 브랜드가 해당 카테고리에 진출해 있습니다.",
        references: exposed ? [`https://${domain}/about`, "https://www.example-allure.com/kbeauty-2025"] : [],
        status: "completed",
      });
    }
  }
  return probes;
}

function summarizeGeoProbes(probes: GeoProbeV2Doc[]): GeoProbeV2Summary {
  const byEngine = new Map<string, { total: number; exposed: number; mentioned: number }>();
  for (const p of probes) {
    const e = byEngine.get(p.engine) ?? { total: 0, exposed: 0, mentioned: 0 };
    e.total += 1;
    if (p.ourSiteInResults) e.exposed += 1;
    if (p.ourSiteMentioned) e.mentioned += 1;
    byEngine.set(p.engine, e);
  }
  const engineBreakdown: DashboardEngineBreakdown[] = [];
  let totalExposed = 0;
  let totalMentioned = 0;
  for (const [engine, v] of byEngine.entries()) {
    const scaledTotal = v.total * 4; // seed 는 engine당 10문항, 실 집계는 40문항 기준 리포팅
    const scaledExposed = v.exposed * 4;
    const scaledMentioned = v.mentioned * 4;
    engineBreakdown.push({
      engine,
      totalQuestions: scaledTotal,
      exposedCount: scaledExposed,
      mentionedCount: scaledMentioned,
      exposureRate: scaledTotal > 0 ? Math.round((scaledExposed / scaledTotal) * 100) : 0,
      mentionRate: scaledTotal > 0 ? Math.round((scaledMentioned / scaledTotal) * 100) : 0,
    });
    totalExposed += scaledExposed;
    totalMentioned += scaledMentioned;
  }
  const totalProbes = probes.length * 4;
  return {
    totalProbes,
    exposureRate: totalProbes > 0 ? Math.round((totalExposed / totalProbes) * 100) : 0,
    mentionRate: totalProbes > 0 ? Math.round((totalMentioned / totalProbes) * 100) : 0,
    engineBreakdown,
  };
}

