// ── Helpers ──────────────────────────────────────────────────

function normalizeDomainKey(domain: string): string {
  return domain.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "") || "unknown";
}

function hashKey(input: string): string {
  let h = 0;
  for (let i = 0; i < input.length; i++) {
    h = ((h << 5) - h + input.charCodeAt(i)) | 0;
  }
  return Math.abs(h).toString(36);
}

// ── Section writers (subcollection) ──────────────────────────

async function seedCompetitorsV2(boardId: string, competitors: CompetitorV2Doc[]): Promise<void> {
  const batch = writeBatch(db);
  for (const c of competitors) {
    batch.set(
      paths.rawCompetitor(boardId, normalizeDomainKey(c.domain)),
      { ...c, type: "auto", createdAt: serverTimestamp() },
      { merge: true },
    );
  }
  await batch.commit();
}

async function seedExternalSourcesV2(boardId: string, sources: DashboardExternalSource[]): Promise<void> {
  const batch = writeBatch(db);
  for (const s of sources) {
    const key = s.sourceUrl ? hashKey(s.sourceUrl) : hashKey(`${s.sourceType}-${s.sourceName}`);
    // externalSourcesV2 is collection-only; build doc ref via paths.externalSourcesV2 parent.
    batch.set(
      paths.rawExternalSource(boardId, key),
      { ...s, createdAt: serverTimestamp() },
      { merge: true },
    );
  }
  await batch.commit();
}

async function seedGeoProbesV2(boardId: string, probes: GeoProbeV2Doc[]): Promise<void> {
  const batch = writeBatch(db);
  probes.forEach((p, idx) => {
    const key = `${p.engine}-${String(idx).padStart(3, "0")}`;
    batch.set(
      paths.rawGeoProbe(boardId, key),
      { ...p, createdAt: serverTimestamp() },
      { merge: true },
    );
  });
  await batch.commit();
}

async function seedBenchmarkDailyV2(boardId: string, points: DashboardBenchmarkPoint[]): Promise<void> {
  const batch = writeBatch(db);
  for (const p of points) {
    batch.set(paths.rawBenchmarkDailyDoc(boardId, p.date), { ...p, date: p.date, updatedAt: serverTimestamp() }, { merge: true });
  }
  await batch.commit();
}

interface SummaryWritePayload {
  key: string;
  title: string;
  data: Record<string, unknown>;
}

async function seedSummaries(boardId: string, payloads: SummaryWritePayload[]): Promise<void> {
  const batch = writeBatch(db);
  for (const p of payloads) {
    batch.set(
      paths.summary(boardId, p.key),
      { key: p.key, title: p.title, data: p.data, updatedAt: serverTimestamp() },
      { merge: true },
    );
  }
  await batch.commit();
}

async function seedDocuments(
  boardId: string,
  payloads: Array<{ key: string; title: string; data: Record<string, unknown>; body?: string }>,
): Promise<void> {
  const batch = writeBatch(db);
  for (const p of payloads) {
    batch.set(
      paths.analysis(boardId, p.key),
      { title: p.title, body: p.body ?? null, data: p.data, updatedAt: serverTimestamp() },
      { merge: true },
    );
  }
  await batch.commit();
}

// ── Entry ────────────────────────────────────────────────────

export async function seedDashboardData(boardId: string, domain: string): Promise<void> {
  const effectiveDomain = domain || "samplebrand.co";

  const brandClient = buildBrandClient(effectiveDomain);
  const keywordClouds = buildKeywordClouds();
  const competitorsSummary = buildCompetitorsSummary();
  const nextActions = buildNextActions();
  const genericEngineSummary = buildGenericEngineSummary();
  const siteHealth = buildSiteHealth();
  const trackingIntegrations = buildTrackingIntegrations();
  const demandKpis = buildDemandKpis();
  const domainEntity = buildDomainEntity(effectiveDomain);
  const externalSignals = buildExternalSignals();

  const benchmarkPoints = buildBenchmarkPoints();
  const externalSources = buildExternalSources();
  const competitors = buildCompetitorsV2();
  const probes = buildGeoProbesV2(effectiveDomain);
  const probeSummary = summarizeGeoProbes(probes);

  const brandDoc = buildBrandDocument(effectiveDomain);
  const competitorAnalysisDoc = buildCompetitorAnalysisDocument(competitors);
  const executiveSummaryDoc = buildExecutiveSummaryDocument();
  const externalSourcesDoc = buildExternalSourcesDocument(externalSources);

  // 1. 요약은 boards/{id}/summaries 단일 컬렉션에만 존재. 섹션별 독립 문서.
  const latestBenchmarkPoint = benchmarkPoints[benchmarkPoints.length - 1];
  const summaryPayloads: SummaryWritePayload[] = [
    { key: "brand", title: "Brand Summary", data: brandClient as unknown as Record<string, unknown> },
    { key: "keyword-clouds", title: "Keyword Clouds", data: keywordClouds as unknown as Record<string, unknown> },
    { key: "competitor-overview", title: "Competitor Overview", data: competitorsSummary as unknown as Record<string, unknown> },
    { key: "next-actions", title: "Next Actions", data: nextActions as unknown as Record<string, unknown> },
    { key: "engines", title: "Engines Summary", data: genericEngineSummary as unknown as Record<string, unknown> },
    { key: "site-health", title: "Site Health", data: siteHealth as unknown as Record<string, unknown> },
    { key: "tracking-integrations", title: "Tracking Integrations", data: trackingIntegrations as unknown as Record<string, unknown> },
    { key: "demand-kpis", title: "Demand KPIs", data: demandKpis as unknown as Record<string, unknown> },
    { key: "domain-entity", title: "Domain Entity", data: domainEntity as unknown as Record<string, unknown> },
    { key: "external-signals", title: "External Signals", data: externalSignals as unknown as Record<string, unknown> },
    { key: "geo-probes", title: "GEO Probes Summary", data: probeSummary as unknown as Record<string, unknown> },
  ];
  if (latestBenchmarkPoint) {
    summaryPayloads.push({
      key: "benchmark-latest",
      title: "Benchmark Latest",
      data: latestBenchmarkPoint as unknown as Record<string, unknown>,
    });
  }

  // 2. 리스트성 _v2 subcollection 쓰기 (요약 문서는 여기 두지 않음).
  await Promise.all([
    seedSummaries(boardId, summaryPayloads),
    seedCompetitorsV2(boardId, competitors),
    seedExternalSourcesV2(boardId, externalSources),
    seedGeoProbesV2(boardId, probes),
    seedBenchmarkDailyV2(boardId, benchmarkPoints),
  ]);

  // 3. Documents subcollection — 실 파이프라인이 생성하는 문서들과 동일한 key/shape
  await seedDocuments(boardId, [
    { key: "brand", title: "Brand Overview", data: brandDoc as unknown as Record<string, unknown>, body: brandDoc.overview },
    { key: "competitor-analysis", title: "Competitor Analysis", data: competitorAnalysisDoc as unknown as Record<string, unknown> },
    { key: "executive-summary", title: "Executive Summary", data: executiveSummaryDoc as unknown as Record<string, unknown>, body: executiveSummaryDoc.summary },
    { key: "external-sources-analysis", title: "External Sources Analysis", data: externalSourcesDoc as unknown as Record<string, unknown> },
  ]);

  // 4. 독립 호출이 필요한 문서는 setDoc 으로 idempotent 처리 (예시: brand_truth)
  await setDoc(
    paths.rawBrandTruth(boardId),
    { ...brandDoc, updatedAt: serverTimestamp() },
    { merge: true },
  );
}
