import { useEffect, useMemo, useState } from "react";
import { useParams } from "react-router-dom";
import {
  AlertTriangle,
  FileText,
  Gauge,
  Lightbulb,
  Sparkles,
} from "lucide-react";
import { getSummary, listSeoAudits, subscribeInsights } from "../../../db/boards";
import type { InsightDoc } from "../../../db/collections";
import { MetricCard } from "../../../components/shared/MetricCard";
import { EmptyState } from "../../../components/shared/EmptyState";
import { InsightSection } from "../../../components/shared/InsightSection";
import { DataQualityBadge } from "../../../components/shared/DataQualityBadge";

interface ContentDiagnostic {
  dimension: string;
  score: number;
  maxScore: number;
  findings?: string[];
  recommendations?: string[];
}

interface ContentAnalysisData {
  diagnostics?: ContentDiagnostic[];
  overallScore?: number;
  summary?: string;
  analyzedAt?: string;
}

interface ContentCheck {
  label?: string;
  rule: string;
  status: "pass" | "warn" | "fail";
  detail?: string;
}

export function ContentQualityInsight() {
  const { id } = useParams<{ id: string }>();
  const [contentDoc, setContentDoc] = useState<ContentAnalysisData | null>(null);
  const [audit, setAudit] = useState<Record<string, unknown> | null>(null);
  const [insights, setInsights] = useState<InsightDoc[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!id) return;
    setLoading(true);
    const unsub = subscribeInsights(id, setInsights, { type: "content_gap" });
    Promise.all([
      getSummary(id, "content-quality").catch(() => null),
      listSeoAudits(id, 1).catch(() => []),
    ]).then(([summary, audits]) => {
      setContentDoc((summary as ContentAnalysisData) ?? null);
      setAudit((audits[0] as Record<string, unknown>) ?? null);
      setLoading(false);
    });
    return unsub;
  }, [id]);

  const diagnostics = contentDoc?.diagnostics ?? [];
  const overallScore = contentDoc?.overallScore ?? null;
  const summary = contentDoc?.summary ?? "";

  const contentChecks = useMemo(() => {
    const all = (audit?.checks ?? []) as ContentCheck[];
    return all.filter((c) =>
      c.rule?.startsWith("geo-") &&
      ["sentence", "passive", "lead", "content-too-short", "tldr", "summary", "question"].some((k) => c.rule.includes(k)),
    );
  }, [audit]);

  const { allFindings, allRecommendations, avgDiagScore, topDiag, bottomDiag } = useMemo(() => {
    const findings: Array<{ dimension: string; text: string }> = [];
    const recs: Array<{ dimension: string; text: string }> = [];
    let total = 0;
    let count = 0;
    for (const d of diagnostics) {
      if (typeof d.score === "number" && typeof d.maxScore === "number" && d.maxScore > 0) {
        total += (d.score / d.maxScore) * 100;
        count += 1;
      }
      for (const f of d.findings ?? []) findings.push({ dimension: d.dimension, text: f });
      for (const r of d.recommendations ?? []) recs.push({ dimension: d.dimension, text: r });
    }
    const sorted = [...diagnostics].filter((d) => typeof d.score === "number").sort((a, b) => normalize(b) - normalize(a));
    return {
      allFindings: findings,
      allRecommendations: recs,
      avgDiagScore: count > 0 ? Math.round(total / count) : null,
      topDiag: sorted[0] ?? null,
      bottomDiag: sorted[sorted.length - 1] ?? null,
    };
  }, [diagnostics]);

  const dataQuality = useMemo(() => {
    const signals = [
      { name: "Content analysis", ok: !!contentDoc },
      { name: "Diagnostics", ok: diagnostics.length > 0 },
      { name: "SEO audit", ok: !!audit },
      { name: "Overall score", ok: overallScore != null },
    ];
    const okCount = signals.filter((s) => s.ok).length;
    const score = Math.round((okCount / signals.length) * 100);
    const status: "ok" | "warning" | "degraded" | "invalid" =
      score >= 80 ? "ok" : score >= 50 ? "warning" : score > 0 ? "degraded" : "invalid";
    const notes = signals.filter((s) => !s.ok).map((s) => `${s.name} not available`);
    return { score, status, notes };
  }, [contentDoc, audit, diagnostics.length, overallScore]);

  const openInsights = useMemo(
    () => insights.filter((i) => i.status !== "resolved" && i.status !== "ignored"),
    [insights],
  );

  if (loading) {
    return (
      <div className="flex min-h-[30vh] items-center justify-center text-sm text-[var(--shell-text-muted)]">
        불러오는 중...
      </div>
    );
  }

  const hasAnyData = diagnostics.length > 0 || contentChecks.length > 0 || overallScore != null || openInsights.length > 0;

  if (!hasAnyData) {
    return (
      <EmptyState
        icon={FileText}
        title="No content quality data yet"
        description="전체 분석을 실행하면 최신성, 깊이, 가독성, 내부 링크, 미디어, CTA 효과를 기준으로 페이지를 점수화합니다."
      />
    );
  }

  return (
    <div className="space-y-6">
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <MetricCard icon={Gauge} label="Overall Score" value={formatScore(overallScore)} color={scoreColor(overallScore)} />
        <MetricCard icon={Sparkles} label="Avg Dimension" value={formatScore(avgDiagScore)} color={scoreColor(avgDiagScore)} />
        <MetricCard
          icon={Lightbulb}
          label="Strongest"
          value={topDiag ? topDiag.dimension : "--"}
          color="text-emerald-600"
        />
        <MetricCard
          icon={AlertTriangle}
          label="Weakest"
          value={bottomDiag ? bottomDiag.dimension : "--"}
          color="text-rose-500"
        />
      </div>

      <DataQualityBadge score={dataQuality.score} status={dataQuality.status} notes={dataQuality.notes} />

      {summary && (
        <InsightSection title="Summary" icon={FileText} defaultOpen>
          <p className="text-sm leading-relaxed text-[var(--shell-text-muted)]">{summary}</p>
        </InsightSection>
      )}

      {openInsights.length > 0 && (
        <InsightSection title="Open Content Gaps" icon={AlertTriangle} count={openInsights.length} defaultOpen>
          <div className="space-y-2">
            {openInsights.slice(0, 12).map((ins) => (
              <div key={ins.id} className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
                <div className="flex items-center justify-between gap-2">
                  <p className="text-sm font-medium text-[var(--shell-text)]">{ins.title}</p>
                  <span className={`rounded-md px-1.5 py-0.5 text-[10px] font-medium ${
                    ins.severity === "critical" ? "bg-rose-500/10 text-rose-500"
                      : ins.severity === "warning" ? "bg-amber-500/10 text-amber-500"
                      : "bg-blue-400/10 text-blue-500"
                  }`}>
                    {ins.severity}
                  </span>
                </div>
                {ins.summary && (
                  <p className="mt-1 text-xs text-[var(--shell-text-muted)]">{ins.summary}</p>
                )}
                {ins.suggestion && (
                  <p className="mt-1 text-xs text-[var(--shell-text)]">{ins.suggestion}</p>
                )}
              </div>
            ))}
          </div>
        </InsightSection>
      )}

      {diagnostics.length > 0 && (
        <InsightSection title="Diagnostic Dimensions" icon={Gauge} count={diagnostics.length} defaultOpen>
          <div className="space-y-3">
            {diagnostics.map((d, i) => (
              <DiagnosticRow key={i} diag={d} />
            ))}
          </div>
        </InsightSection>
      )}

      {allRecommendations.length > 0 && (
        <InsightSection
          title="Recommendations"
          icon={Lightbulb}
          count={allRecommendations.length}
          defaultOpen
        >
          <div className="space-y-2">
            {allRecommendations.slice(0, 12).map((r, i) => (
              <div key={i} className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
                <p className="text-[10px] uppercase tracking-wider text-[var(--shell-text-muted)]">{r.dimension}</p>
                <p className="mt-1 text-sm text-[var(--shell-text)]">{r.text}</p>
              </div>
            ))}
          </div>
        </InsightSection>
      )}

      {allFindings.length > 0 && (
        <InsightSection
          title="Findings"
          icon={AlertTriangle}
          count={allFindings.length}
          defaultOpen={false}
        >
          <div className="space-y-2">
            {allFindings.slice(0, 15).map((f, i) => (
              <div key={i} className="flex items-start gap-3 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
                <span className="mt-1.5 h-1.5 w-1.5 shrink-0 rounded-full bg-amber-500" />
                <div className="min-w-0 flex-1">
                  <p className="text-[10px] uppercase tracking-wider text-[var(--shell-text-muted)]">{f.dimension}</p>
                  <p className="mt-0.5 text-sm text-[var(--shell-text)]">{f.text}</p>
                </div>
              </div>
            ))}
          </div>
        </InsightSection>
      )}

      {contentChecks.length > 0 && (
        <InsightSection title="Content Rule Checks" icon={AlertTriangle} count={contentChecks.length} defaultOpen={false}>
          <div className="space-y-2">
            {contentChecks.slice(0, 10).map((c, i) => (
              <div key={i} className="flex items-start gap-3 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
                <StatusDot status={c.status} />
                <div className="min-w-0 flex-1">
                  <p className="text-sm font-medium text-[var(--shell-text)]">{c.label || c.rule}</p>
                  {c.detail && <p className="mt-0.5 text-xs text-[var(--shell-text-muted)]">{c.detail}</p>}
                </div>
                <span className="rounded-full bg-[var(--shell-panel)] px-2 py-0.5 text-[10px] font-medium text-[var(--shell-text-muted)]">
                  {c.status}
                </span>
              </div>
            ))}
          </div>
        </InsightSection>
      )}
    </div>
  );
}

function DiagnosticRow({ diag }: { diag: ContentDiagnostic }) {
  const pct = normalize(diag);
  const barColor = pct >= 70 ? "bg-emerald-500" : pct >= 40 ? "bg-amber-500" : "bg-rose-500";
  return (
    <div className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
      <div className="flex items-center justify-between gap-3">
        <p className="text-sm font-medium text-[var(--shell-text)]">{diag.dimension}</p>
        <span className="text-xs text-[var(--shell-text-muted)]">
          {diag.score}/{diag.maxScore}
        </span>
      </div>
      <div className="mt-2 h-1.5 w-full overflow-hidden rounded-full bg-[var(--shell-panel)]">
        <div className={`h-full ${barColor}`} style={{ width: `${Math.min(100, Math.max(0, pct))}%` }} />
      </div>
      {(diag.findings?.length || diag.recommendations?.length) ? (
        <div className="mt-3 grid gap-3 md:grid-cols-2">
          {diag.findings && diag.findings.length > 0 && (
            <div>
              <p className="text-[10px] uppercase tracking-wider text-[var(--shell-text-muted)]">Findings</p>
              <ul className="mt-1 space-y-1">
                {diag.findings.slice(0, 3).map((f, i) => (
                  <li key={i} className="text-xs text-[var(--shell-text-muted)]">- {f}</li>
                ))}
              </ul>
            </div>
          )}
          {diag.recommendations && diag.recommendations.length > 0 && (
            <div>
              <p className="text-[10px] uppercase tracking-wider text-[var(--shell-text-muted)]">Recommendations</p>
              <ul className="mt-1 space-y-1">
                {diag.recommendations.slice(0, 3).map((r, i) => (
                  <li key={i} className="text-xs text-[var(--shell-text-muted)]">- {r}</li>
                ))}
              </ul>
            </div>
          )}
        </div>
      ) : null}
    </div>
  );
}

function StatusDot({ status }: { status: "pass" | "warn" | "fail" }) {
  const color = status === "fail" ? "bg-rose-500" : status === "warn" ? "bg-amber-500" : "bg-emerald-500";
  return <span className={`mt-1.5 inline-block h-2 w-2 shrink-0 rounded-full ${color}`} />;
}

function normalize(d: ContentDiagnostic): number {
  if (typeof d.score !== "number" || typeof d.maxScore !== "number" || d.maxScore === 0) return 0;
  return Math.round((d.score / d.maxScore) * 100);
}

function formatScore(value: number | null): string {
  return value != null ? String(Math.round(value)) : "--";
}

function scoreColor(value: number | null): string {
  if (value == null) return "text-[var(--shell-text-muted)]";
  if (value >= 70) return "text-emerald-600";
  if (value >= 40) return "text-amber-500";
  return "text-rose-500";
}
