import { useMemo, useState } from "react";
import { CheckCircle2, Circle, ChevronDown, ChevronUp, Bot } from "lucide-react";
import { usePortalDashboard, usePortalSeo } from "./dataHub";

type CheckItem = {
  key: string;
  label: string;
  description: string;
  applied: boolean;
  howTo?: string;
};

type EngineAppliedMap = {
  robots: boolean;
  schema: boolean;
  llms: boolean;
  ga4: boolean;
  searchConsole: boolean;
  sitemap: boolean;
};

type EngineGuide = {
  engine: "ChatGPT" | "Gemini" | "Perplexity";
  description: string;
  items: Array<{ label: string; key: keyof EngineAppliedMap; expectedEffect: string }>;
};

const ENGINE_GUIDES: EngineGuide[] = [
  {
    engine: "ChatGPT",
    description: "OpenAI 의 GPTBot 이 학습 데이터를 수집할 때 robots.txt 와 llms.txt 를 우선 참고합니다.",
    items: [
      { label: "robots.txt 에 GPTBot 허용", key: "robots", expectedEffect: "GPT 의 학습 대상 진입 — 답변에 우리 콘텐츠 인용 가능성 ↑" },
      { label: "llms.txt 작성", key: "llms", expectedEffect: "AI 가 우리 사이트의 핵심 정보를 빠르게 이해 — 답변 정확도 ↑" },
      { label: "Bing Webmaster 등록 (Bing 검색 = ChatGPT 출처)", key: "searchConsole", expectedEffect: "ChatGPT 의 web search 가 우리 사이트를 빨리 찾음" },
    ],
  },
  {
    engine: "Gemini",
    description: "Google 검색을 그대로 출처로 활용 — Search Console + 구조화 데이터가 핵심입니다.",
    items: [
      { label: "Google Search Console 등록", key: "searchConsole", expectedEffect: "Gemini 답변의 Google 출처 인덱싱 가속" },
      { label: "Schema.org JSON-LD (FAQPage / Product)", key: "schema", expectedEffect: "Gemini 가 구조화된 답변 생성 — FAQ 형식 응답에 직접 인용 가능" },
      { label: "GA4 연동 (사용자 신호 강화)", key: "ga4", expectedEffect: "사이트 신뢰성 신호 — Google 의 AI Overviews 노출 우선순위 ↑" },
    ],
  },
  {
    engine: "Perplexity",
    description: "실시간 web 검색 엔진 — sitemap 최신화와 빠른 로딩이 직접적인 영향을 줍니다.",
    items: [
      { label: "sitemap.xml 최신화", key: "sitemap", expectedEffect: "Perplexity 의 인덱싱 빈도 ↑ — 새 콘텐츠가 빠르게 답변에 반영" },
      { label: "Schema.org 구조화 데이터", key: "schema", expectedEffect: "Perplexity 의 출처 인용 패턴이 구조화된 페이지 우선" },
      { label: "robots.txt 에 PerplexityBot 허용", key: "robots", expectedEffect: "Perplexity crawler 가 우리 콘텐츠 수집 가능" },
    ],
  },
];

export function PortalTechnical() {
  const [showBasic, setShowBasic] = useState(false);

  const { data: dashboardData, isLoading } = usePortalDashboard();
  const { data: seoData } = usePortalSeo();

  const checks = useMemo<CheckItem[]>(() => {
    const siteInfo = dashboardData?.onboarding?.siteInfo || {};
    const siteFiles = siteInfo.siteFiles || {};
    const siteDetection = siteInfo.siteDetection || {};
    const signals =
      (seoData?.categories as { signalsSummary?: { hasSchema?: boolean } } | null)?.signalsSummary || {};

    return [
      {
        key: "robots",
        label: "robots.txt",
        description: "검색 엔진 크롤러에게 어떤 페이지를 수집할지 알려주는 파일.",
        applied: !!siteFiles.robots?.exists,
        howTo: "사이트 루트 (/robots.txt) 에 User-agent 와 Allow/Disallow 규칙을 작성합니다.",
      },
      {
        key: "sitemap",
        label: "sitemap.xml",
        description: "전체 페이지 목록을 검색 엔진에 제공해 인덱싱을 돕는 파일.",
        applied: !!siteFiles.sitemap?.exists,
        howTo: "/sitemap.xml 에 모든 공개 URL 목록을 XML 형식으로 작성합니다.",
      },
      {
        key: "llms",
        label: "llms.txt",
        description: "AI 가 우리 사이트를 이해하기 쉽도록 핵심 정보를 모은 파일.",
        applied: !!siteFiles.llms?.exists,
        howTo: "/llms.txt 에 브랜드 소개 + 주요 페이지 링크를 markdown 으로 작성합니다.",
      },
      {
        key: "schema",
        label: "구조화 데이터 (Schema.org)",
        description: "JSON-LD 로 페이지 의미를 구조화해 AI 와 검색 엔진의 이해도를 높입니다.",
        applied: !!signals.hasSchema,
        howTo: "주요 페이지에 Organization / Product / FAQPage 등 schema.org JSON-LD 를 추가합니다.",
      },
      {
        key: "ga4",
        label: "GA4 연동",
        description: "Google Analytics 4 로 트래픽과 사용자 행동 데이터를 수집합니다.",
        applied: !!siteDetection.ga4Id,
        howTo: "Google Tag Manager 또는 직접 G-XXXXXX 코드를 head 에 삽입합니다.",
      },
      {
        key: "gtm",
        label: "Google Tag Manager",
        description: "여러 측정 태그를 한 곳에서 관리하는 컨테이너.",
        applied: !!siteDetection.gtmId,
        howTo: "GTM 컨테이너 (GTM-XXXXXX) 코드를 사이트 head 에 삽입합니다.",
      },
      {
        key: "search-console",
        label: "Google Search Console",
        description: "검색 노출 / 클릭 / CTR / 평균 순위 등 검색 데이터 확인.",
        applied: !!dashboardData?.integrations?.searchConsoleDetected,
        howTo: "Search Console 에 사이트를 등록하고 소유권을 확인합니다.",
      },
      {
        key: "naver-analytics",
        label: "네이버 애널리틱스",
        description: "한국 사용자 트래픽 분석 (네이버 검색 유입 위주).",
        applied: !!dashboardData?.integrations?.naverAnalyticsDetected,
        howTo: "네이버 애널리틱스 (analytics.naver.com) 에 사이트 등록 후 추적 코드 삽입.",
      },
    ];
  }, [dashboardData, seoData]);

  const appliedCount = checks.filter((c) => c.applied).length;
  const totalCount = checks.length;

  const appliedMap: EngineAppliedMap = useMemo(() => {
    const find = (key: string) => !!checks.find((c) => c.key === key)?.applied;
    return {
      robots: find("robots"),
      schema: find("schema"),
      llms: find("llms"),
      ga4: find("ga4"),
      searchConsole: find("search-console"),
      sitemap: find("sitemap"),
    };
  }, [checks]);

  return (
    <div className="mx-auto max-w-6xl space-y-6 px-4 py-6">
      <header>
        <div className="text-xs uppercase tracking-[0.28em] text-[var(--shell-text-soft)]">Portal / 기술 관련</div>
        <h1 className="mt-2 text-3xl font-semibold tracking-tight text-[var(--shell-text)]">기술 적용 체크리스트</h1>
        <p className="mt-2 text-sm text-[var(--shell-text-muted)]">
          우리 사이트가 검색 엔진과 AI 답변에 잘 노출되도록 적용되어야 할 기술 항목입니다.
        </p>
      </header>

      {isLoading && (
        <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] px-6 py-12 text-center text-sm text-[var(--shell-text-muted)]">
          불러오는 중입니다...
        </div>
      )}

      {!isLoading && (
        <>
          <section className="rounded-3xl border border-[var(--shell-border)] bg-gradient-to-br from-[var(--shell-panel-strong)] to-[var(--shell-panel)] px-6 py-5">
            <div className="text-[11px] uppercase tracking-[0.22em] text-[var(--shell-text-soft)]">적용 진행률</div>
            <div className="mt-2 flex items-baseline gap-3">
              <div className="text-4xl font-semibold tracking-tight text-[var(--shell-text)]">{appliedCount}</div>
              <div className="text-xl text-[var(--shell-text-muted)]">/ {totalCount}</div>
            </div>
            <div className="mt-3 h-2 w-full overflow-hidden rounded-full bg-[var(--shell-panel-soft)]">
              <div
                className="h-full bg-[var(--shell-accent)] transition-all"
                style={{ width: `${(appliedCount / totalCount) * 100}%` }}
              />
            </div>
          </section>

          <section>
            <div className="mb-3">
              <div className="text-sm font-semibold text-[var(--shell-text)]">AI 엔진별 최적화 가이드</div>
              <div className="mt-1 text-[11px] text-[var(--shell-text-muted)]">
                엔진마다 답변 생성 모델이 다릅니다. 각 엔진별 우선순위에 맞춰 적용해야 효과가 극대화됩니다.
              </div>
            </div>
            <div className="grid gap-3 md:grid-cols-3">
              {ENGINE_GUIDES.map((g) => {
                const total = g.items.length;
                const applied = g.items.filter((it) => appliedMap[it.key]).length;
                return (
                  <div key={g.engine} className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-4">
                    <div className="flex items-center gap-2">
                      <Bot className="h-4 w-4 text-[var(--shell-accent)]" />
                      <span className="text-sm font-semibold text-[var(--shell-text)]">{g.engine}</span>
                      <span className="ml-auto text-[10px] text-[var(--shell-text-soft)]">
                        {applied}/{total}
                      </span>
                    </div>
                    <div className="mt-2 text-[11px] leading-5 text-[var(--shell-text-muted)]">{g.description}</div>
                    <div className="mt-3 h-1.5 w-full overflow-hidden rounded-full bg-[var(--shell-panel-soft)]">
                      <div
                        className={
                          applied === total
                            ? "h-full bg-emerald-500"
                            : applied > 0
                              ? "h-full bg-[var(--shell-accent)]"
                              : "h-full bg-amber-500"
                        }
                        style={{ width: `${(applied / total) * 100}%` }}
                      />
                    </div>
                    <ul className="mt-3 space-y-2">
                      {g.items.map((it, i) => {
                        const ok = appliedMap[it.key];
                        return (
                          <li key={i} className="text-[11px] leading-5">
                            <div className="flex items-start gap-1.5">
                              {ok ? (
                                <CheckCircle2 className="mt-0.5 h-3 w-3 shrink-0 text-emerald-400" />
                              ) : (
                                <Circle className="mt-0.5 h-3 w-3 shrink-0 text-[var(--shell-text-soft)]" />
                              )}
                              <span className={ok ? "text-[var(--shell-text)]" : "text-[var(--shell-text-muted)]"}>
                                {it.label}
                              </span>
                            </div>
                            <div className="ml-4 mt-0.5 text-[10px] text-[var(--shell-text-soft)]">
                              예상 효과: {it.expectedEffect}
                            </div>
                          </li>
                        );
                      })}
                    </ul>
                  </div>
                );
              })}
            </div>
          </section>

          <section className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)]">
            <button
              type="button"
              onClick={() => setShowBasic((v) => !v)}
              className="flex w-full items-center justify-between px-5 py-4 text-left"
            >
              <div>
                <div className="text-sm font-semibold text-[var(--shell-text)]">
                  기본 기술 항목 ({appliedCount}/{totalCount})
                </div>
                <div className="mt-0.5 text-[11px] text-[var(--shell-text-muted)]">
                  robots.txt / sitemap / llms.txt / 구조화 데이터 / GA4 / GTM / Search Console / 네이버 애널리틱스
                </div>
              </div>
              {showBasic ? (
                <ChevronUp className="h-4 w-4 text-[var(--shell-text-soft)]" />
              ) : (
                <ChevronDown className="h-4 w-4 text-[var(--shell-text-soft)]" />
              )}
            </button>
            {showBasic && (
              <div className="space-y-2 px-5 pb-5">
                {checks.map((c) => (
                  <div
                    key={c.key}
                    className={`rounded-xl border p-3 ${
                      c.applied
                        ? "border-emerald-500/30 bg-emerald-500/5"
                        : "border-[var(--shell-border)] bg-[var(--shell-panel-soft)]"
                    }`}
                  >
                    <div className="flex items-start gap-3">
                      {c.applied ? (
                        <CheckCircle2 className="mt-0.5 h-4 w-4 shrink-0 text-emerald-400" />
                      ) : (
                        <Circle className="mt-0.5 h-4 w-4 shrink-0 text-[var(--shell-text-soft)]" />
                      )}
                      <div className="flex-1">
                        <div className="flex items-center gap-2 text-sm font-medium text-[var(--shell-text)]">
                          {c.label}
                          {c.applied ? (
                            <span className="rounded-full bg-emerald-500/15 px-2 py-0.5 text-[10px] text-emerald-300">
                              적용됨
                            </span>
                          ) : (
                            <span className="rounded-full bg-amber-500/15 px-2 py-0.5 text-[10px] text-amber-300">
                              미적용
                            </span>
                          )}
                        </div>
                        <div className="mt-1 text-[11px] leading-5 text-[var(--shell-text-muted)]">
                          {c.description}
                        </div>
                        {!c.applied && c.howTo && (
                          <div className="mt-1.5 rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel)] px-3 py-1.5 text-[10px] leading-5 text-[var(--shell-text)]">
                            <strong className="text-[var(--shell-accent)]">적용 방법:</strong> {c.howTo}
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </section>
        </>
      )}
    </div>
  );
}
