import { useMemo } from "react";
import { AlertTriangle, CheckCircle2 } from "lucide-react";
import { usePortalSeo, usePortalDashboard } from "./dataHub";

const PRIORITY_LABEL: Record<string, string> = {
  high: "우선",
  medium: "보통",
  low: "낮음",
};

const PRIORITY_TONE: Record<string, string> = {
  high: "text-red-300 border-red-500/30 bg-red-500/5",
  medium: "text-amber-300 border-amber-500/30 bg-amber-500/5",
  low: "text-neutral-300 border-neutral-500/30 bg-neutral-500/5",
};

export function PortalWebsite() {
  const { data: seoData, isLoading: seoLoading } = usePortalSeo();
  const { data: dashboardData } = usePortalDashboard();

  const overallScore = seoData?.score ?? dashboardData?.siteHealth?.score ?? 0;
  const categories = seoData?.categories as { seoScore?: number; geoScore?: number } | null;
  const seoScore = categories?.seoScore ?? 0;
  const geoScore = categories?.geoScore ?? 0;

  // Top 5 우선 개선 항목.
  const topIssues = useMemo(() => {
    const recs = seoData?.recommendations || [];
    if (recs.length > 0) {
      return recs
        .slice()
        .sort((a, b) => {
          const order: Record<string, number> = { high: 0, medium: 1, low: 2 };
          return (order[a.priority] ?? 3) - (order[b.priority] ?? 3);
        })
        .slice(0, 5);
    }
    return [];
  }, [seoData]);

  const lowestPages = useMemo(() => {
    const arr = seoData?.pageScores || [];
    return [...arr].sort((a, b) => a.seoScore - b.seoScore).slice(0, 5);
  }, [seoData]);

  return (
    <div className="mx-auto max-w-6xl space-y-6 px-4 py-6">
      <header>
        <div className="text-xs uppercase tracking-[0.28em] text-[var(--shell-text-soft)]">Portal / 웹사이트 분석</div>
        <h1 className="mt-2 text-3xl font-semibold tracking-tight text-[var(--shell-text)]">웹사이트 점수 + 개선 제안</h1>
        <p className="mt-2 text-sm text-[var(--shell-text-muted)]">
          검색 엔진 (SEO) 과 AI 답변 (GEO) 양쪽 관점에서 우리 사이트의 기술 점수와 가장 시급한 개선 항목을 확인합니다.
        </p>
      </header>

      {seoLoading && (
        <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] px-6 py-12 text-center text-sm text-[var(--shell-text-muted)]">
          웹사이트 분석 데이터를 불러오는 중입니다...
        </div>
      )}

      {!seoLoading && (
        <>
          <section className="grid gap-3 md:grid-cols-3">
            <div className="rounded-3xl border border-[var(--shell-border)] bg-gradient-to-br from-[var(--shell-panel-strong)] to-[var(--shell-panel)] px-6 py-5 md:col-span-1">
              <div className="text-[11px] uppercase tracking-[0.22em] text-[var(--shell-text-soft)]">종합 점수</div>
              <div className="mt-2 flex items-baseline gap-2">
                <div className="text-5xl font-semibold tracking-tight text-[var(--shell-text)]">{overallScore}</div>
                <div className="text-xl text-[var(--shell-text-muted)]">/ 100</div>
              </div>
            </div>
            <div className="rounded-3xl border border-[var(--shell-border)] bg-[var(--shell-panel)] px-6 py-5">
              <div className="text-[11px] uppercase tracking-[0.22em] text-[var(--shell-text-soft)]">SEO 점수</div>
              <div className="mt-2 text-3xl font-semibold text-blue-300">{seoScore}</div>
              <div className="mt-1 text-[11px] text-[var(--shell-text-muted)]">Google·Naver 검색 엔진 노출 기반</div>
            </div>
            <div className="rounded-3xl border border-[var(--shell-border)] bg-[var(--shell-panel)] px-6 py-5">
              <div className="text-[11px] uppercase tracking-[0.22em] text-[var(--shell-text-soft)]">GEO 점수</div>
              <div className="mt-2 text-3xl font-semibold text-emerald-300">{geoScore}</div>
              <div className="mt-1 text-[11px] text-[var(--shell-text-muted)]">ChatGPT·Claude·Gemini AI 답변 노출 기반</div>
            </div>
          </section>

          {lowestPages.length > 0 && (
            <section className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
              <div className="text-sm font-semibold text-[var(--shell-text)]">개선이 시급한 페이지 Top 5</div>
              <div className="mt-1 text-[11px] text-[var(--shell-text-soft)]">SEO 점수가 낮은 페이지 순 — 우선 보강 대상</div>
              <ul className="mt-3 space-y-2">
                {lowestPages.map((p, i) => (
                  <li key={i} className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
                    <div className="flex items-center justify-between gap-3">
                      <div className="min-w-0 flex-1">
                        <div className="truncate text-sm text-[var(--shell-text)]">{p.pageTitle || p.path || p.url}</div>
                        <div className="mt-0.5 truncate text-[10px] text-[var(--shell-text-soft)]">{p.url}</div>
                      </div>
                      <div className="shrink-0 text-right">
                        <div className="text-xs text-blue-300">SEO {p.seoScore}</div>
                        <div className="text-xs text-emerald-300">GEO {p.geoScore}</div>
                      </div>
                    </div>
                  </li>
                ))}
              </ul>
            </section>
          )}

          <section className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
            <div className="flex items-center justify-between">
              <div className="text-sm font-semibold text-[var(--shell-text)]">우선 개선 항목 Top 5</div>
            </div>

            {topIssues.length === 0 ? (
              <div className="mt-4 rounded-lg border border-emerald-500/30 bg-emerald-500/5 px-4 py-6 text-center">
                <CheckCircle2 className="mx-auto h-8 w-8 text-emerald-400" />
                <div className="mt-2 text-sm text-emerald-200">현재 우선 개선이 필요한 항목이 없습니다.</div>
              </div>
            ) : (
              <ul className="mt-4 space-y-2.5">
                {topIssues.map((iss, i) => (
                  <li
                    key={i}
                    className={`rounded-xl border bg-[var(--shell-panel-soft)] px-4 py-3 ${PRIORITY_TONE[iss.priority] || ""}`}
                  >
                    <div className="flex items-start gap-3">
                      <AlertTriangle className="h-4 w-4 shrink-0" />
                      <div className="flex-1">
                        <div className="flex items-center gap-2 text-sm font-medium text-[var(--shell-text)]">
                          {iss.label || iss.ruleId}
                          <span className="rounded-full border border-current/40 px-2 py-0.5 text-[10px]">
                            {PRIORITY_LABEL[iss.priority] || iss.priority}
                          </span>
                        </div>
                        {iss.description && (
                          <div className="mt-1 text-xs leading-5 text-[var(--shell-text-muted)]">{iss.description}</div>
                        )}
                        {iss.action && <div className="mt-1 text-[11px] text-[var(--shell-text)]">→ {iss.action}</div>}
                        <div className="mt-1.5 flex items-center gap-3 text-[10px] text-[var(--shell-text-soft)]">
                          <span>예상 점수 +{iss.estimatedPoints || 0}</span>
                          <span>난이도: {iss.effort}</span>
                          <span>적용 페이지 {iss.pageCount || 0}개</span>
                        </div>
                      </div>
                    </div>
                  </li>
                ))}
              </ul>
            )}
          </section>
        </>
      )}
    </div>
  );
}
