import { useEffect, useState } from "react";
import { Save, Plus, X, Star } from "lucide-react";
import { usePortalBrandTruth, useSavePortalBrandTruth } from "./dataHub";
import { KR_REGIONS, SAMPLE_COUNT_PRESETS, type BrandTruth } from "./dataHub/types";

const EMPTY: BrandTruth = {
  canonicalName: "",
  businessSummary: "",
  primaryCategory: "",
  coreOfferings: [],
  positiveKeywords: [],
  negativeKeywords: [],
  mustWinQueries: [],
  importantCompetitors: [],
  measurementCadence: {
    frequency: "weekly",
    runsPerCycle: 1,
    totalSamples: 30,
    runAt: "09:00",
    regionalMode: false,
    regions: [],
  },
};

export function PortalInput() {
  const [draft, setDraft] = useState<BrandTruth>(EMPTY);
  const [feedback, setFeedback] = useState<{ ok: boolean; message: string } | null>(null);

  const { data, isLoading } = usePortalBrandTruth();
  const saveMutation = useSavePortalBrandTruth();
  const isSaving = saveMutation.isPending;

  useEffect(() => {
    if (data?.truth) {
      setDraft({
        ...EMPTY,
        ...data.truth,
        coreOfferings: data.truth.coreOfferings || [],
        positiveKeywords: data.truth.positiveKeywords || [],
        negativeKeywords: data.truth.negativeKeywords || [],
        mustWinQueries: data.truth.mustWinQueries || [],
        importantCompetitors: data.truth.importantCompetitors || [],
        measurementCadence: data.truth.measurementCadence || EMPTY.measurementCadence,
      });
    }
  }, [data]);

  const handleSave = () => {
    setFeedback(null);
    saveMutation.mutate(draft, {
      onSuccess: () => setFeedback({ ok: true, message: "저장되었습니다." }),
      onError: (err) =>
        setFeedback({ ok: false, message: err instanceof Error ? err.message : "저장 실패" }),
    });
  };

  return (
    <div className="mx-auto max-w-6xl space-y-6 px-4 py-6">
      <header>
        <div className="text-xs uppercase tracking-[0.28em] text-[var(--shell-text-soft)]">Portal / 고객 인풋</div>
        <h1 className="mt-2 text-3xl font-semibold tracking-tight text-[var(--shell-text)]">브랜드 정보 입력</h1>
        <p className="mt-2 text-sm text-[var(--shell-text-muted)]">
          브랜드의 기본 정보, 핵심 서비스, 중요 키워드, 꼭 노출되어야 할 검색 쿼리를 입력합니다. 입력 내용은 분석 정확도를 높이고 LLM 컨텍스트로 활용됩니다.
        </p>
      </header>

      {isLoading && (
        <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] px-6 py-12 text-center text-sm text-[var(--shell-text-muted)]">
          불러오는 중입니다...
        </div>
      )}

      {!isLoading && (
        <>
          <section className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
            <div className="space-y-4">
              <FieldText
                label="브랜드명"
                value={draft.canonicalName}
                onChange={(v) => setDraft((d) => ({ ...d, canonicalName: v }))}
                placeholder="ex) 아이노마이즈"
              />
              <FieldText
                label="업종 / 카테고리"
                value={draft.primaryCategory}
                onChange={(v) => setDraft((d) => ({ ...d, primaryCategory: v }))}
                placeholder="ex) AI 마케팅 자동화 SaaS"
              />
              <FieldTextarea
                label="비즈니스 한 줄 설명 (서비스 / 타겟 / 차별점)"
                value={draft.businessSummary}
                onChange={(v) => setDraft((d) => ({ ...d, businessSummary: v }))}
                placeholder="ex) 중소·중견 SaaS 대상 GEO 가시성 측정 · 최적화 통합 플랫폼."
                rows={3}
              />
              <FieldList
                label="핵심 서비스 / 제품 (최대 5개)"
                hint="대표 제품/서비스를 한 줄에 하나씩"
                items={draft.coreOfferings}
                onChange={(items) => setDraft((d) => ({ ...d, coreOfferings: items }))}
                max={5}
                placeholder="제품/서비스명"
              />
              <FieldList
                label="긍정 키워드 (최대 5개)"
                hint="우리 브랜드와 함께 노출되었으면 하는 키워드"
                items={draft.positiveKeywords}
                onChange={(items) => setDraft((d) => ({ ...d, positiveKeywords: items }))}
                max={5}
                placeholder="ex) 국내 최초, 정확도"
              />
              <FieldList
                label="네거티브 키워드 (최대 3개)"
                hint="피해야 할 키워드 / 부정 표현"
                items={draft.negativeKeywords}
                onChange={(items) => setDraft((d) => ({ ...d, negativeKeywords: items }))}
                max={3}
                placeholder="ex) 단순 SEO, 번역기"
              />
              <FieldList
                label="꼭 노출되어야 할 검색 쿼리 (최대 5개)"
                hint="AI 답변에 우리 브랜드가 반드시 포함되어야 할 질문 — GEO 현황·주간 리포트에 별 표시로 우선 반영됩니다"
                items={draft.mustWinQueries}
                onChange={(items) => setDraft((d) => ({ ...d, mustWinQueries: items }))}
                max={5}
                placeholder="ex) AI 마케팅 자동화 추천"
              />
            </div>
          </section>

          <section className="rounded-2xl border-2 border-[var(--shell-accent)]/30 bg-[var(--shell-accent)]/5 p-5">
            <div className="mb-3">
              <div className="flex items-center gap-2 text-sm font-semibold text-[var(--shell-text)]">
                <Star className="h-4 w-4 fill-amber-300 text-amber-300" /> 주요 경쟁사 (최대 5개)
              </div>
              <div className="mt-1 text-[11px] leading-5 text-[var(--shell-text-muted)]">
                AI 답변에서 함께 언급된 횟수와 톤(긍정/부정/중립)을 추적할 경쟁사입니다.
                여기에 입력한 경쟁사는 GEO 현황 · Dashboard · 주간 리포트의 경쟁사 비교에 별 표시로 우선 노출되며,
                자동으로 탐지된 경쟁사는 별 없이 함께 표시됩니다.
              </div>
            </div>
            <FieldList
              label=""
              items={draft.importantCompetitors || []}
              onChange={(items) => setDraft((d) => ({ ...d, importantCompetitors: items }))}
              max={5}
              placeholder="ex) 코드프렌즈, 테크로드"
            />
          </section>

          <section className="rounded-2xl border-2 border-[var(--shell-accent)]/30 bg-[var(--shell-accent)]/5 p-5">
            <div className="mb-3">
              <div className="flex items-center gap-2 text-sm font-semibold text-[var(--shell-text)]">
                <Star className="h-4 w-4 fill-amber-300 text-amber-300" /> 측정 설정 — 모든 측정 옵션을 여기서 한 번에
              </div>
              <div className="mt-1 text-[11px] leading-5 text-[var(--shell-text-muted)]">
                설정한 주기에 맞춰 ChatGPT · Claude · Gemini 에 자동으로 쿼리를 보내고 결과를 추적합니다.
                주기 / 샘플 수 / 시각 / 지역 분산을 한 카드에서 모두 설정할 수 있으며, 다른 메뉴에서 추가 설정할 필요 없습니다.
              </div>
            </div>
            <div className="grid gap-3 md:grid-cols-3">
              <div>
                <label className="mb-1.5 block text-xs font-medium text-[var(--shell-text)]">측정 주기</label>
                <select
                  value={draft.measurementCadence?.frequency || "weekly"}
                  onChange={(e) =>
                    setDraft((d) => ({
                      ...d,
                      measurementCadence: {
                        ...(d.measurementCadence || EMPTY.measurementCadence!),
                        frequency: e.target.value as "daily" | "weekly",
                      },
                    }))
                  }
                  className="w-full rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-2 text-sm text-[var(--shell-text)] outline-none focus:border-[var(--shell-accent)]"
                >
                  <option value="weekly">매주</option>
                  <option value="daily">매일</option>
                </select>
              </div>
              <div>
                <label className="mb-1.5 block text-xs font-medium text-[var(--shell-text)]">총 샘플 수 (한 사이클)</label>
                <select
                  value={draft.measurementCadence?.totalSamples ?? 30}
                  onChange={(e) =>
                    setDraft((d) => ({
                      ...d,
                      measurementCadence: {
                        ...(d.measurementCadence || EMPTY.measurementCadence!),
                        totalSamples: Number(e.target.value),
                      },
                    }))
                  }
                  className="w-full rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-2 text-sm text-[var(--shell-text)] outline-none focus:border-[var(--shell-accent)]"
                >
                  {SAMPLE_COUNT_PRESETS.map((n) => (
                    <option key={n} value={n}>
                      {n}개
                    </option>
                  ))}
                </select>
              </div>
              <div>
                <label className="mb-1.5 block text-xs font-medium text-[var(--shell-text)]">실행 시각 (KST)</label>
                <input
                  type="time"
                  value={draft.measurementCadence?.runAt || "09:00"}
                  onChange={(e) =>
                    setDraft((d) => ({
                      ...d,
                      measurementCadence: {
                        ...(d.measurementCadence || EMPTY.measurementCadence!),
                        runAt: e.target.value,
                      },
                    }))
                  }
                  className="w-full rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-2 text-sm text-[var(--shell-text)] outline-none focus:border-[var(--shell-accent)]"
                />
              </div>
            </div>

            <div className="mt-4 rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel)]/40 p-3">
              <label className="flex cursor-pointer items-center gap-2 text-xs font-medium text-[var(--shell-text)]">
                <input
                  type="checkbox"
                  checked={draft.measurementCadence?.regionalMode === true}
                  onChange={(e) =>
                    setDraft((d) => ({
                      ...d,
                      measurementCadence: {
                        ...(d.measurementCadence || EMPTY.measurementCadence!),
                        regionalMode: e.target.checked,
                      },
                    }))
                  }
                  className="h-4 w-4 rounded border-[var(--shell-border)]"
                />
                지역별 분산 측정 (전체 샘플을 지역에 분산)
              </label>
              <div className="mt-1 text-[10px] leading-5 text-[var(--shell-text-muted)]">
                ON 시 총 샘플을 선택한 광역시·도에 균등 분배해 측정합니다. 여론조사 기관처럼 도단위 분산 결과 확인 가능.
              </div>
              {draft.measurementCadence?.regionalMode && (
                <div className="mt-3">
                  <div className="flex items-center justify-between">
                    <div className="text-[10px] text-[var(--shell-text-soft)]">
                      지역 선택 ({(draft.measurementCadence?.regions || []).length}/17)
                    </div>
                    <div className="flex gap-2">
                      <button
                        type="button"
                        onClick={() =>
                          setDraft((d) => ({
                            ...d,
                            measurementCadence: {
                              ...(d.measurementCadence || EMPTY.measurementCadence!),
                              regions: KR_REGIONS.map((r) => r.code),
                            },
                          }))
                        }
                        className="rounded border border-[var(--shell-border)] px-2 py-0.5 text-[10px] text-[var(--shell-text-muted)] hover:bg-[var(--shell-panel-soft)]"
                      >
                        전체 선택
                      </button>
                      <button
                        type="button"
                        onClick={() =>
                          setDraft((d) => ({
                            ...d,
                            measurementCadence: {
                              ...(d.measurementCadence || EMPTY.measurementCadence!),
                              regions: [],
                            },
                          }))
                        }
                        className="rounded border border-[var(--shell-border)] px-2 py-0.5 text-[10px] text-[var(--shell-text-muted)] hover:bg-[var(--shell-panel-soft)]"
                      >
                        모두 해제
                      </button>
                    </div>
                  </div>
                  <div className="mt-2 grid grid-cols-3 gap-1.5 sm:grid-cols-4 md:grid-cols-5">
                    {KR_REGIONS.map((r) => {
                      const checked = (draft.measurementCadence?.regions || []).includes(r.code);
                      return (
                        <label
                          key={r.code}
                          className={`flex cursor-pointer items-center gap-1.5 rounded border px-2 py-1.5 text-[11px] ${
                            checked
                              ? "border-[var(--shell-accent)]/40 bg-[var(--shell-accent)]/10 text-[var(--shell-text)]"
                              : "border-[var(--shell-border)] text-[var(--shell-text-muted)] hover:bg-[var(--shell-panel-soft)]"
                          }`}
                        >
                          <input
                            type="checkbox"
                            checked={checked}
                            onChange={(e) => {
                              const cur = new Set(draft.measurementCadence?.regions || []);
                              if (e.target.checked) cur.add(r.code);
                              else cur.delete(r.code);
                              setDraft((d) => ({
                                ...d,
                                measurementCadence: {
                                  ...(d.measurementCadence || EMPTY.measurementCadence!),
                                  regions: [...cur],
                                },
                              }));
                            }}
                            className="h-3 w-3"
                          />
                          <span className="truncate">{r.name}</span>
                        </label>
                      );
                    })}
                  </div>
                </div>
              )}
            </div>
          </section>

          <div className="flex items-center justify-between gap-3">
            <button
              type="button"
              onClick={handleSave}
              disabled={isSaving}
              className="flex items-center gap-2 rounded-xl bg-[var(--shell-accent)] px-5 py-2.5 text-sm font-medium text-white hover:opacity-90 disabled:opacity-50"
            >
              <Save className="h-4 w-4" />
              {isSaving ? "저장 중..." : "저장"}
            </button>
            {(() => {
              const raw = data?.truth?.updatedAt as unknown;
              if (!raw) return null;
              let date: Date | null = null;
              if (raw instanceof Date) date = raw;
              else if (typeof raw === "object" && raw !== null && typeof (raw as { toDate?: () => Date }).toDate === "function") {
                date = (raw as { toDate: () => Date }).toDate();
              } else if (typeof raw === "object" && raw !== null && "seconds" in (raw as Record<string, unknown>)) {
                const secs = (raw as { seconds: number }).seconds;
                date = new Date(secs * 1000);
              } else if (typeof raw === "string" || typeof raw === "number") {
                date = new Date(raw);
              }
              if (!date || Number.isNaN(date.getTime())) return null;
              return (
                <div className="text-[11px] text-[var(--shell-text-soft)]">
                  마지막 저장: {date.toLocaleString()}
                </div>
              );
            })()}
          </div>

          {feedback && (
            <div
              className={`rounded-xl border px-4 py-3 text-sm ${
                feedback.ok
                  ? "border-emerald-500/30 bg-emerald-500/5 text-emerald-200"
                  : "border-red-500/30 bg-red-500/5 text-red-200"
              }`}
            >
              {feedback.message}
            </div>
          )}
        </>
      )}
    </div>
  );
}

function FieldText({
  label,
  value,
  onChange,
  placeholder,
}: {
  label: string;
  value: string;
  onChange: (v: string) => void;
  placeholder?: string;
}) {
  return (
    <div>
      <label className="mb-1.5 block text-xs font-medium text-[var(--shell-text)]">{label}</label>
      <input
        type="text"
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        className="w-full rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-2 text-sm text-[var(--shell-text)] placeholder-[var(--shell-text-soft)] outline-none focus:border-[var(--shell-accent)]"
      />
    </div>
  );
}

function FieldTextarea({
  label,
  value,
  onChange,
  placeholder,
  rows = 3,
}: {
  label: string;
  value: string;
  onChange: (v: string) => void;
  placeholder?: string;
  rows?: number;
}) {
  return (
    <div>
      <label className="mb-1.5 block text-xs font-medium text-[var(--shell-text)]">{label}</label>
      <textarea
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        rows={rows}
        className="w-full rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-2 text-sm text-[var(--shell-text)] placeholder-[var(--shell-text-soft)] outline-none focus:border-[var(--shell-accent)]"
      />
    </div>
  );
}

function FieldList({
  label,
  hint,
  items,
  onChange,
  max,
  placeholder,
}: {
  label: string;
  hint?: string;
  items: string[];
  onChange: (items: string[]) => void;
  max: number;
  placeholder?: string;
}) {
  const [input, setInput] = useState("");
  const add = () => {
    const v = input.trim();
    if (!v || items.includes(v) || items.length >= max) return;
    onChange([...items, v]);
    setInput("");
  };

  return (
    <div>
      <div className="mb-1.5 flex items-center justify-between">
        <label className="text-xs font-medium text-[var(--shell-text)]">{label}</label>
        <span className="text-[10px] text-[var(--shell-text-soft)]">
          {items.length} / {max}
        </span>
      </div>
      {hint && <div className="mb-1.5 text-[10px] text-[var(--shell-text-muted)]">{hint}</div>}
      <div className="mb-2 flex flex-wrap gap-1.5">
        {items.map((it, i) => (
          <span
            key={i}
            className="inline-flex items-center gap-1 rounded-full bg-[var(--shell-accent)]/15 px-3 py-1 text-xs text-[var(--shell-text)]"
          >
            {it}
            <button
              type="button"
              onClick={() => onChange(items.filter((_, j) => j !== i))}
              className="text-[var(--shell-text-soft)] hover:text-red-300"
            >
              <X className="h-3 w-3" />
            </button>
          </span>
        ))}
      </div>
      <div className="flex items-center gap-2">
        <input
          type="text"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter") {
              e.preventDefault();
              add();
            }
          }}
          placeholder={placeholder}
          disabled={items.length >= max}
          className="flex-1 rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-1.5 text-xs text-[var(--shell-text)] placeholder-[var(--shell-text-soft)] outline-none focus:border-[var(--shell-accent)] disabled:opacity-50"
        />
        <button
          type="button"
          onClick={add}
          disabled={!input.trim() || items.length >= max}
          className="rounded-lg border border-[var(--shell-border)] px-3 py-1.5 text-xs text-[var(--shell-text)] hover:bg-[var(--shell-panel-soft)] disabled:opacity-50"
        >
          <Plus className="h-3 w-3" />
        </button>
      </div>
    </div>
  );
}
