import { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import { CheckCircle2, ListTodo, Rocket } from "lucide-react";
import { listActionRuns } from "../../../db/boards";
import { MetricCard } from "../../../components/shared/MetricCard";
import { EmptyState } from "../../../components/shared/EmptyState";

interface ActionRun {
  id: string;
  title?: string;
  platform?: string;
  status?: string;
  publishedAt?: string;
  url?: string;
  createdAt?: string;
}

function useActionRuns() {
  const { id } = useParams<{ id: string }>();
  const [runs, setRuns] = useState<ActionRun[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!id) return;
    setLoading(true);
    listActionRuns(id).catch(() => []).then((data) => {
      setRuns(data as ActionRun[]);
      setLoading(false);
    });
  }, [id]);

  return { runs, loading };
}

// ── Deploy Queue ───────────────────────────────────────────

export function DeployQueue() {
  const { runs, loading } = useActionRuns();

  if (loading) return <Loading />;

  const published = runs.filter((r) => r.status === "published");
  const failed = runs.filter((r) => r.status === "failed");
  const pending = runs.filter((r) => r.status !== "published" && r.status !== "failed");

  return (
    <div className="space-y-6">
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <MetricCard icon={Rocket} label="Total Deploys" value={String(runs.length)} color="text-blue-600" />
        <MetricCard icon={Rocket} label="Published" value={String(published.length)} color="text-emerald-600" />
        <MetricCard icon={Rocket} label="Pending" value={String(pending.length)} color="text-amber-500" />
        <MetricCard icon={Rocket} label="Failed" value={String(failed.length)} color="text-rose-500" />
      </div>

      {runs.length > 0 ? (
        <div className="overflow-x-auto rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)]">
          <table className="w-full text-left text-sm">
            <thead>
              <tr className="border-b border-[var(--shell-border)] text-[10px] uppercase tracking-wider text-[var(--shell-text-muted)]">
                <th className="px-4 py-3 font-medium">Title</th>
                <th className="px-4 py-3 font-medium">Platform</th>
                <th className="px-4 py-3 font-medium">Status</th>
                <th className="px-4 py-3 font-medium">Published</th>
              </tr>
            </thead>
            <tbody>
              {runs.map((run) => (
                <tr key={run.id} className="border-b border-[var(--shell-border)]/50 transition-colors hover:bg-[var(--shell-panel-soft)]">
                  <td className="px-4 py-2.5 text-[var(--shell-text)]">
                    {run.url ? (
                      <a href={run.url} target="_blank" rel="noopener noreferrer" className="text-[var(--shell-accent)] hover:underline">{run.title || run.id}</a>
                    ) : (
                      run.title || run.id
                    )}
                  </td>
                  <td className="px-4 py-2.5 text-[var(--shell-text-muted)]">{run.platform || "--"}</td>
                  <td className="px-4 py-2.5">
                    <StatusPill status={run.status || "pending"} />
                  </td>
                  <td className="whitespace-nowrap px-4 py-2.5 text-xs text-[var(--shell-text-muted)]">
                    {run.publishedAt ? String(run.publishedAt).slice(0, 16).replace("T", " ") : "--"}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      ) : (
        <EmptyState icon={Rocket} title="No deploy history" description="배포된 콘텐츠가 여기에 표시됩니다" />
      )}
    </div>
  );
}

// ── Work Queue ─────────────────────────────────────────────

export function WorkQueue() {
  const { runs, loading } = useActionRuns();

  if (loading) return <Loading />;

  const active = runs.filter((r) => r.status === "running" || r.status === "pending" || r.status === "queued");
  const waiting = runs.filter((r) => !r.status || r.status === "waiting" || r.status === "scheduled");

  return (
    <div className="space-y-6">
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
        <MetricCard icon={ListTodo} label="Active" value={String(active.length)} color="text-amber-500" />
        <MetricCard icon={ListTodo} label="Waiting" value={String(waiting.length)} color="text-blue-600" />
        <MetricCard icon={ListTodo} label="Total Queue" value={String(active.length + waiting.length)} color="text-cyan-600" />
      </div>

      {active.length > 0 ? (
        <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
          <h3 className="text-sm font-semibold text-[var(--shell-text)]">Active Work Items</h3>
          <div className="mt-3 space-y-2">
            {active.map((r) => (
              <div key={r.id} className="flex items-center justify-between rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
                <div className="min-w-0">
                  <p className="truncate text-sm text-[var(--shell-text)]">{r.title || r.id}</p>
                  {r.platform && <p className="mt-0.5 text-[10px] text-[var(--shell-text-muted)]">{r.platform}</p>}
                </div>
                <StatusPill status={r.status || "running"} />
              </div>
            ))}
          </div>
        </div>
      ) : (
        <EmptyState icon={ListTodo} title="No active work items" description="실행 중이거나 대기 중인 작업이 여기에 표시됩니다" />
      )}

      {waiting.length > 0 && (
        <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
          <h3 className="text-sm font-semibold text-[var(--shell-text)]">Waiting ({waiting.length})</h3>
          <div className="mt-3 space-y-2">
            {waiting.map((r) => (
              <div key={r.id} className="flex items-center justify-between rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
                <p className="truncate text-sm text-[var(--shell-text)]">{r.title || r.id}</p>
                <StatusPill status={r.status || "waiting"} />
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

// ── Completed ──────────────────────────────────────────────

export function Completed() {
  const { runs, loading } = useActionRuns();

  if (loading) return <Loading />;

  const completed = runs.filter((r) => r.status === "done" || r.status === "complete" || r.status === "completed" || r.status === "published");

  return (
    <div className="space-y-6">
      <div className="grid gap-4 sm:grid-cols-2">
        <MetricCard icon={CheckCircle2} label="Completed Actions" value={String(completed.length)} color="text-emerald-600" />
        <MetricCard icon={CheckCircle2} label="Total Runs" value={String(runs.length)} color="text-blue-600" />
      </div>

      {completed.length > 0 ? (
        <div className="overflow-x-auto rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)]">
          <table className="w-full text-left text-sm">
            <thead>
              <tr className="border-b border-[var(--shell-border)] text-[10px] uppercase tracking-wider text-[var(--shell-text-muted)]">
                <th className="px-4 py-3 font-medium">Title</th>
                <th className="px-4 py-3 font-medium">Platform</th>
                <th className="px-4 py-3 font-medium">Status</th>
                <th className="px-4 py-3 font-medium">Date</th>
              </tr>
            </thead>
            <tbody>
              {completed.map((run) => (
                <tr key={run.id} className="border-b border-[var(--shell-border)]/50 transition-colors hover:bg-[var(--shell-panel-soft)]">
                  <td className="px-4 py-2.5 text-[var(--shell-text)]">
                    {run.url ? (
                      <a href={run.url} target="_blank" rel="noopener noreferrer" className="text-[var(--shell-accent)] hover:underline">{run.title || run.id}</a>
                    ) : (
                      run.title || run.id
                    )}
                  </td>
                  <td className="px-4 py-2.5 text-[var(--shell-text-muted)]">{run.platform || "--"}</td>
                  <td className="px-4 py-2.5"><StatusPill status={run.status || "done"} /></td>
                  <td className="whitespace-nowrap px-4 py-2.5 text-xs text-[var(--shell-text-muted)]">
                    {run.publishedAt ? String(run.publishedAt).slice(0, 16).replace("T", " ") : run.createdAt ? String(run.createdAt).slice(0, 16).replace("T", " ") : "--"}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      ) : (
        <EmptyState icon={CheckCircle2} title="No completed actions" description="완료된 액션은 여기에 보관됩니다" />
      )}
    </div>
  );
}

// ── Shared ──────────────────────────────────────────────────

function StatusPill({ status }: { status: string }) {
  const style = status === "done" || status === "complete" || status === "completed" || status === "published"
    ? "bg-emerald-500/10 text-emerald-600"
    : status === "running" || status === "pending" || status === "queued"
      ? "bg-amber-500/10 text-amber-500"
      : status === "failed"
        ? "bg-rose-500/10 text-rose-500"
        : "bg-[var(--shell-panel-soft)] text-[var(--shell-text-muted)]";
  return <span className={`rounded-md px-2 py-0.5 text-[10px] font-medium ${style}`}>{status}</span>;
}

function Loading() {
  return <div className="flex min-h-[30vh] items-center justify-center text-sm text-[var(--shell-text-muted)]">Loading...</div>;
}
