import { useMemo } from "react";
import { ArrowUpRight, ArrowDownRight, Minus, Calendar, CheckCircle2, AlertCircle, Lightbulb, Target, Info } from "lucide-react";
import { usePortalWeeklyReport, usePortalTrendSnapshots, usePortalActions, usePortalSentiment } from "./dataHub";

function deltaIcon(delta: number) {
  if (delta > 0.5) return <ArrowUpRight className="h-4 w-4 text-emerald-400" />;
  if (delta < -0.5) return <ArrowDownRight className="h-4 w-4 text-red-400" />;
  return <Minus className="h-4 w-4 text-neutral-400" />;
}

function formatDelta(delta: number, suffix: string = "%p") {
  const sign = delta > 0 ? "+" : "";
  return `${sign}${delta.toFixed(1)}${suffix}`;
}

export function PortalWeeklyReport() {
  const { data: reportData, isLoading } = usePortalWeeklyReport();
  const { data: snapshotsData } = usePortalTrendSnapshots();
  const { data: actionsData } = usePortalActions();
  const { data: sentimentData } = usePortalSentiment();

  const report = reportData?.report;
  const snapshots = snapshotsData?.snapshots || [];
  const actions = actionsData?.actions || [];
  const structured = actionsData?.structuredActions || [];
  const sentiment = sentimentData?.summary;

  const trendline = useMemo(() => {
    return snapshots
      .slice(0, 6)
      .reverse()
      .map((s) => ({
        date: new Date(s.capturedAt).toLocaleDateString(),
        score: s.metrics?.visibilityScore || 0,
      }));
  }, [snapshots]);
  const maxScore = Math.max(100, ...trendline.map((t) => t.score));

  const completedThisWeek = useMemo(() => {
    const cutoff = Date.now() - 7 * 24 * 60 * 60 * 1000;
    return actions
      .filter((a) => {
        if (!a.completedAt) return false;
        const t = new Date(a.completedAt).getTime();
        return t >= cutoff;
      })
      .slice(0, 5);
  }, [actions]);

  const upcoming = useMemo(() => {
    return actions
      .filter((a) => a.status !== "completed" && !a.completedAt)
      .sort((a, b) => {
        const order: Record<string, number> = { high: 0, medium: 1, low: 2, urgent: -1 };
        return (order[a.priority] ?? 3) - (order[b.priority] ?? 3);
      })
      .slice(0, 5);
  }, [actions]);

  const recommendations = useMemo(() => {
    const recs: Array<{ title: string; rationale: string; expectedEffect: string; tier: "P0" | "P1" | "P2" }> = [];
    if (report) {
      if (report.weeklyChange.mentionRateDelta < -1) {
        recs.push({
          tier: "P0",
          title: "AI 답변 언급률 하락 — 신규 콘텐츠 + 외부 신뢰소스 보강",
          rationale: `이번 주 언급률이 ${formatDelta(report.weeklyChange.mentionRateDelta)} 감소했습니다. AI 가 답변을 만들 때 참고하는 외부 신뢰소스(위키·언론·전문 커뮤니티)를 확대하는 것이 가장 빠른 회복 경로입니다.`,
          expectedEffect: "1~2주 내 언급률 +3~5%p 회복 가능",
        });
      }
      if (report.weeklyChange.mentionRateDelta > 1) {
        recs.push({
          tier: "P1",
          title: "언급률 상승세 — 콘텐츠 패턴을 유지·확장",
          rationale: `언급률이 ${formatDelta(report.weeklyChange.mentionRateDelta)} 상승했습니다. 최근 게시한 콘텐츠 / 외부 노출 활동의 어떤 패턴이 효과적이었는지 분석해 다음 주에 반복 시도하세요.`,
          expectedEffect: "한 달 내 추가 +5~8%p 가능",
        });
      }
      const lowEngines = (report.globalEngine.engines || []).filter((e) => e.mentionRate < 20);
      if (lowEngines.length > 0) {
        recs.push({
          tier: "P1",
          title: `${lowEngines.map((e) => e.engine).join(" / ")} 언급률 < 20% — 엔진별 노출 전략 분리`,
          rationale: `엔진마다 답변 생성 모델이 다릅니다. 특히 출처 인용 패턴과 가중치가 달라서, 약한 엔진별로 어떤 출처가 자주 인용되는지 별도 분석이 필요합니다.`,
          expectedEffect: "약한 엔진 언급률 10%p+ 상승 가능",
        });
      }
      if (report.competitors && report.competitors.length > 0) {
        const top = report.competitors[0];
        if (top.mentionCount > 5) {
          recs.push({
            tier: "P0",
            title: `경쟁사 ${top.name} 언급 ${top.mentionCount}회 — 차별화 메시지 보강`,
            rationale: `경쟁사가 AI 답변에서 더 자주 언급됩니다. 우리만의 강점 (USP) 을 명확히 드러내는 비교 콘텐츠 / 사용자 후기 / 성능 데이터가 우선 보강 대상입니다.`,
            expectedEffect: "Share of Voice +5~10%p",
          });
        }
      }
    }
    if (sentiment) {
      const total =
        sentiment.brandBreakdown.positive + sentiment.brandBreakdown.negative + sentiment.brandBreakdown.neutral;
      if (total > 0) {
        const negPct = sentiment.brandBreakdown.negative / total;
        if (negPct > 0.15) {
          recs.push({
            tier: "P0",
            title: `부정 답변 비율 ${Math.round(negPct * 100)}% — 답변 본문 점검 + 반박 콘텐츠`,
            rationale: `답변 톤 분석에서 부정적 톤이 ${Math.round(negPct * 100)}% 입니다. 어떤 쿼리에서 부정 톤이 나오는지 GEO 현황 '주요 답변' 탭에서 확인하고, 해당 쿼리에 대응하는 FAQ / 교정 콘텐츠를 우선 작성하세요.`,
            expectedEffect: "부정 비율 5%p+ 감소 + 신뢰도 회복",
          });
        }
        const posPct = sentiment.brandBreakdown.positive / total;
        if (posPct > 0.5) {
          recs.push({
            tier: "P2",
            title: `긍정 답변 ${Math.round(posPct * 100)}% — 추천 메시지를 owned 채널에 재활용`,
            rationale: `AI 가 우리 브랜드를 추천하는 톤이 ${Math.round(posPct * 100)}% 입니다. 그 답변에 자주 등장하는 표현을 자체 SNS / 홈페이지 FAQ 에 그대로 반영하면 일관된 메시지로 강화됩니다.`,
            expectedEffect: "전환율 + 브랜드 일관성 향상",
          });
        }
      }
    }
    return recs.slice(0, 6);
  }, [report, sentiment]);

  return (
    <div className="mx-auto max-w-6xl space-y-6 px-4 py-6">
      <header>
        <div className="text-xs uppercase tracking-[0.28em] text-[var(--shell-text-soft)]">Portal / 주간 리포트</div>
        <h1 className="mt-2 text-3xl font-semibold tracking-tight text-[var(--shell-text)]">이번 주 GEO 변화 + 다음 주 액션</h1>
        <p className="mt-2 text-sm text-[var(--shell-text-muted)]">
          지난주 대비 점수 변화 → 원인 분석 (긍정·부정·중립 톤) → 이번 주 한 일 → 다음 주 추천 액션 순으로 정리합니다.
        </p>
      </header>

      {isLoading && (
        <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] px-6 py-12 text-center text-sm text-[var(--shell-text-muted)]">
          리포트를 생성하는 중입니다...
        </div>
      )}

      {!isLoading && !report && (
        <div className="rounded-2xl border border-amber-500/30 bg-amber-500/5 px-6 py-8 text-sm text-amber-200">
          아직 첫 번째 주간 리포트가 생성되지 않았습니다. 측정이 진행되면 자동으로 표시됩니다.
        </div>
      )}

      {report && (
        <>
          <section className="rounded-3xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-6">
            <div className="flex items-center gap-2 text-[11px] uppercase tracking-[0.22em] text-[var(--shell-text-soft)]">
              <Calendar className="h-3.5 w-3.5" />
              {new Date(report.periodStart).toLocaleDateString()} ~ {new Date(report.periodEnd).toLocaleDateString()}
            </div>
            <h2 className="mt-3 text-xl font-semibold leading-7 text-[var(--shell-text)]">{report.summary.headline}</h2>
            {report.summary.overview && report.summary.overview.length > 0 && (
              <ul className="mt-4 space-y-1.5 text-sm leading-6 text-[var(--shell-text-muted)]">
                {report.summary.overview.slice(0, 4).map((line, i) => (
                  <li key={i} className="flex items-start gap-2">
                    <span className="mt-2 inline-block h-1.5 w-1.5 shrink-0 rounded-full bg-[var(--shell-accent)]" />
                    <span>{line}</span>
                  </li>
                ))}
              </ul>
            )}
          </section>

          <section className="grid gap-3 md:grid-cols-2 lg:grid-cols-4">
            <DeltaCard label="언급률 변화" delta={report.weeklyChange.mentionRateDelta} />
            <DeltaCard label="노출률 변화" delta={report.weeklyChange.exposureRateDelta} />
            <DeltaCard label="가중 언급률 변화" delta={report.weeklyChange.weightedMentionRateDelta} />
            <DeltaCard label="언급 수 변화" delta={report.weeklyChange.mentionCountDelta} suffix="회" />
          </section>

          <section className="grid gap-4 lg:grid-cols-2">
            {sentiment ? (
              <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
                <div className="text-sm font-semibold text-[var(--shell-text)]">답변 톤 분석</div>
                <div className="mt-3 text-xs text-[var(--shell-text-muted)]">
                  {sentiment.totalProbesAnalyzed}개 답변 기준
                </div>
                {(() => {
                  const total =
                    sentiment.brandBreakdown.positive +
                    sentiment.brandBreakdown.negative +
                    sentiment.brandBreakdown.neutral +
                    sentiment.brandBreakdown.unknown;
                  if (total === 0) return <div className="mt-3 text-xs text-amber-300">분석된 데이터 없음</div>;
                  return (
                    <>
                      <div className="mt-3 flex h-3 overflow-hidden rounded-full">
                        <div
                          className="bg-emerald-500"
                          style={{ width: `${(sentiment.brandBreakdown.positive / total) * 100}%` }}
                        />
                        <div
                          className="bg-blue-500"
                          style={{ width: `${(sentiment.brandBreakdown.neutral / total) * 100}%` }}
                        />
                        <div
                          className="bg-red-500"
                          style={{ width: `${(sentiment.brandBreakdown.negative / total) * 100}%` }}
                        />
                        <div
                          className="bg-neutral-500"
                          style={{ width: `${(sentiment.brandBreakdown.unknown / total) * 100}%` }}
                        />
                      </div>
                      <div className="mt-3 grid grid-cols-3 gap-2 text-xs">
                        <div className="rounded-lg bg-emerald-500/5 px-3 py-2 text-emerald-300">
                          <div className="text-[10px] text-emerald-300/70">긍정</div>
                          <div className="text-lg font-semibold">{sentiment.brandBreakdown.positive}</div>
                        </div>
                        <div className="rounded-lg bg-blue-500/5 px-3 py-2 text-blue-300">
                          <div className="text-[10px] text-blue-300/70">중립</div>
                          <div className="text-lg font-semibold">{sentiment.brandBreakdown.neutral}</div>
                        </div>
                        <div className="rounded-lg bg-red-500/5 px-3 py-2 text-red-300">
                          <div className="text-[10px] text-red-300/70">부정</div>
                          <div className="text-lg font-semibold">{sentiment.brandBreakdown.negative}</div>
                        </div>
                      </div>

                      <div className="mt-4 space-y-2">
                        {sentiment.topAnswers.positive[0] && (
                          <div className="rounded-lg border border-emerald-500/30 bg-emerald-500/5 px-3 py-2">
                            <div className="text-[10px] text-emerald-300/80">긍정 대표 답변</div>
                            <div className="mt-1 line-clamp-2 text-[11px] leading-5 text-[var(--shell-text)]">
                              "{sentiment.topAnswers.positive[0].excerpt}"
                            </div>
                          </div>
                        )}
                        {sentiment.topAnswers.negative[0] && (
                          <div className="rounded-lg border border-red-500/30 bg-red-500/5 px-3 py-2">
                            <div className="text-[10px] text-red-300/80">부정 대표 답변</div>
                            <div className="mt-1 line-clamp-2 text-[11px] leading-5 text-[var(--shell-text)]">
                              "{sentiment.topAnswers.negative[0].excerpt}"
                            </div>
                          </div>
                        )}
                        {sentiment.topAnswers.neutral[0] && (
                          <div className="rounded-lg border border-blue-500/30 bg-blue-500/5 px-3 py-2">
                            <div className="text-[10px] text-blue-300/80">중립 대표 답변</div>
                            <div className="mt-1 line-clamp-2 text-[11px] leading-5 text-[var(--shell-text)]">
                              "{sentiment.topAnswers.neutral[0].excerpt}"
                            </div>
                          </div>
                        )}
                      </div>
                    </>
                  );
                })()}
              </div>
            ) : (
              <div className="rounded-2xl border border-amber-500/30 bg-amber-500/5 p-5 text-xs text-amber-200">
                답변 톤(긍정/부정/중립) 분석이 아직 실행되지 않았습니다. GEO 현황 페이지에서 'sentiment 분석 실행' 버튼을 눌러주세요.
              </div>
            )}
            {trendline.length >= 2 && (
              <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
                <div className="text-sm font-semibold text-[var(--shell-text)]">최근 가시성 추이</div>
                <div className="mt-4 flex h-32 items-end gap-2">
                  {trendline.map((t, i) => {
                    const heightPct = maxScore > 0 ? (t.score / maxScore) * 100 : 0;
                    return (
                      <div key={i} className="flex flex-1 flex-col items-center gap-1">
                        <div
                          className="w-full rounded-t bg-[var(--shell-accent)] transition-all"
                          style={{ height: `${heightPct}%`, minHeight: "4px" }}
                        />
                        <div className="text-[9px] text-[var(--shell-text-soft)]">{t.score}</div>
                        <div className="text-[9px] text-[var(--shell-text-soft)]">{t.date.slice(5)}</div>
                      </div>
                    );
                  })}
                </div>
              </div>
            )}
          </section>

          <section className="grid gap-4 lg:grid-cols-2">
            <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
              <div className="flex items-center gap-2 text-sm font-semibold text-[var(--shell-text)]">
                <CheckCircle2 className="h-4 w-4 text-emerald-400" /> 이번 주 한 일 ({completedThisWeek.length})
              </div>
              {completedThisWeek.length === 0 ? (
                <div className="mt-3 text-xs text-[var(--shell-text-muted)]">최근 7일 동안 완료된 액션이 없습니다.</div>
              ) : (
                <ul className="mt-3 space-y-2 text-sm text-[var(--shell-text)]">
                  {completedThisWeek.map((a, i) => (
                    <li key={i} className="rounded-lg bg-emerald-500/5 px-3 py-2">
                      <div className="flex items-start gap-2">
                        <CheckCircle2 className="mt-0.5 h-3.5 w-3.5 shrink-0 text-emerald-400" />
                        <div className="flex-1">
                          <div>{a.title || a.identifier}</div>
                          {a.completedAt && (
                            <div className="mt-0.5 text-[10px] text-[var(--shell-text-soft)]">
                              완료: {new Date(a.completedAt).toLocaleDateString()}
                            </div>
                          )}
                        </div>
                      </div>
                    </li>
                  ))}
                </ul>
              )}
            </div>
            <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
              <div className="flex items-center gap-2 text-sm font-semibold text-[var(--shell-text)]">
                <Target className="h-4 w-4 text-blue-400" /> 다음 주 할 일 ({upcoming.length})
              </div>
              {upcoming.length === 0 ? (
                <div className="mt-3 text-xs text-[var(--shell-text-muted)]">예정된 액션이 없습니다.</div>
              ) : (
                <ul className="mt-3 space-y-2 text-sm text-[var(--shell-text)]">
                  {upcoming.map((a, i) => (
                    <li key={i} className="rounded-lg bg-blue-500/5 px-3 py-2">
                      <div className="flex items-start gap-2">
                        <span className="mt-1 inline-block h-1.5 w-1.5 shrink-0 rounded-full bg-blue-400" />
                        <div className="flex-1">
                          <div>{a.title || a.identifier}</div>
                          <div className="mt-0.5 text-[10px] text-[var(--shell-text-soft)]">
                            우선순위: {a.priority || "보통"}
                          </div>
                        </div>
                      </div>
                    </li>
                  ))}
                </ul>
              )}
            </div>
          </section>

          <section className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
            <div className="flex items-center gap-2 text-sm font-semibold text-[var(--shell-text)]">
              <Lightbulb className="h-4 w-4 text-amber-400" /> 다음 단계 추천 — 이번 주 신호 기반
            </div>
            <div className="mt-1 text-[11px] text-[var(--shell-text-soft)]">
              이번 주의 점수 변화 · 답변 톤 · 경쟁사 신호를 종합해 자동 합성한 권고입니다. P0 (즉시 1-2주) / P1 (단기 1개월) / P2 (중기 분기) 로 구분.
              Dashboard 의 '다음 액션' 은 현재 시점의 상시 우선순위 — 두 페이지의 권고는 보완 관계.
            </div>
            {recommendations.length === 0 ? (
              <div className="mt-3 rounded-lg border border-emerald-500/30 bg-emerald-500/5 px-3 py-3 text-xs text-emerald-200">
                현재 데이터 기준으로 추가 권고 사항이 없습니다. 안정적인 상태를 유지하세요.
              </div>
            ) : (
              <div className="mt-3 space-y-3">
                {(["P0", "P1", "P2"] as const).map((tier) => {
                  const items = recommendations.filter((r) => r.tier === tier);
                  if (items.length === 0) return null;
                  const tierStyle =
                    tier === "P0"
                      ? {
                          tag: "bg-red-500/15 text-red-300 border-red-500/40",
                          label: "P0 · 즉시 (1-2주)",
                          border: "border-red-500/30 bg-red-500/5",
                        }
                      : tier === "P1"
                        ? {
                            tag: "bg-amber-500/15 text-amber-300 border-amber-500/40",
                            label: "P1 · 단기 (1개월)",
                            border: "border-amber-500/30 bg-amber-500/5",
                          }
                        : {
                            tag: "bg-blue-500/15 text-blue-300 border-blue-500/40",
                            label: "P2 · 중기 (분기)",
                            border: "border-blue-500/30 bg-blue-500/5",
                          };
                  return (
                    <div key={tier}>
                      <div className={`mb-2 inline-flex rounded-full border px-3 py-0.5 text-[11px] font-semibold ${tierStyle.tag}`}>
                        {tierStyle.label}
                      </div>
                      <ol className="space-y-2">
                        {items.map((r, i) => (
                          <li key={i} className={`rounded-xl border p-3 ${tierStyle.border}`}>
                            <div className="flex items-start gap-3">
                              <AlertCircle className="mt-0.5 h-4 w-4 shrink-0" />
                              <div className="flex-1">
                                <div className="text-sm font-medium text-[var(--shell-text)]">{r.title}</div>
                                <div className="mt-1 text-xs leading-5 text-[var(--shell-text-muted)]">{r.rationale}</div>
                                <div className="mt-1.5 inline-flex items-center gap-1.5 rounded bg-[var(--shell-panel)] px-2 py-1 text-[10px] text-[var(--shell-text)]">
                                  <span className="text-[var(--shell-accent)]">예상 효과:</span> {r.expectedEffect}
                                </div>
                              </div>
                            </div>
                          </li>
                        ))}
                      </ol>
                    </div>
                  );
                })}
              </div>
            )}
            {structured.length > 0 && (
              <div className="mt-4 flex items-center gap-1.5 text-[11px] text-[var(--shell-text-soft)]">
                <Info className="h-3 w-3" />
                '액션 진행일정' 메뉴에서 전체 {structured.length}개의 구조화된 액션 항목을 확인할 수 있습니다.
              </div>
            )}
          </section>

          {report.globalEngine?.engines && report.globalEngine.engines.length > 0 && (
            <section className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
              <div className="text-sm font-semibold text-[var(--shell-text)]">엔진별 가시성 (참고)</div>
              <ul className="mt-3 space-y-2">
                {report.globalEngine.engines.map((e, i) => (
                  <li
                    key={i}
                    className="flex items-center justify-between rounded-lg bg-[var(--shell-panel-soft)] px-3 py-2"
                  >
                    <span className="text-sm capitalize text-[var(--shell-text)]">{e.engine}</span>
                    <span className="text-xs text-[var(--shell-text-muted)]">
                      언급 {e.mentionRate}% · 노출 {e.exposureRate}% ({e.mentionedCount}/{e.totalQuestions})
                    </span>
                  </li>
                ))}
              </ul>
            </section>
          )}

          {report.competitors && report.competitors.length > 0 && (
            <section className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
              <div className="text-sm font-semibold text-[var(--shell-text)]">경쟁사 언급 빈도</div>
              <div className="mt-1 text-[11px] text-[var(--shell-text-soft)]">
                AI 답변에서 경쟁사 이름이 등장한 횟수와 답변 톤 분포 (sentiment 분석 후 표시).
              </div>
              <ul className="mt-3 space-y-2">
                {report.competitors.slice(0, 8).map((c, i) => {
                  const norm = (s: string) => s.trim().toLowerCase().replace(/[\s.\-_,()[\]]/g, "");
                  const sentMatch = sentiment?.competitors?.find((sc) => norm(sc.name) === norm(c.name));
                  const sb = sentMatch?.sentimentBreakdown;
                  const sentTotal = sb ? sb.positive + sb.negative + sb.neutral : 0;
                  return (
                    <li
                      key={i}
                      className="flex flex-wrap items-center justify-between gap-2 rounded-lg bg-[var(--shell-panel-soft)] px-3 py-2"
                    >
                      <span className="text-sm text-[var(--shell-text)]">{c.name}</span>
                      <div className="flex items-center gap-2 text-[11px]">
                        <span className="text-[var(--shell-text-muted)]">{c.mentionCount} 회</span>
                        {sentTotal > 0 && sb && (
                          <span className="flex items-center gap-1.5 rounded-full bg-[var(--shell-panel)] px-2 py-0.5">
                            {sb.positive > 0 && <span className="text-emerald-300">긍정 {sb.positive}</span>}
                            {sb.negative > 0 && <span className="text-red-300">부정 {sb.negative}</span>}
                            {sb.neutral > 0 && <span className="text-blue-300">중립 {sb.neutral}</span>}
                          </span>
                        )}
                        <span className="text-[10px] text-[var(--shell-text-soft)]">{c.engines.join(", ")}</span>
                      </div>
                    </li>
                  );
                })}
              </ul>
              {!sentiment && (
                <div className="mt-3 flex items-start gap-1.5 rounded-lg border border-blue-500/20 bg-blue-500/5 px-3 py-2 text-[11px] text-blue-200">
                  <Info className="mt-0.5 h-3 w-3 shrink-0" />
                  <span>
                    'GEO 현황' 페이지에서 sentiment 분석을 실행하면 각 경쟁사 답변 톤(긍정/부정/중립) 분포가 함께 표시됩니다.
                  </span>
                </div>
              )}
            </section>
          )}
        </>
      )}
    </div>
  );
}

function DeltaCard({ label, delta, suffix = "%p" }: { label: string; delta: number; suffix?: string }) {
  const tone = delta > 0.5 ? "text-emerald-300" : delta < -0.5 ? "text-red-300" : "text-[var(--shell-text)]";
  return (
    <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] px-5 py-4">
      <div className="text-[11px] uppercase tracking-[0.18em] text-[var(--shell-text-soft)]">{label}</div>
      <div className="mt-2 flex items-center gap-1.5">
        {deltaIcon(delta)}
        <span className={`text-2xl font-semibold ${tone}`}>{formatDelta(delta, suffix)}</span>
      </div>
    </div>
  );
}
