// Portal Phase 3 — Firestore readers per domain.
// 문서가 없거나 일부 필드가 비어 있을 때도 UI 가 크래시하지 않도록 각 reader 는
// 스키마 형태의 기본값을 채워서 반환한다 (Slice A — read 정합성).

import { getDoc, getDocs, orderBy, query, setDoc, serverTimestamp } from "firebase/firestore";
import { paths } from "./paths";
import type {
  ActionsData,
  BrandTruth,
  ClientCompetitorMention,
  ClientCompetitorMentionsResponse,
  DashboardData,
  ManualAction,
  ProbeRecord,
  ProbeSentimentsDoc,
  SeoData,
  TrendSnapshot,
  WeeklyTrendReport,
} from "../pages/portal/dataHub/types";

function asArray<T>(v: unknown): T[] {
  return Array.isArray(v) ? (v as T[]) : [];
}

function asRecord(v: unknown): Record<string, unknown> {
  return v && typeof v === "object" ? (v as Record<string, unknown>) : {};
}

export async function getPortalDashboard(boardId: string): Promise<DashboardData | null> {
  const [summarySnap, brandSnap] = await Promise.all([
    getDoc(paths.summary(boardId, "dashboard")),
    getDoc(paths.rawBrandTruth(boardId)),
  ]);
  if (!summarySnap.exists() && !brandSnap.exists()) return null;

  const raw = summarySnap.exists() ? (summarySnap.data() as Record<string, unknown>) : {};
  const onboarding = (raw.onboarding as DashboardData["onboarding"] | undefined) ?? {
    id: boardId,
    url: "",
    domain: "",
    status: "unknown",
  };
  const brand = brandSnap.exists() ? (brandSnap.data() as Record<string, unknown>) : null;
  const company = brand
    ? {
        name: String(brand.canonicalName ?? ""),
        status: "active",
        issuePrefix: String(brand.primaryCategory ?? "").slice(0, 3).toUpperCase() || "GEO",
      }
    : null;
  const { onboarding: _on, updatedAt: _u, issues: _i, activity: _a, ...execFields } = raw as Record<string, unknown>;

  return {
    onboarding,
    company,
    issues: asArray<DashboardData["issues"][number]>(raw.issues),
    hasSummary: summarySnap.exists(),
    ...(summarySnap.exists() ? (execFields as Partial<DashboardData>) : {}),
    activity: asArray<DashboardData["activity"][number]>(raw.activity),
  };
}

export async function getPortalSeo(boardId: string): Promise<SeoData | null> {
  const snap = await getDoc(paths.analysis(boardId, "seo-audit"));
  if (!snap.exists()) return null;
  const raw = snap.data() as Record<string, unknown>;
  return {
    score: typeof raw.score === "number" ? raw.score : null,
    categories: (raw.categories as SeoData["categories"]) ?? null,
    checks: asArray<SeoData["checks"][number]>(raw.checks),
    recommendations: asArray<SeoData["recommendations"][number]>(raw.recommendations),
    pageScores: asArray<NonNullable<SeoData["pageScores"]>[number]>(raw.pageScores),
  };
}

export async function getPortalProbes(boardId: string): Promise<{ probes: ProbeRecord[] }> {
  const snap = await getDocs(paths.rawGeoProbes(boardId));
  const probes = snap.docs.map((d) => ({ id: d.id, ...(d.data() as Record<string, unknown>) })) as ProbeRecord[];
  return { probes };
}

export async function getPortalBrandTruth(
  boardId: string,
): Promise<{ truth: BrandTruth | null }> {
  const snap = await getDoc(paths.rawBrandTruth(boardId));
  if (!snap.exists()) return { truth: null };
  return { truth: snap.data() as BrandTruth };
}

export async function savePortalBrandTruth(
  boardId: string,
  data: Partial<BrandTruth>,
): Promise<void> {
  await setDoc(
    paths.rawBrandTruth(boardId),
    { ...data, updatedAt: serverTimestamp() },
    { merge: true },
  );
}

export async function getPortalSentiment(
  boardId: string,
): Promise<{ summary: ProbeSentimentsDoc | null }> {
  const snap = await getDoc(paths.summary(boardId, "probe-sentiments"));
  if (!snap.exists()) return { summary: null };
  const raw = snap.data() as Record<string, unknown>;
  const topAnswersRaw = asRecord(raw.topAnswers);
  const brandBreakdownRaw = asRecord(raw.brandBreakdown);
  const summary: ProbeSentimentsDoc = {
    generatedAt: String(raw.generatedAt ?? ""),
    totalProbesAnalyzed: Number(raw.totalProbesAnalyzed ?? 0),
    brandBreakdown: {
      positive: Number(brandBreakdownRaw.positive ?? 0),
      negative: Number(brandBreakdownRaw.negative ?? 0),
      neutral: Number(brandBreakdownRaw.neutral ?? 0),
      unknown: Number(brandBreakdownRaw.unknown ?? 0),
    },
    records: asArray<ProbeSentimentsDoc["records"][number]>(raw.records),
    competitors: asArray<ProbeSentimentsDoc["competitors"][number]>(raw.competitors),
    topAnswers: {
      positive: asArray<ProbeSentimentsDoc["topAnswers"]["positive"][number]>(topAnswersRaw.positive),
      negative: asArray<ProbeSentimentsDoc["topAnswers"]["negative"][number]>(topAnswersRaw.negative),
      neutral: asArray<ProbeSentimentsDoc["topAnswers"]["neutral"][number]>(topAnswersRaw.neutral),
    },
  };
  return { summary };
}

export async function getPortalActions(boardId: string): Promise<ActionsData | null> {
  const summarySnap = await getDoc(paths.summary(boardId, "next-actions"));
  const summary = summarySnap.exists() ? (summarySnap.data() as Partial<ActionsData>) : null;

  const runsSnap = await getDocs(paths.actionRuns(boardId));
  const actions = runsSnap.docs
    .map((d) => ({ id: d.id, ...(d.data() as Record<string, unknown>) }))
    .filter((r) => (r as { source?: string }).source !== "manual") as ActionsData["actions"];

  if (!summary && actions.length === 0) return null;
  return {
    actions,
    structuredActions: asArray<ActionsData["structuredActions"][number]>(summary?.structuredActions),
  };
}

export async function getPortalManualActions(
  boardId: string,
): Promise<{ items: ManualAction[] }> {
  const snap = await getDocs(paths.actionRuns(boardId));
  const items = snap.docs
    .map((d) => ({ id: d.id, ...(d.data() as Record<string, unknown>) }))
    .filter((r) => (r as { source?: string }).source === "manual") as ManualAction[];
  return { items };
}

export async function getPortalTrendSnapshots(
  boardId: string,
): Promise<{ snapshots: TrendSnapshot[] }> {
  const snap = await getDocs(
    query(paths.rawBenchmarkDaily(boardId), orderBy("date", "asc")),
  );
  const snapshots = snap.docs.map((d) => {
    const raw = d.data() as Record<string, unknown>;
    const metrics = asRecord(raw.metrics);
    return {
      capturedAt: String(raw.capturedAt ?? ""),
      brandTruth: raw.brandTruth as TrendSnapshot["brandTruth"],
      metrics: {
        totalQuestions: Number(metrics.totalQuestions ?? 0),
        exposureRate: Number(metrics.exposureRate ?? 0),
        mentionRate: Number(metrics.mentionRate ?? 0),
        visibilityScore: Number(metrics.visibilityScore ?? 0),
        weightedMentionRate: Number(metrics.weightedMentionRate ?? 0),
        mentionCount: Number(metrics.mentionCount ?? 0),
        seoScore: metrics.seoScore as number | undefined,
        geoScore: metrics.geoScore as number | undefined,
      },
      engineBreakdown: asArray<TrendSnapshot["engineBreakdown"][number]>(raw.engineBreakdown),
      topQueries: asArray<TrendSnapshot["topQueries"][number]>(raw.topQueries),
      actions: asArray<TrendSnapshot["actions"][number]>(raw.actions),
    } satisfies TrendSnapshot;
  });
  return { snapshots };
}

export async function getPortalWeeklyReport(
  boardId: string,
): Promise<{ report: WeeklyTrendReport | null }> {
  const snap = await getDoc(paths.report(boardId, "weekly-latest"));
  if (!snap.exists()) return { report: null };
  const raw = snap.data() as Record<string, unknown>;
  const summary = asRecord(raw.summary);
  const globalEngine = asRecord(raw.globalEngine);
  const naverLayer = asRecord(raw.naverLayer);
  const weeklyChange = asRecord(raw.weeklyChange);
  const report: WeeklyTrendReport = {
    generatedAt: String(raw.generatedAt ?? ""),
    periodStart: String(raw.periodStart ?? ""),
    periodEnd: String(raw.periodEnd ?? ""),
    summary: {
      headline: String(summary.headline ?? ""),
      overview: asArray<string>(summary.overview),
    },
    globalEngine: {
      label: String(globalEngine.label ?? ""),
      engines: asArray<WeeklyTrendReport["globalEngine"]["engines"][number]>(globalEngine.engines),
    },
    naverLayer: {
      score: Number(naverLayer.score ?? 0),
      exposureRate: (naverLayer.exposureRate as number | null | undefined) ?? null,
      newsMentions: Number(naverLayer.newsMentions ?? 0),
      communityPresence: Number(naverLayer.communityPresence ?? 0),
      summary: asArray<string>(naverLayer.summary),
    },
    weeklyChange: {
      mentionRateDelta: Number(weeklyChange.mentionRateDelta ?? 0),
      exposureRateDelta: Number(weeklyChange.exposureRateDelta ?? 0),
      weightedMentionRateDelta: Number(weeklyChange.weightedMentionRateDelta ?? 0),
      mentionCountDelta: Number(weeklyChange.mentionCountDelta ?? 0),
    },
    competitors: asArray<WeeklyTrendReport["competitors"][number]>(raw.competitors),
    executedActions: asArray<WeeklyTrendReport["executedActions"][number]>(raw.executedActions),
    nextSteps: asArray<string>(raw.nextSteps),
    body: String(raw.body ?? ""),
  };
  return { report };
}

export async function getPortalCompetitorMentions(
  boardId: string,
): Promise<ClientCompetitorMentionsResponse> {
  const [compSnap, sentimentSnap] = await Promise.all([
    getDocs(paths.rawCompetitors(boardId)),
    getDoc(paths.summary(boardId, "probe-sentiments")),
  ]);
  const userCompetitors: ClientCompetitorMention[] = [];
  const autoDetected: ClientCompetitorMention[] = [];
  for (const d of compSnap.docs) {
    const data = d.data() as Record<string, unknown> & {
      type?: string;
      name?: string;
      source?: "user" | "auto";
      mentionCount?: number;
      engines?: string[];
      sentimentBreakdown?: { positive?: number; negative?: number; neutral?: number; unknown?: number };
    };
    const sb = data.sentimentBreakdown ?? {};
    const entry: ClientCompetitorMention = {
      name: data.name ?? d.id,
      source: data.source ?? (data.type === "manual" ? "user" : "auto"),
      mentionCount: Number(data.mentionCount ?? 0),
      engines: Array.isArray(data.engines) ? data.engines : [],
      sentimentBreakdown: {
        positive: Number(sb.positive ?? 0),
        negative: Number(sb.negative ?? 0),
        neutral: Number(sb.neutral ?? 0),
        unknown: Number(sb.unknown ?? 0),
      },
    };
    if (data.type === "manual") userCompetitors.push(entry);
    else autoDetected.push(entry);
  }
  const sentimentData = sentimentSnap.exists()
    ? (sentimentSnap.data() as Record<string, unknown>)
    : null;
  return {
    userCompetitors,
    autoDetected,
    totalProbesAnalyzed: Number(sentimentData?.totalProbesAnalyzed ?? 0),
    sentimentAvailable: !!sentimentData,
  };
}
