import { useMemo, useState } from "react";
import { Link } from "react-router-dom";
import { CheckCircle2, Clock, Circle, Plus, X, Trash2, Save, Bot, Pencil, ArrowRight, Sparkles } from "lucide-react";
import { usePortalActions, usePortalManualActions, usePortalDashboard } from "./dataHub";
import { MANUAL_ACTION_CATEGORY_LABEL, type ManualAction, type ManualActionCategory, type ManualActionStatus } from "./dataHub/types";

type Status = "completed" | "in-progress" | "scheduled";

const STATUS_LABEL: Record<Status, string> = {
  completed: "완료",
  "in-progress": "진행 중",
  scheduled: "예정",
};

const STATUS_TONE: Record<Status, string> = {
  completed: "bg-emerald-500/10 border-emerald-500/30 text-emerald-200",
  "in-progress": "bg-blue-500/10 border-blue-500/30 text-blue-200",
  scheduled: "bg-neutral-500/10 border-neutral-500/30 text-neutral-300",
};

// NOTE: technical 카테고리는 참고 디자인에서 violet/purple 을 썼으나 포털 가이드에 따라 blue 계열로 교체.
const CATEGORY_TONE: Record<ManualActionCategory, string> = {
  technical: "bg-blue-500/15 text-blue-300 border-blue-500/30",
  homepage: "bg-teal-500/15 text-teal-300 border-teal-500/30",
  media: "bg-amber-500/15 text-amber-300 border-amber-500/30",
  community: "bg-emerald-500/15 text-emerald-300 border-emerald-500/30",
  other: "bg-neutral-500/15 text-neutral-300 border-neutral-500/30",
};

function priorityToTier(priority: string): "P0" | "P1" | "P2" {
  const p = (priority || "").toLowerCase();
  if (p === "urgent" || p === "critical" || p === "high") return "P0";
  if (p === "medium" || p === "p1") return "P1";
  return "P2";
}

type AutoAction = {
  id: string;
  identifier: string;
  title: string;
  status: string;
  priority: string;
  assignee: string | null;
  activeRun: { status: string } | null;
  createdAt: string;
  completedAt: string | null;
};

function statusOf(action: AutoAction): Status {
  if (action.status === "completed" || action.completedAt) return "completed";
  if (action.activeRun?.status === "running" || action.status === "in_progress" || action.status === "running")
    return "in-progress";
  return "scheduled";
}

function statusIcon(s: Status) {
  if (s === "completed") return <CheckCircle2 className="h-4 w-4 text-emerald-400" />;
  if (s === "in-progress") return <Clock className="h-4 w-4 text-blue-400" />;
  return <Circle className="h-4 w-4 text-neutral-400" />;
}

function getWeekStart(iso: string): string {
  const d = new Date(iso);
  const day = d.getDay() || 7;
  if (day !== 1) d.setHours(-24 * (day - 1));
  return d.toISOString().slice(0, 10);
}

type UnifiedItem = {
  key: string;
  date: string;
  title: string;
  status: Status;
  source: "auto" | "manual";
  category?: ManualActionCategory;
  notes?: string;
  manualId?: string;
  auto?: AutoAction;
};

export function PortalTimeline() {
  const [showAddForm, setShowAddForm] = useState(false);
  const [localManual, setLocalManual] = useState<ManualAction[] | null>(null);

  const { data: actionsData, isLoading: actionsLoading } = usePortalActions();
  const { data: manualData, isLoading: manualLoading } = usePortalManualActions();
  const { data: dashboardData } = usePortalDashboard();

  const isLoading = actionsLoading || manualLoading;
  const autoActions = (actionsData?.actions || []) as AutoAction[];
  const manualActions: ManualAction[] = localManual ?? manualData?.items ?? [];

  const analysisStarted = !!dashboardData?.hasSummary;
  const recommendedActions = dashboardData?.nextActions?.recommended || [];

  const handleDelete = (actionId: string) => {
    setLocalManual((prev) => {
      const base = prev ?? manualData?.items ?? [];
      return base.filter((m) => m.id !== actionId);
    });
  };

  const handleCreate = (payload: {
    date: string;
    category: ManualActionCategory;
    title: string;
    notes?: string;
    status: ManualActionStatus;
  }) => {
    const now = new Date().toISOString();
    const newItem: ManualAction = {
      id: `m-local-${Date.now()}`,
      date: payload.date,
      category: payload.category,
      title: payload.title,
      notes: payload.notes,
      status: payload.status,
      source: "manual",
      createdAt: now,
      updatedAt: now,
    };
    setLocalManual((prev) => {
      const base = prev ?? manualData?.items ?? [];
      return [...base, newItem];
    });
    setShowAddForm(false);
  };

  const weeks = useMemo(() => {
    const unified: UnifiedItem[] = [];
    for (const a of autoActions) {
      unified.push({
        key: `auto-${a.id}`,
        date: a.createdAt,
        title: a.title || a.identifier,
        status: statusOf(a),
        source: "auto",
        auto: a,
      });
    }
    for (const m of manualActions) {
      unified.push({
        key: `manual-${m.id}`,
        date: m.date + "T09:00:00.000Z",
        title: m.title,
        status: m.status,
        source: "manual",
        category: m.category,
        notes: m.notes,
        manualId: m.id,
      });
    }

    const map = new Map<string, UnifiedItem[]>();
    for (const u of unified) {
      const w = getWeekStart(u.date);
      if (!map.has(w)) map.set(w, []);
      map.get(w)!.push(u);
    }
    return [...map.entries()]
      .sort((a, b) => b[0].localeCompare(a[0]))
      .map(([week, items]) => ({
        week,
        items: items.sort((a, b) => a.date.localeCompare(b.date)),
      }));
  }, [autoActions, manualActions]);

  const stats = useMemo(() => {
    const counts: Record<Status, number> = { completed: 0, "in-progress": 0, scheduled: 0 };
    for (const a of autoActions) counts[statusOf(a)]++;
    for (const m of manualActions) counts[m.status]++;
    return counts;
  }, [autoActions, manualActions]);

  return (
    <div className="mx-auto max-w-6xl space-y-6 px-4 py-6">
      <header>
        <div className="text-xs uppercase tracking-[0.28em] text-[var(--shell-text-soft)]">Portal / 액션 진행일정</div>
        <h1 className="mt-2 text-3xl font-semibold tracking-tight text-[var(--shell-text)]">액션 타임라인</h1>
        <p className="mt-2 text-sm text-[var(--shell-text-muted)]">
          언제 어떤 액션이 진행되었는지를 주 단위로 모아 보여줍니다.
          <span className="ml-2 inline-flex items-center gap-1 text-[11px] text-[var(--shell-text-soft)]">
            <Bot className="h-3 w-3" /> 자동 = 플랫폼 측정/배포로 자동 기록 ·
            <Pencil className="h-3 w-3" /> 수동 = 대행사·고객이 직접 입력
          </span>
        </p>
      </header>

      {isLoading && (
        <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] px-6 py-12 text-center text-sm text-[var(--shell-text-muted)]">
          불러오는 중입니다...
        </div>
      )}

      {!isLoading && (
        <>
          <section className="grid grid-cols-1 gap-3 md:grid-cols-[1fr_1fr_1fr_auto]">
            <CountCard label="완료" count={stats.completed} tone="emerald" />
            <CountCard label="진행 중" count={stats["in-progress"]} tone="blue" />
            <CountCard label="예정" count={stats.scheduled} tone="neutral" />
            <button
              type="button"
              onClick={() => setShowAddForm((v) => !v)}
              className="flex items-center justify-center gap-2 rounded-2xl border-2 border-dashed border-[var(--shell-accent)]/40 bg-[var(--shell-accent)]/5 px-5 py-4 text-sm font-medium text-[var(--shell-accent)] hover:bg-[var(--shell-accent)]/10"
            >
              {showAddForm ? <X className="h-4 w-4" /> : <Plus className="h-4 w-4" />}
              {showAddForm ? "취소" : "+ 액션 추가"}
            </button>
          </section>

          {showAddForm && (
            <ManualActionForm onSubmit={handleCreate} onCancel={() => setShowAddForm(false)} />
          )}

          {weeks.length === 0 ? (
            !analysisStarted ? (
              <div className="rounded-2xl border border-blue-500/30 bg-blue-500/5 px-6 py-6">
                <div className="flex items-start gap-3">
                  <Sparkles className="mt-0.5 h-5 w-5 shrink-0 text-blue-300" />
                  <div className="flex-1">
                    <div className="text-sm font-medium text-blue-100">아직 웹사이트 분석이 진행되지 않았습니다</div>
                    <div className="mt-1 text-xs leading-5 text-blue-200/80">
                      Dashboard 에서 분석을 시작하면 AI 가 우리 사이트의 SEO/GEO 점수를 측정하고
                      자동으로 추천 액션을 생성합니다. 또는 위 '+ 액션 추가' 버튼으로 이미 진행한 액션을 직접 기록할 수 있습니다.
                    </div>
                    <Link
                      to="../dashboard"
                      relative="path"
                      className="mt-3 inline-flex items-center gap-1.5 rounded-lg bg-blue-500/20 px-3 py-1.5 text-xs font-medium text-blue-100 hover:bg-blue-500/30"
                    >
                      Dashboard 로 이동 → 분석 시작 <ArrowRight className="h-3 w-3" />
                    </Link>
                  </div>
                </div>
              </div>
            ) : recommendedActions.length > 0 ? (
              <div className="rounded-2xl border border-emerald-500/30 bg-emerald-500/5 p-5">
                <div className="flex items-start gap-3">
                  <Sparkles className="mt-0.5 h-5 w-5 shrink-0 text-emerald-300" />
                  <div className="flex-1">
                    <div className="text-sm font-medium text-emerald-100">분석은 완료되었지만 등록된 액션이 없습니다</div>
                    <div className="mt-1 text-xs leading-5 text-emerald-200/80">
                      AI 가 추천하는 우선 액션 {recommendedActions.length}개를 확인하고, 진행한 항목은 위 '+ 액션 추가' 버튼으로 기록하세요.
                    </div>
                  </div>
                </div>
                <ol className="mt-4 space-y-2">
                  {recommendedActions.slice(0, 3).map((act, i) => (
                    <li key={i} className="flex items-start gap-3 rounded-xl bg-emerald-500/10 px-4 py-3">
                      <div className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-emerald-500/30 text-xs font-semibold text-emerald-100">
                        {i + 1}
                      </div>
                      <div className="flex-1 text-sm text-emerald-50">
                        {act.title}
                        {act.priority && (
                          <span className="ml-2 rounded-full bg-emerald-900/30 px-2 py-0.5 text-[10px] text-emerald-200">
                            우선순위: {act.priority}
                          </span>
                        )}
                        {act.impact && (
                          <span className="ml-1 rounded-full bg-emerald-900/30 px-2 py-0.5 text-[10px] text-emerald-200">
                            영향: {act.impact}
                          </span>
                        )}
                      </div>
                    </li>
                  ))}
                </ol>
              </div>
            ) : (
              <div className="rounded-2xl border border-amber-500/30 bg-amber-500/5 p-5">
                <div className="flex items-start gap-3">
                  <Sparkles className="mt-0.5 h-5 w-5 shrink-0 text-amber-300" />
                  <div className="flex-1">
                    <div className="text-sm font-medium text-amber-100">분석은 완료되었지만 등록된 액션이 없습니다</div>
                    <div className="mt-1 text-xs leading-5 text-amber-200/80">
                      아래는 GEO 가시성 향상을 위해 일반적으로 가장 효과가 큰 기본 액션 3개입니다.
                      진행한 항목은 위 '+ 액션 추가' 버튼으로 기록하세요.
                    </div>
                  </div>
                </div>
                <ol className="mt-4 space-y-2">
                  {[
                    { title: "robots.txt 에 GPTBot / PerplexityBot 허용 추가", category: "기술", impact: "AI 답변 출처 인용 가능성 ↑" },
                    { title: "주요 서비스 페이지에 FAQPage Schema (JSON-LD) 추가", category: "기술", impact: "Gemini AI Overview 답변에 직접 인용 가능" },
                    { title: "must-win 쿼리에 대응하는 FAQ 콘텐츠 5개 작성", category: "콘텐츠", impact: "AI 학습 컨텍스트 강화 + 자체 노출 ↑" },
                  ].map((act, i) => (
                    <li key={i} className="flex items-start gap-3 rounded-xl bg-amber-500/10 px-4 py-3">
                      <div className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-amber-500/30 text-xs font-semibold text-amber-100">
                        {i + 1}
                      </div>
                      <div className="flex-1">
                        <div className="text-sm text-amber-50">{act.title}</div>
                        <div className="mt-1 flex flex-wrap items-center gap-1.5 text-[10px]">
                          <span className="rounded-full bg-amber-900/30 px-2 py-0.5 text-amber-200">{act.category}</span>
                          <span className="rounded-full bg-amber-900/30 px-2 py-0.5 text-amber-200">
                            예상 효과: {act.impact}
                          </span>
                        </div>
                      </div>
                    </li>
                  ))}
                </ol>
              </div>
            )
          ) : (
            <section className="space-y-5">
              {weeks.map((w) => (
                <div key={w.week}>
                  <div className="mb-2 flex items-center gap-3 px-1">
                    <div className="text-sm font-semibold text-[var(--shell-text)]">
                      {new Date(w.week).toLocaleDateString()} 주
                    </div>
                    <div className="text-[11px] text-[var(--shell-text-soft)]">{w.items.length} 개 액션</div>
                  </div>
                  <ul className="space-y-2">
                    {w.items.map((u) => (
                      <li key={u.key} className={`rounded-xl border px-4 py-3 ${STATUS_TONE[u.status]}`}>
                        <div className="flex items-start gap-3">
                          {statusIcon(u.status)}
                          <div className="flex-1">
                            <div className="flex flex-wrap items-center gap-2">
                              <span
                                className={`shrink-0 rounded-full border px-2 py-0.5 text-[9px] font-semibold ${
                                  u.source === "auto"
                                    ? "border-blue-500/30 bg-blue-500/15 text-blue-300"
                                    : "border-amber-500/30 bg-amber-500/15 text-amber-300"
                                }`}
                              >
                                {u.source === "auto" ? (
                                  <Bot className="inline h-2.5 w-2.5" />
                                ) : (
                                  <Pencil className="inline h-2.5 w-2.5" />
                                )}{" "}
                                {u.source === "auto" ? "자동" : "수동"}
                              </span>
                              {u.source === "auto" &&
                                u.auto?.priority &&
                                (() => {
                                  const tier = priorityToTier(u.auto.priority);
                                  const tierStyle =
                                    tier === "P0"
                                      ? "border-red-500/40 bg-red-500/15 text-red-300"
                                      : tier === "P1"
                                        ? "border-amber-500/40 bg-amber-500/15 text-amber-300"
                                        : "border-blue-500/40 bg-blue-500/15 text-blue-300";
                                  return (
                                    <span
                                      className={`shrink-0 rounded-full border px-2 py-0.5 text-[10px] font-semibold ${tierStyle}`}
                                    >
                                      {tier}
                                    </span>
                                  );
                                })()}
                              {u.category && (
                                <span
                                  className={`shrink-0 rounded-full border px-2 py-0.5 text-[10px] ${CATEGORY_TONE[u.category]}`}
                                >
                                  {MANUAL_ACTION_CATEGORY_LABEL[u.category]}
                                </span>
                              )}
                              <span className="text-sm font-medium text-[var(--shell-text)]">{u.title}</span>
                              <span className="rounded-full bg-[var(--shell-panel)] px-2 py-0.5 text-[10px]">
                                {STATUS_LABEL[u.status]}
                              </span>
                            </div>
                            {u.notes && (
                              <div className="mt-1 text-[11px] leading-5 text-[var(--shell-text-muted)]">{u.notes}</div>
                            )}
                            <div className="mt-1 flex items-center gap-3 text-[10px] text-[var(--shell-text-soft)]">
                              <span>일자: {new Date(u.date).toLocaleDateString()}</span>
                              {u.source === "auto" && u.auto?.completedAt && (
                                <span>완료: {new Date(u.auto.completedAt).toLocaleDateString()}</span>
                              )}
                              {u.source === "auto" && u.auto?.priority && <span>우선순위: {u.auto.priority}</span>}
                              {u.source === "auto" && u.auto?.assignee && <span>담당: {u.auto.assignee}</span>}
                            </div>
                          </div>
                          {u.source === "manual" && u.manualId && (
                            <button
                              type="button"
                              onClick={() => {
                                if (confirm("이 수동 액션을 삭제할까요?")) handleDelete(u.manualId!);
                              }}
                              className="shrink-0 rounded-lg p-1.5 text-[var(--shell-text-soft)] hover:bg-red-500/15 hover:text-red-300"
                              title="삭제"
                            >
                              <Trash2 className="h-3.5 w-3.5" />
                            </button>
                          )}
                        </div>
                      </li>
                    ))}
                  </ul>
                </div>
              ))}
            </section>
          )}
        </>
      )}
    </div>
  );
}

function CountCard({ label, count, tone }: { label: string; count: number; tone: "emerald" | "blue" | "neutral" }) {
  const toneColor =
    tone === "emerald" ? "text-emerald-300" : tone === "blue" ? "text-blue-300" : "text-[var(--shell-text)]";
  return (
    <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] px-5 py-4">
      <div className="text-[11px] uppercase tracking-[0.18em] text-[var(--shell-text-soft)]">{label}</div>
      <div className={`mt-2 text-3xl font-semibold ${toneColor}`}>{count}</div>
    </div>
  );
}

function ManualActionForm({
  onSubmit,
  onCancel,
}: {
  onSubmit: (payload: {
    date: string;
    category: ManualActionCategory;
    title: string;
    notes?: string;
    status: ManualActionStatus;
  }) => void;
  onCancel: () => void;
}) {
  const [date, setDate] = useState(() => new Date().toISOString().slice(0, 10));
  const [category, setCategory] = useState<ManualActionCategory>("homepage");
  const [title, setTitle] = useState("");
  const [notes, setNotes] = useState("");
  const [status, setStatus] = useState<ManualActionStatus>("completed");
  const [error, setError] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);

  const handleSubmit = () => {
    setError(null);
    if (!title.trim()) {
      setError("내용을 입력해주세요");
      return;
    }
    setIsSaving(true);
    setTimeout(() => {
      onSubmit({ date, category, title: title.trim(), notes: notes.trim() || undefined, status });
      setIsSaving(false);
    }, 300);
  };

  return (
    <section className="rounded-2xl border-2 border-[var(--shell-accent)]/40 bg-[var(--shell-accent)]/5 p-5">
      <div className="mb-3 flex items-center gap-2">
        <Pencil className="h-4 w-4 text-[var(--shell-accent)]" />
        <span className="text-sm font-semibold text-[var(--shell-text)]">수동 액션 추가</span>
      </div>
      <div className="grid gap-3 md:grid-cols-[140px_180px_1fr_140px]">
        <div>
          <label className="mb-1.5 block text-xs font-medium text-[var(--shell-text)]">일자</label>
          <input
            type="date"
            value={date}
            onChange={(e) => setDate(e.target.value)}
            className="w-full rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-2 text-sm text-[var(--shell-text)] outline-none focus:border-[var(--shell-accent)]"
          />
        </div>
        <div>
          <label className="mb-1.5 block text-xs font-medium text-[var(--shell-text)]">카테고리</label>
          <select
            value={category}
            onChange={(e) => setCategory(e.target.value as ManualActionCategory)}
            className="w-full rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-2 text-sm text-[var(--shell-text)] outline-none focus:border-[var(--shell-accent)]"
          >
            <option value="technical">기술</option>
            <option value="homepage">홈페이지 콘텐츠</option>
            <option value="media">언론</option>
            <option value="community">커뮤니티</option>
            <option value="other">기타</option>
          </select>
        </div>
        <div>
          <label className="mb-1.5 block text-xs font-medium text-[var(--shell-text)]">내용</label>
          <input
            type="text"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="ex) 홈페이지 FAQ 5개 추가, 경쟁사 비교 콘텐츠 발행"
            className="w-full rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-2 text-sm text-[var(--shell-text)] placeholder-[var(--shell-text-soft)] outline-none focus:border-[var(--shell-accent)]"
          />
        </div>
        <div>
          <label className="mb-1.5 block text-xs font-medium text-[var(--shell-text)]">상태</label>
          <select
            value={status}
            onChange={(e) => setStatus(e.target.value as ManualActionStatus)}
            className="w-full rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-2 text-sm text-[var(--shell-text)] outline-none focus:border-[var(--shell-accent)]"
          >
            <option value="completed">완료</option>
            <option value="in-progress">진행 중</option>
            <option value="scheduled">예정</option>
          </select>
        </div>
      </div>
      <div className="mt-3">
        <label className="mb-1.5 block text-xs font-medium text-[var(--shell-text)]">메모 (선택)</label>
        <textarea
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
          placeholder="추가 설명, 진행 상황, 연결된 콘텐츠 URL 등"
          rows={2}
          className="w-full rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-2 text-xs text-[var(--shell-text)] placeholder-[var(--shell-text-soft)] outline-none focus:border-[var(--shell-accent)]"
        />
      </div>
      {error && (
        <div className="mt-3 rounded border border-red-500/30 bg-red-500/5 px-3 py-2 text-xs text-red-300">{error}</div>
      )}
      <div className="mt-4 flex items-center justify-end gap-2">
        <button
          type="button"
          onClick={onCancel}
          className="rounded-lg border border-[var(--shell-border)] px-4 py-2 text-sm text-[var(--shell-text-muted)] hover:bg-[var(--shell-panel-soft)]"
        >
          취소
        </button>
        <button
          type="button"
          onClick={handleSubmit}
          disabled={isSaving || !title.trim()}
          className="flex items-center gap-2 rounded-lg bg-[var(--shell-accent)] px-4 py-2 text-sm font-medium text-white hover:opacity-90 disabled:opacity-50"
        >
          <Save className="h-3.5 w-3.5" />
          {isSaving ? "저장 중..." : "추가"}
        </button>
      </div>
    </section>
  );
}
