// ── Number / text formatters ─────────────────────────────

export function formatCompactNumber(value: number | null | undefined): string {
  if (value === null || value === undefined || Number.isNaN(value)) return "–";
  const n = Math.abs(value);
  if (n >= 1_000_000) return `${(value / 1_000_000).toFixed(1)}M`;
  if (n >= 1_000) return `${Math.round(value / 100) / 10}K`;
  return value.toLocaleString();
}

export function formatPercent(value: number | null | undefined, digits = 0): string {
  if (value === null || value === undefined || Number.isNaN(value)) return "–";
  return `${value.toFixed(digits)}%`;
}

export function truncateText(text: string | undefined | null, max = 120): string {
  if (!text) return "";
  if (text.length <= max) return text;
  return `${text.slice(0, max - 1)}…`;
}

export function looksLikeDomain(value: string): boolean {
  return /^[a-z0-9.-]+\.[a-z]{2,}$/i.test(value.replace(/^https?:\/\//, "").split("/")[0]);
}

export function formatCompetitorDomain(competitor: { domain?: string; url?: string; source?: string }): string {
  const raw = String(competitor?.domain || competitor?.url || competitor?.source || "").trim();
  if (!raw) return "domain pending";
  try {
    return new URL(raw.startsWith("http") ? raw : `https://${raw}`).hostname.replace(/^www\./, "");
  } catch {
    return raw.replace(/^https?:\/\//, "").replace(/^www\./, "").split("/")[0];
  }
}

export function formatCompetitorName(competitor: { name?: string; domain?: string; url?: string; source?: string }): string {
  const name = String(competitor?.name || "").trim();
  const domain = formatCompetitorDomain(competitor);
  if (name && !looksLikeDomain(name)) return name;
  const host = domain.replace(/^www\./, "").split(".")[0] || name || "경쟁사";
  return host
    .split(/[-_]/)
    .filter(Boolean)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join(" ");
}

// ── Score helpers ────────────────────────────────────────

export function averageScores(values: Array<number | null | undefined>): number {
  const scores = values.filter((value): value is number => typeof value === "number" && Number.isFinite(value));
  if (scores.length === 0) return 0;
  return Math.round(scores.reduce((sum, score) => sum + score, 0) / scores.length);
}

export function scoreCruxMetric(value: string | number | null | undefined, good: number, needsWork: number): number | null {
  if (value === null || value === undefined || value === "" || value === "N/A") return null;
  const numeric = Number(String(value).replace(/[^0-9.]/g, ""));
  if (!Number.isFinite(numeric) || numeric <= 0) return null;
  if (numeric <= good) return 90;
  if (numeric <= needsWork) return 60;
  return 30;
}

export function computeCruxScore(siteHealth: DashboardExecutiveSummary["siteHealth"] | undefined): number | null {
  if (!siteHealth) return null;
  const metrics = [
    scoreCruxMetric(siteHealth.lcp, 2500, 4000),
    scoreCruxMetric(siteHealth.inp, 200, 500),
    scoreCruxMetric(siteHealth.cls, 0.1, 0.25),
  ].filter((score): score is number => score !== null);
  if (metrics.length === 0) return null;
  return Math.round(metrics.reduce((sum, score) => sum + score, 0) / metrics.length);
}

export function formatCruxNote(siteHealth: DashboardExecutiveSummary["siteHealth"] | undefined): string {
  const values = [siteHealth?.lcp, siteHealth?.inp, siteHealth?.cls].filter((value) => value && value !== "N/A");
  return values.length > 0
    ? `LCP ${siteHealth?.lcp || "-"} · INP ${siteHealth?.inp || "-"} · CLS ${siteHealth?.cls || "-"}`
    : "Chrome UX 데이터 대기";
}

// ── Dashboard action items ───────────────────────────────

export interface DashboardActionItem {
  title: string;
  impact: string;
}

export function buildDashboardActionItems(
  nextActions: DashboardExecutiveSummary["nextActions"] | undefined,
): DashboardActionItem[] {
  const base = Array.isArray(nextActions?.recommended) ? nextActions!.recommended! : [];
  const items: DashboardActionItem[] = base.map((item) => ({
    title: item.title || "실행 액션",
    impact: item.impact || "GEO 가시성 개선을 위한 우선 액션입니다.",
  }));

  const ensure = (title: string, impact: string, matcher: RegExp) => {
    if (!items.some((item) => matcher.test(item.title))) items.push({ title, impact });
  };

  ensure("Google Business Profile 등록/최적화", "지역/업체 추천형 AI 답변에서 공식 비즈니스 신호로 활용됩니다.", /google business|gbp/i);
  ensure("네이버 스마트플레이스 등록/정비", "국내 검색·지도·리뷰 신호를 확보해 네이버 기반 인용 가능성을 높입니다.", /네이버|naver|smart/i);
  ensure("Bing Places for Business 확인", "Bing 기반 검색/AI 레이어에서 업체 정보가 누락되지 않도록 확인합니다.", /bing/i);

  return items.slice(0, 3);
}

// ── External sources summary ─────────────────────────────

export interface ExternalSourceSummary {
  total: number;
  news: number;
  community: number;
  mentions: number;
  trustScore: number;
  newsNames: string;
  communityNames: string;
  mentionNote: string;
}

export function summarizeExternalSources(
  sources: Array<Record<string, unknown>>,
  externalSignals: { trustScore?: number; sourceCount?: number } | undefined,
): ExternalSourceSummary {
  const normalized = sources.map((source) => ({
    type: String(source.sourceType || source.source_type || source.type || "").toLowerCase(),
    name: String(source.sourceName || source.source_name || source.title || source.label || source.sourceUrl || source.source_url || "외부 소스"),
    exists: source.exists !== false,
    snippet: String(source.snippet || source.summary || ""),
  }));
  const newsRows = normalized.filter((source) => /news|media|press|article|언론/.test(source.type));
  const communityRows = normalized.filter((source) => /community|blog|review|place|map|dcinside|namuwiki|wiki|sns|naver|google/.test(source.type));
  const mentionedRows = normalized.filter((source) => source.exists && (source.snippet || source.name));
  const names = (rows: typeof normalized) => rows.slice(0, 3).map((source) => source.name).join(" · ");

  return {
    total: externalSignals?.sourceCount ?? normalized.length,
    news: newsRows.length,
    community: communityRows.length,
    mentions: mentionedRows.length,
    trustScore: externalSignals?.trustScore ?? 0,
    newsNames: names(newsRows) || "뉴스 소스 수집 대기",
    communityNames: names(communityRows) || "커뮤니티/리뷰 소스 수집 대기",
    mentionNote: mentionedRows.length > 0 ? `${mentionedRows.length}개 외부 소스에서 신호 확인` : "브랜드 언급 신호 수집 대기",
  };
}

// ── Place / Integration statuses ─────────────────────────

export interface PlaceIntegrationStatus {
  key: string;
  label: string;
  status: "connected" | "missing";
  statusLabel: string;
  detail: string;
  nextStep: string;
}

export function buildPlaceIntegrationStatuses(
  integration: Record<string, unknown> | undefined,
  externalSources: Array<Record<string, unknown>>,
  siteChecks: Record<string, Record<string, unknown>>,
): PlaceIntegrationStatus[] {
  const sourceText = externalSources
    .map((source) => [
      source.sourceType, source.source_type, source.type,
      source.sourceName, source.source_name, source.title, source.label,
      source.sourceUrl, source.source_url, source.snippet, source.summary,
    ].filter(Boolean).join(" "))
    .join(" ")
    .toLowerCase();

  const hasSignal = (...values: unknown[]) => values.some((value) => {
    if (value === true) return true;
    if (typeof value === "string") return /connected|detected|verified|active|등록|탐지|연동|확인/.test(value.toLowerCase());
    if (value && typeof value === "object") {
      const v = value as Record<string, unknown>;
      return v.connected === true || v.detected === true || v.exists === true || v.status === "connected";
    }
    return false;
  });

  const googleBusinessCheck = siteChecks["google-business"] || siteChecks.googleBusiness || {};
  const gbpConnected =
    hasSignal(
      integration?.gbpDetected, integration?.gbpConnected,
      integration?.googleBusinessProfileDetected, integration?.googleBusinessProfileConnected,
      integration?.googleBusiness, integration?.googleBusinessProfile,
      googleBusinessCheck,
    ) || /google business|business profile|gbp|google map|google place|구글지도|구글 지도/.test(sourceText);

  const naverPlaceConnected =
    hasSignal(
      integration?.naverPlaceDetected, integration?.naverPlaceConnected,
      integration?.naverSmartPlaceDetected, integration?.naverSmartPlaceConnected,
      integration?.smartPlace, integration?.naverSmartPlace,
    ) || /smart\s?place|naver place|naver map|네이버플레이스|스마트플레이스|네이버 지도|네이버지도/.test(sourceText);

  const bingPlacesConnected =
    hasSignal(
      integration?.bingPlacesDetected, integration?.bingPlacesConnected,
      integration?.bingBusinessDetected, integration?.bingBusinessConnected,
      integration?.bingPlaces,
    ) || /bing place|bing business|bing map|bing places for business/.test(sourceText);

  return [
    {
      key: "gbp",
      label: "Google Business Profile",
      status: gbpConnected ? "connected" : "missing",
      statusLabel: gbpConnected ? "확인됨" : "진행 필요",
      detail: gbpConnected ? "Google 로컬/지도 신호가 감지되었습니다." : "로컬 검색 및 AI 추천의 기준 신호입니다.",
      nextStep: gbpConnected ? "NAP, 카테고리, 리뷰 응답 품질을 점검합니다." : "GBP 등록/권한 연동 후 카테고리와 주요 서비스를 정비합니다.",
    },
    {
      key: "naver-smartplace",
      label: "네이버 스마트플레이스",
      status: naverPlaceConnected ? "connected" : "missing",
      statusLabel: naverPlaceConnected ? "확인됨" : "진행 필요",
      detail: naverPlaceConnected ? "네이버 플레이스/지도 계열 신호가 감지되었습니다." : "국내 검색·지도·리뷰 신호 확보가 필요합니다.",
      nextStep: naverPlaceConnected ? "대표 키워드, 소식, 리뷰 신호를 강화합니다." : "스마트플레이스 등록/권한 연동 후 브랜드·서비스 정보를 맞춥니다.",
    },
    {
      key: "bing-places",
      label: "Bing Places for Business",
      status: bingPlacesConnected ? "connected" : "missing",
      statusLabel: bingPlacesConnected ? "확인됨" : "확인 필요",
      detail: bingPlacesConnected ? "Bing 로컬 신호가 감지되었습니다." : "Bing 기반 검색/AI 레이어의 로컬 소스입니다.",
      nextStep: bingPlacesConnected ? "Google/Naver와 동일한 NAP 일관성을 유지합니다." : "Bing Places 등록 여부를 확인하고 누락 시 생성합니다.",
    },
  ];
}

// ── Source Ladder ────────────────────────────────────────

export interface SourceLadderRow {
  priority: number;
  label: string;
  status: "ready" | "weak" | "missing";
  summary: string;
  nextAction: string;
}

export function buildDashboardSourceLadder(
  externalSourceSummary: ExternalSourceSummary,
  placeStatuses: PlaceIntegrationStatus[],
  domainEntity: { canonicalHost?: string } | undefined,
  integration: Record<string, unknown> | undefined,
): SourceLadderRow[] {
  const missingPlaces = placeStatuses.filter((status) => status.status === "missing").length;
  const snsConnected =
    (integration as { configured?: { services?: { sns?: { status?: string } } }; snsConnected?: boolean } | undefined)
      ?.configured?.services?.sns?.status === "connected" ||
    !!(integration as { snsConnected?: boolean } | undefined)?.snsConnected;

  return [
    {
      priority: 1,
      label: "공식 홈페이지",
      status: domainEntity?.canonicalHost ? "ready" : "weak",
      summary: "브랜드 정의, FAQ, 비교표, Schema, llms.txt가 AI의 기준 출처가 됩니다.",
      nextAction: domainEntity?.canonicalHost ? "페이지별 FAQ/근거 문단을 확장" : "canonical/301/공식 도메인 정리",
    },
    {
      priority: 2,
      label: "공식 Owned Channel",
      status: snsConnected ? "ready" : "weak",
      summary: "공식 SNS, 블로그, 유튜브 등 고객이 직접 통제 가능한 채널입니다.",
      nextAction: "채널 ID/권한 연결 후 GEO형 콘텐츠 초안 생성",
    },
    {
      priority: 3,
      label: "언론/보도자료",
      status: externalSourceSummary.news > 0 ? "ready" : "missing",
      summary: "경제지, 업계지, 보도자료가 AI 추천 근거의 제3자 신뢰 신호가 됩니다.",
      nextAction: "브랜드 USP/연구 근거 중심 보도자료와 언론 소스 확보",
    },
    {
      priority: 4,
      label: "논문/연구/권위 자료",
      status: externalSourceSummary.trustScore >= 60 ? "ready" : externalSourceSummary.trustScore > 0 ? "weak" : "missing",
      summary: "논문, 임상, 특허, 인증, 전문가 자료를 엔티티 그래프로 연결합니다.",
      nextAction: "연구/인증/전문가 프로필을 공식 페이지와 Schema에 연결",
    },
    {
      priority: 5,
      label: "권위 커뮤니티/지식 베이스",
      status: externalSourceSummary.community > 0 ? "weak" : "missing",
      summary: "나무위키, 위키피디아, 주요 지식 베이스에서 브랜드 설명 일관성을 봅니다.",
      nextAction: "엔티티명, 모회사/브랜드 관계, 핵심 근거 불일치 확인",
    },
    {
      priority: 6,
      label: "일반 커뮤니티/리뷰/플레이스",
      status: missingPlaces === 0 && externalSourceSummary.community > 0 ? "ready" : "weak",
      summary: "지도, 플레이스, 리뷰, 카페/블로그에서 소비자 언급과 지역 신호를 수집합니다.",
      nextAction: missingPlaces > 0 ? "GBP/네이버 스마트플레이스/Bing Places 확인" : "리뷰/커뮤니티 질문 대응 콘텐츠 강화",
    },
  ];
}

// ── Keyword cloud ────────────────────────────────────────

export interface CombinedKeyword {
  keyword: string;
  value: number;
  sources: string[];
}

export function combineKeywordClouds(
  keywordClouds: DashboardExecutiveSummary["keywordClouds"] | undefined,
  fallbackKeywordCloud: Array<{ keyword: string; value: number }>,
): CombinedKeyword[] {
  const map = new Map<string, CombinedKeyword>();
  const add = (item: { keyword: string; value: number }, source: string) => {
    const key = item.keyword.trim().toLowerCase();
    if (!key) return;
    const current = map.get(key) || { keyword: item.keyword, value: 0, sources: [] };
    current.value += Number(item.value || 0);
    if (!current.sources.includes(source)) current.sources.push(source);
    map.set(key, current);
  };

  (keywordClouds?.google || []).forEach((item) => add(item, "Google"));
  (keywordClouds?.naver || []).forEach((item) => add(item, "Naver"));
  if (map.size === 0) fallbackKeywordCloud.forEach((item) => add(item, "Crawl"));

  return [...map.values()]
    .sort((a, b) => b.value - a.value)
    .slice(0, 5);
}

// ── Benchmark helpers ────────────────────────────────────

export function latestBenchmarkPoint(
  points: DashboardBenchmarkPoint[] | undefined,
): DashboardBenchmarkPoint | null {
  if (!points || points.length === 0) return null;
  return points[points.length - 1];
}

export function engineRowsFromGenericEngine(
  breakdown: DashboardEngineBreakdown[] | undefined,
): DashboardEngineBreakdown[] {
  return (breakdown ?? []).slice().sort((a, b) => b.mentionRate - a.mentionRate);
}
