import { useState } from "react";
import { Link } from "react-router-dom";
import { ConsoleLog, type ConsoleEntry } from "../../components/ConsoleLog";
import { useCommand } from "../../hooks/useCommand";
import { updateSiteName } from "../../db/boards";
import type { LogLine } from "../../hooks/useCommand";
import type { Board } from "../../db/collections";

const STEP_LABELS: Record<string, string> = {
  crawl: "Crawl",
  seo: "SEO/GEO",
  brand: "Brand",
  keywords: "Keywords",
  competitors: "Competitors",
  geoProbe: "GEO Probe",
  external: "External",
  content: "Content",
  harness: "Synthesis",
  sns: "SNS",
};

const ALL_STEPS = Object.keys(STEP_LABELS);

interface DashboardTopBarProps {
  id: string;
  board: Board | null;
  logLines: LogLine[];
  onReanalyze: () => void;
  reanalyzing: boolean;
}

export function DashboardTopBar({ id, board, logLines, onReanalyze, reanalyzing }: DashboardTopBarProps) {
  const [showLog, setShowLog] = useState(false);
  const [editing, setEditing] = useState(false);
  const [editName, setEditName] = useState("");
  const [retrying, setRetrying] = useState<Set<string>>(new Set());
  const cmd = useCommand(id);

  const stepStatus: Record<string, string> = board?.stepStatus ?? {};
  const entries = Object.entries(stepStatus);
  const failedSteps = entries.filter(([, s]) => s === "failed");
  const runningSteps = entries.filter(([, s]) => s === "running");

  const faviconUrl = board?.domain ? `https://www.google.com/s2/favicons?domain=${board.domain}&sz=32` : null;

  const handleEditStart = () => {
    setEditName(board?.siteName || "");
    setEditing(true);
  };

  const handleEditSave = async () => {
    const name = editName.trim();
    if (name && id) await updateSiteName(id, name);
    setEditing(false);
  };

  const handleRetry = async (step: string) => {
    setRetrying((prev) => new Set(prev).add(step));
    try {
      await cmd.execute("retry_step", { step });
    } finally {
      setRetrying((prev) => { const n = new Set(prev); n.delete(step); return n; });
    }
  };

  const consoleEntries: ConsoleEntry[] = logLines.map((l, i) => ({
    id: `${l.ts}-${i}`,
    type: l.type === "step" ? "info" : l.type === "warning" ? "search" : l.type,
    message: l.message,
    timestamp: l.ts,
  }));

  const domainUrl = board?.url || (board?.domain ? `https://${board.domain}` : null);
  const hasAnyStep = ALL_STEPS.some((step) => stepStatus[step]);
  const overallStatus = board?.status === "complete" ? "완료" : "분석 중";

  return (
    <section className="shell-panel shell-transition overflow-hidden rounded-[24px]">
      <div className="flex flex-col gap-4 px-5 py-5 lg:flex-row lg:items-start lg:justify-between">
        <div className="min-w-0">
          <div className="text-[11px] uppercase tracking-[0.22em] text-[var(--shell-text-soft)]">Workspace Controls</div>
          <div className="mt-3 flex min-w-0 flex-wrap items-center gap-3">
            {faviconUrl ? (
              <img src={faviconUrl} alt="" className="h-6 w-6 rounded-md" onError={(e) => { (e.target as HTMLImageElement).style.display = "none"; }} />
            ) : (
              <div className="grid h-6 w-6 place-items-center rounded-md bg-[var(--shell-accent)] text-xs font-semibold text-white">
                {(board?.siteName || board?.domain || "?")[0]?.toUpperCase()}
              </div>
            )}

            {editing ? (
              <input
                autoFocus
                value={editName}
                onChange={(e) => setEditName(e.target.value)}
                onBlur={handleEditSave}
                onKeyDown={(e) => { if (e.key === "Enter") handleEditSave(); if (e.key === "Escape") setEditing(false); }}
                className="w-64 border-b border-[var(--shell-accent)] bg-transparent px-0 py-0 text-lg font-semibold text-[var(--shell-text)] outline-none"
              />
            ) : (
              <button
                type="button"
                onClick={handleEditStart}
                title="Click to edit"
                className="truncate text-left text-xl font-semibold tracking-[-0.03em] text-[var(--shell-text)] transition-colors hover:text-[var(--shell-accent)]"
              >
                {board?.siteName || board?.domain || "..."}
              </button>
            )}

            {board?.domain && domainUrl && (
              <a href={domainUrl} target="_blank" rel="noopener noreferrer"
                className="inline-flex items-center gap-1 text-sm text-[var(--shell-text-muted)] transition-colors hover:text-[var(--shell-accent)]"
              >
                {board.domain}
              </a>
            )}
          </div>
          <div className="mt-3 flex flex-wrap items-center gap-2 text-xs text-[var(--shell-text-soft)]">
            <span className="rounded-full border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-1">상태 {overallStatus}</span>
            <span className="rounded-full border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-1">{logLines.length} logs</span>
            <span className="rounded-full border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-1">
              {failedSteps.length > 0 ? `${failedSteps.length} failed steps` : "정상 실행 중"}
            </span>
            {runningSteps.length > 0 && (
              <span className="flex items-center gap-1.5 rounded-full bg-[color-mix(in_srgb,var(--shell-accent)_14%,transparent)] px-3 py-1 text-[var(--shell-accent)]">
                <span className="inline-block h-1.5 w-1.5 animate-pulse rounded-full bg-[var(--shell-accent)]" />
                {runningSteps.map(([s]) => STEP_LABELS[s] || s).join(", ")}
              </span>
            )}
          </div>
        </div>

        <div className="flex flex-wrap items-center gap-2">
          <button
            type="button"
            onClick={() => setShowLog((current) => !current)}
            aria-pressed={showLog}
            className={`group shell-transition relative inline-flex items-center gap-2 overflow-hidden rounded-2xl border px-4 py-2 text-sm font-medium tracking-tight backdrop-blur-sm active:scale-[0.98] focus:outline-none focus-visible:ring-2 focus-visible:ring-[var(--shell-accent)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--shell-main)] ${
              showLog
                ? "border-[var(--shell-accent)] bg-[color-mix(in_srgb,var(--shell-accent)_12%,transparent)] text-[var(--shell-accent)] shadow-[0_0_0_1px_color-mix(in_srgb,var(--shell-accent)_30%,transparent)]"
                : "border-[var(--shell-border)] bg-[var(--shell-panel-soft)] text-[var(--shell-text-muted)] hover:-translate-y-[1px] hover:border-[color-mix(in_srgb,var(--shell-accent)_40%,var(--shell-border))] hover:text-[var(--shell-text)] hover:shadow-[0_6px_20px_-10px_color-mix(in_srgb,var(--shell-accent)_50%,transparent)]"
            }`}
          >
            <span className="relative flex h-2 w-2 items-center justify-center" aria-hidden="true">
              <span className={`absolute inline-flex h-full w-full rounded-full opacity-75 ${runningSteps.length > 0 ? "animate-ping bg-[var(--shell-accent)]" : ""}`} />
              <span className={`relative inline-flex h-2 w-2 rounded-full ${runningSteps.length > 0 ? "bg-[var(--shell-accent)]" : showLog ? "bg-[var(--shell-accent)]" : "bg-[var(--shell-text-soft)]"}`} />
            </span>
            <span>Live log</span>
            {logLines.length > 0 && (
              <span
                className={`grid h-5 min-w-[1.25rem] place-items-center rounded-full px-1.5 text-[10px] font-semibold tabular-nums transition-colors ${
                  showLog
                    ? "bg-[var(--shell-accent)] text-white"
                    : "bg-[color-mix(in_srgb,var(--shell-accent)_18%,transparent)] text-[var(--shell-accent)] group-hover:bg-[var(--shell-accent)] group-hover:text-white"
                }`}
              >
                {logLines.length > 99 ? "99+" : logLines.length}
              </span>
            )}
          </button>
          <button
            type="button"
            onClick={onReanalyze}
            disabled={reanalyzing}
            className="shell-transition rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-2 text-sm text-[var(--shell-text-muted)] hover:text-[var(--shell-accent)] disabled:opacity-60"
          >
            {reanalyzing ? "재분석 중..." : "전체 재분석"}
          </button>
          <Link
            to={`/board/${id}/workspace/operations`}
            className="shell-transition rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-2 text-sm text-[var(--shell-text-muted)] hover:text-[var(--shell-accent)]"
          >
            Manage
          </Link>
        </div>
      </div>

      {(showLog || hasAnyStep || failedSteps.length > 0) && (
        <div className="border-t border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-5 py-4">
          {showLog && consoleEntries.length > 0 && (
            <div className="mb-4">
              <ConsoleLog entries={consoleEntries} />
            </div>
          )}
          {showLog && consoleEntries.length === 0 && (
            <div className="mb-4 rounded-[20px] border border-[var(--shell-border)] bg-[var(--shell-panel-strong)] px-4 py-3 font-mono text-[13px] text-[var(--shell-text-soft)]">
              <span className="mr-2">$</span>
              {board?.status === "complete" ? "모든 분석이 완료되었습니다." : "GEO Insight 분석 대기..."}
            </div>
          )}

          <div className="flex flex-wrap gap-2">
            {ALL_STEPS.map((step) => {
              const status = retrying.has(step) ? "retrying" : (stepStatus[step] || "pending");
              const toneClass =
                status === "failed"
                  ? "border-[var(--shell-danger)] bg-[var(--shell-panel-strong)] text-[var(--shell-danger)]"
                  : status === "complete"
                    ? "border-[var(--shell-positive)] bg-[var(--shell-panel-strong)] text-[var(--shell-positive)]"
                    : status === "retrying" || status === "running"
                      ? "border-[var(--shell-accent)] bg-[color-mix(in_srgb,var(--shell-accent)_10%,transparent)] text-[var(--shell-accent)]"
                      : "border-[var(--shell-border)] bg-[var(--shell-panel)] text-[var(--shell-text-muted)]";
              const disabled = retrying.has(step) || status === "running";
              return (
                <button
                  key={step}
                  type="button"
                  onClick={() => handleRetry(step)}
                  disabled={disabled}
                  title={`${STEP_LABELS[step]} 다시 실행`}
                  className={`shell-transition rounded-full border px-3 py-1.5 text-xs disabled:opacity-60 ${toneClass}`}
                >
                  {STEP_LABELS[step]}
                  {status === "retrying" && " …"}
                </button>
              );
            })}
          </div>
        </div>
      )}
    </section>
  );
}
