import type { ComponentType } from "react";

interface EmptyStateProps {
  icon: ComponentType<{ className?: string }>;
  title: string;
  description?: string;
  action?: { label: string; onClick: () => void };
}

export function EmptyState({ icon: Icon, title, description, action }: EmptyStateProps) {
  return (
    <div className="flex flex-col items-center justify-center py-16 text-center">
      <div className="rounded-2xl bg-[var(--shell-panel-soft)] p-4">
        <Icon className="h-8 w-8 text-[var(--shell-text-soft)]" />
      </div>
      <p className="mt-4 text-sm font-medium text-[var(--shell-text)]">{title}</p>
      {description && (
        <p className="mt-1 max-w-sm text-sm text-[var(--shell-text-muted)]">
          {description}
        </p>
      )}
      {action && (
        <button
          onClick={action.onClick}
          className="mt-4 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel)] px-4 py-2 text-sm font-medium text-[var(--shell-text)] transition-colors hover:border-[var(--shell-accent)] hover:text-[var(--shell-accent)]"
        >
          {action.label}
        </button>
      )}
    </div>
  );
}
