import { Routes, Route, Navigate } from "react-router-dom";
import { RequireAuth } from "./components/RequireAuth";
import { BoardLayout } from "./components/BoardLayout";
import { Landing } from "./pages/Landing";
import { Login } from "./pages/Login";
import { Onboarding } from "./pages/Onboarding";
import { AdminUsers } from "./pages/AdminUsers";

import { DashboardV2 } from "./pages/DashboardV2";
import { PortalDashboard } from "./pages/portal/PortalDashboard";
import { PortalInput } from "./pages/portal/PortalInput";
import { PortalWebsite } from "./pages/portal/PortalWebsite";
import { PortalGeoStatus } from "./pages/portal/PortalGeoStatus";
import { PortalQueries } from "./pages/portal/PortalQueries";
import { PortalTechnical } from "./pages/portal/PortalTechnical";
import { PortalTimeline } from "./pages/portal/PortalTimeline";
import { PortalWeeklyReport } from "./pages/portal/PortalWeeklyReport";
import { Home } from "./pages/workspace/Home";
import { Insights } from "./pages/workspace/Insights";
import { ActionsV2 } from "./pages/workspace/ActionsV2";
import { Performance } from "./pages/workspace/Performance";
import { Operations } from "./pages/workspace/Operations";
import { Assets } from "./pages/workspace/Assets";
import { SettingsV2 } from "./pages/workspace/SettingsV2";

export function App() {
  return (
    <Routes>
      <Route path="/login" element={<Login />} />
      <Route element={<RequireAuth />}>
        <Route path="/" element={<Landing />} />
        <Route path="/admin/users" element={<AdminUsers />} />
        <Route path="/onboarding/:id" element={<Onboarding />} />
        <Route path="/board/:id" element={<BoardLayout />}>
          {/* Board Dashboard */}
          <Route index element={<DashboardV2 />} />

          {/* Portal (고객 화면) */}
          <Route path="portal" element={<PortalDashboard />} />
          <Route path="portal/input" element={<PortalInput />} />
          <Route path="portal/website" element={<PortalWebsite />} />
          <Route path="portal/geo-status" element={<PortalGeoStatus />} />
          <Route path="portal/queries" element={<PortalQueries />} />
          <Route path="portal/technical" element={<PortalTechnical />} />
          <Route path="portal/timeline" element={<PortalTimeline />} />
          <Route path="portal/weekly-report" element={<PortalWeeklyReport />} />

          {/* Workspace */}
          <Route path="workspace" element={<Home />} />
          <Route path="workspace/insights" element={<Insights />} />
          <Route path="workspace/insights/:tab" element={<Insights />} />
          <Route path="workspace/actions" element={<ActionsV2 />} />
          <Route path="workspace/actions/:tab" element={<ActionsV2 />} />
          <Route path="workspace/performance" element={<Performance />} />
          <Route path="workspace/performance/:tab" element={<Performance />} />
          <Route path="workspace/operations" element={<Operations />} />
          <Route path="workspace/assets" element={<Assets />} />
          <Route path="workspace/assets/:tab" element={<Assets />} />
          <Route path="workspace/assets/documents/:docKey" element={<Assets />} />
          <Route path="workspace/settings" element={<SettingsV2 />} />
          <Route path="workspace/settings/:tab" element={<SettingsV2 />} />

          {/* Measure -> Insights redirects */}
          <Route path="workspace/measure" element={<Navigate to="../workspace/insights/ai-visibility" replace />} />
          <Route path="workspace/measure/ai-visibility" element={<Navigate to="../workspace/insights/ai-visibility" replace />} />
          <Route path="workspace/measure/search-demand" element={<Navigate to="../workspace/insights/search-demand" replace />} />
          <Route path="workspace/measure/competitors" element={<Navigate to="../workspace/insights/competitors" replace />} />
          <Route path="workspace/measure/trust-signals" element={<Navigate to="../workspace/insights/trust-signals" replace />} />

          {/* Diagnose -> Insights redirects */}
          <Route path="workspace/diagnose" element={<Navigate to="../workspace/insights/board" replace />} />
          <Route path="workspace/diagnose/issues" element={<Navigate to="../workspace/insights/board" replace />} />
          <Route path="workspace/diagnose/seo" element={<Navigate to="../workspace/insights/website-health" replace />} />
          <Route path="workspace/diagnose/geo" element={<Navigate to="../workspace/insights/ai-visibility" replace />} />
          <Route path="workspace/diagnose/health" element={<Navigate to="../workspace/insights/website-health" replace />} />
          <Route path="workspace/diagnose/checks" element={<Navigate to="../workspace/insights/website-health" replace />} />
          <Route path="workspace/diagnose/trust" element={<Navigate to="../workspace/insights/trust-signals" replace />} />
          <Route path="workspace/diagnose/gap" element={<Navigate to="../workspace/insights/board" replace />} />

          <Route path="old/*" element={<Navigate to="workspace" replace />} />
        </Route>
      </Route>
      <Route path="*" element={<Navigate to="/" replace />} />
    </Routes>
  );
}
