import { useMemo } from "react";
import { Link } from "react-router-dom";
import { ArrowRight, ArrowUpRight, ArrowDownRight, Minus, Swords, Star } from "lucide-react";
import { MentionRateTrendChart, computeWeekDelta } from "./components/MentionRateTrendChart";
import {
  usePortalDashboard,
  usePortalCompetitorMentions,
  usePortalTrendSnapshots,
} from "./dataHub";

/** 작은 KPI 카드 — 라벨 + 큰 숫자 + 보조 텍스트. */
function KpiCard({
  label,
  value,
  suffix,
  hint,
  tone,
}: {
  label: string;
  value: number | string;
  suffix?: string;
  hint?: string;
  tone?: "blue" | "green" | "amber" | "red";
}) {
  const toneColor =
    tone === "blue"
      ? "text-blue-300"
      : tone === "green"
        ? "text-emerald-300"
        : tone === "amber"
          ? "text-amber-300"
          : tone === "red"
            ? "text-red-300"
            : "text-[var(--shell-text)]";
  return (
    <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] px-5 py-4">
      <div className="text-[11px] uppercase tracking-[0.18em] text-[var(--shell-text-soft)]">{label}</div>
      <div className="mt-2 flex items-baseline gap-1">
        <div className={`text-3xl font-semibold ${toneColor}`}>{value}</div>
        {suffix && <div className="text-sm text-[var(--shell-text-muted)]">{suffix}</div>}
      </div>
      {hint && <div className="mt-1 text-[11px] text-[var(--shell-text-muted)]">{hint}</div>}
    </div>
  );
}

function priorityToTier(priority: string): "P0" | "P1" | "P2" {
  const p = (priority || "").toLowerCase();
  if (p === "urgent" || p === "critical" || p === "high") return "P0";
  if (p === "medium" || p === "p1") return "P1";
  return "P2";
}

function tierLabel(tier: "P0" | "P1" | "P2"): string {
  if (tier === "P0") return "P0 · 즉시 (1-2주)";
  if (tier === "P1") return "P1 · 단기 (1개월)";
  return "P2 · 중기 (분기)";
}

function deltaIcon(delta: number) {
  if (delta > 0) return <ArrowUpRight className="h-4 w-4 text-emerald-400" />;
  if (delta < 0) return <ArrowDownRight className="h-4 w-4 text-red-400" />;
  return <Minus className="h-4 w-4 text-neutral-400" />;
}

/** 색상 Swatch — "■" 이모지 대체용. */
function Swatch({ className }: { className: string }) {
  return <span className={`inline-block h-2.5 w-2.5 rounded-sm ${className}`} />;
}

export function PortalDashboard() {
  const { data, isLoading } = usePortalDashboard();
  const { data: competitorMentions } = usePortalCompetitorMentions();
  const { data: snapshotsData } = usePortalTrendSnapshots();

  const snapshots = snapshotsData?.snapshots || [];
  const weekDelta = computeWeekDelta(snapshots);

  const scores = useMemo(() => {
    if (!data) return null;
    const exec = data;

    const siteScore = exec?.siteHealth?.score ?? 0;
    const websiteScore = Math.round((siteScore / 100) * 30);

    const mentionRate = exec?.genericEngine?.mentionRate ?? 0;
    const exposureRate = exec?.genericEngine?.exposureRate ?? 0;
    const geoScore = Math.round((mentionRate / 100) * 30);

    const googleKw = (exec?.keywordClouds?.google || []).length;
    const naverKw = (exec?.keywordClouds?.naver || []).length;
    const keywordScore = Math.min(googleKw + naverKw, 20);

    const trustScore = exec?.externalSignals?.trustScore ?? 0;
    const externalScore = Math.round((trustScore / 100) * 20);

    const total = websiteScore + geoScore + keywordScore + externalScore;

    return {
      total,
      websiteScore,
      websiteMax: 30,
      geoScore,
      geoMax: 30,
      keywordScore,
      keywordMax: 20,
      externalScore,
      externalMax: 20,
      mentionRate,
      exposureRate,
      googleKw,
      naverKw,
      trustScore,
      siteScore,
    };
  }, [data]);

  const weeklyHighlights = useMemo(() => {
    if (!data?.activity) return [];
    return data.activity.slice(0, 3).map((a) => {
      const detail = a.details as { summary?: string } | null;
      return {
        text: detail?.summary || a.action || a.entityType,
        when: a.createdAt,
      };
    });
  }, [data]);

  const recommendedActions = data?.nextActions?.recommended || [];

  return (
    <div className="mx-auto max-w-6xl space-y-6 px-4 py-6">
      <header>
        <div className="text-xs uppercase tracking-[0.28em] text-[var(--shell-text-soft)]">Portal / Dashboard</div>
        <h1 className="mt-2 text-3xl font-semibold tracking-tight text-[var(--shell-text)]">종합 현황</h1>
        <p className="mt-2 text-sm text-[var(--shell-text-muted)]">
          ChatGPT·Claude·Gemini 가 우리 브랜드를 답변에서 얼마나 자주 언급하는지 추세 + 종합 점수 + 다음 액션을 한눈에 확인합니다.
        </p>
      </header>

      {isLoading && (
        <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] px-6 py-12 text-center text-sm text-[var(--shell-text-muted)]">
          데이터를 불러오는 중입니다...
        </div>
      )}

      {!isLoading && !data && (
        <div className="rounded-2xl border border-amber-500/30 bg-amber-500/5 px-6 py-8 text-sm text-amber-200">
          아직 분석이 시작되지 않았습니다. 브랜드 정보 입력과 크롤링을 완료하면 종합 현황이 표시됩니다.
        </div>
      )}

      {scores && scores.total === 0 && !data?.hasSummary && (
        <div className="rounded-2xl border border-amber-400 bg-amber-950/70 px-6 py-4 text-sm font-semibold text-amber-300 shadow-sm">
          AI 측정(GEO 프로브) 과 요약 집계가 아직 완료되지 않았습니다. 측정이 끝나면 점수·KPI 가 채워집니다.
        </div>
      )}

      {scores && (
        <>
          <MentionRateTrendChart snapshots={snapshots} />

          <section className="rounded-3xl border border-[var(--shell-border)] bg-gradient-to-br from-[var(--shell-panel-strong)] to-[var(--shell-panel)] px-8 py-7">
            <div className="flex items-end justify-between gap-6">
              <div>
                <div className="text-[11px] uppercase tracking-[0.22em] text-[var(--shell-text-soft)]">GEO 종합 점수</div>
                <div className="mt-3 flex items-baseline gap-3">
                  <div className="text-6xl font-semibold tracking-tight text-[var(--shell-text)]">{scores.total}</div>
                  <div className="text-2xl text-[var(--shell-text-muted)]">/ 100</div>
                </div>
                <div className="mt-3 flex items-center gap-2 text-xs text-[var(--shell-text-muted)]">
                  {weekDelta ? (
                    <>
                      {deltaIcon(weekDelta.delta)}
                      <span>
                        {weekDelta.delta === 0
                          ? "지난주와 동일"
                          : `${weekDelta.delta > 0 ? "↑" : "↓"} ${Math.abs(weekDelta.delta).toFixed(1)}%p — 지난주 ${weekDelta.previous.toFixed(0)}% → 이번주 ${weekDelta.current.toFixed(0)}% (AI 언급률 기준)`}
                      </span>
                    </>
                  ) : (
                    <>
                      {deltaIcon(0)}
                      <span>지난주 대비 변화는 두 번째 측정 후 표시됩니다</span>
                    </>
                  )}
                </div>
              </div>
              <Link
                to="geo-status"
                relative="path"
                className="hidden items-center gap-2 rounded-full border border-[var(--shell-border)] bg-[var(--shell-panel)] px-4 py-2 text-xs text-[var(--shell-text)] hover:bg-[var(--shell-panel-soft)] sm:flex"
              >
                GEO 현황 자세히 보기 <ArrowRight className="h-3.5 w-3.5" />
              </Link>
            </div>
          </section>

          <section className="grid gap-3 md:grid-cols-2 lg:grid-cols-4">
            <KpiCard
              label="웹사이트"
              value={scores.websiteScore}
              suffix={`/ ${scores.websiteMax}`}
              hint={`기술 점수 ${scores.siteScore}/100`}
              tone={scores.websiteScore >= scores.websiteMax * 0.7 ? "green" : scores.websiteScore >= scores.websiteMax * 0.4 ? "blue" : "amber"}
            />
            <KpiCard
              label="GEO 가시성"
              value={scores.geoScore}
              suffix={`/ ${scores.geoMax}`}
              hint={`AI 언급률 ${scores.mentionRate}% · 노출률 ${scores.exposureRate}%`}
              tone={scores.geoScore >= scores.geoMax * 0.5 ? "green" : scores.geoScore >= scores.geoMax * 0.25 ? "blue" : "amber"}
            />
            <KpiCard
              label="키워드"
              value={scores.keywordScore}
              suffix={`/ ${scores.keywordMax}`}
              hint={`Google ${scores.googleKw} · Naver ${scores.naverKw}`}
              tone={scores.keywordScore >= 12 ? "green" : scores.keywordScore >= 5 ? "blue" : "amber"}
            />
            <KpiCard
              label="외부 신뢰성"
              value={scores.externalScore}
              suffix={`/ ${scores.externalMax}`}
              hint={`신뢰 점수 ${scores.trustScore}/100`}
              tone={scores.externalScore >= scores.externalMax * 0.7 ? "green" : scores.externalScore >= scores.externalMax * 0.3 ? "blue" : "amber"}
            />
          </section>

          {competitorMentions && competitorMentions.totalProbesAnalyzed > 0 && (() => {
            const all = [...competitorMentions.userCompetitors, ...competitorMentions.autoDetected];
            const top3 = all.sort((a, b) => b.mentionCount - a.mentionCount).slice(0, 3);
            const competitorTotal = top3.reduce((s, c) => s + c.mentionCount, 0);
            const generic = data?.genericEngine;
            const ourMentions = generic?.engineBreakdown?.reduce((s, e) => s + (e.mentionedCount || 0), 0) || 0;
            const totalUnits = ourMentions + competitorTotal;
            if (totalUnits === 0) return null;
            const ourShare = Math.round((ourMentions / totalUnits) * 100);
            return (
              <section className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
                <div className="flex items-center justify-between">
                  <div className="text-sm font-semibold text-[var(--shell-text)]">경쟁사 대비 점유율 (Share of Voice)</div>
                  <div className="text-xs text-[var(--shell-text-muted)]">우리 {ourShare}%</div>
                </div>
                <div className="mt-3 flex h-3 overflow-hidden rounded-full">
                  <div className="bg-[var(--shell-accent)]" style={{ width: `${(ourMentions / totalUnits) * 100}%` }} title={`우리: ${ourMentions}`} />
                  {top3.map((c, i) => (
                    <div
                      key={i}
                      className={i === 0 ? "bg-red-400" : i === 1 ? "bg-amber-400" : "bg-neutral-400"}
                      style={{ width: `${(c.mentionCount / totalUnits) * 100}%` }}
                      title={`${c.name}: ${c.mentionCount}`}
                    />
                  ))}
                </div>
                <div className="mt-2 flex flex-wrap items-center gap-3 text-[11px]">
                  <span className="flex items-center gap-1.5 text-[var(--shell-accent)]">
                    <Swatch className="bg-[var(--shell-accent)]" /> 우리 ({ourMentions})
                  </span>
                  {top3.map((c, i) => (
                    <span
                      key={i}
                      className={`flex items-center gap-1.5 ${
                        i === 0 ? "text-red-300" : i === 1 ? "text-amber-300" : "text-neutral-300"
                      }`}
                    >
                      <Swatch className={i === 0 ? "bg-red-400" : i === 1 ? "bg-amber-400" : "bg-neutral-400"} />
                      {c.name} ({c.mentionCount})
                    </span>
                  ))}
                </div>
              </section>
            );
          })()}

          {weeklyHighlights.length > 0 && (
            <section className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
              <div className="text-sm font-semibold text-[var(--shell-text)]">최근 활동</div>
              <ul className="mt-3 space-y-2 text-sm text-[var(--shell-text-muted)]">
                {weeklyHighlights.map((h, i) => (
                  <li key={i} className="flex items-start gap-2">
                    <span className="mt-1 inline-block h-1.5 w-1.5 shrink-0 rounded-full bg-[var(--shell-accent)]" />
                    <span className="flex-1">{h.text}</span>
                    <span className="text-[10px] text-[var(--shell-text-soft)]">{new Date(h.when).toLocaleDateString()}</span>
                  </li>
                ))}
              </ul>
            </section>
          )}

          {competitorMentions && (competitorMentions.userCompetitors.length > 0 || competitorMentions.autoDetected.length > 0) && (
            <section className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2 text-sm font-semibold text-[var(--shell-text)]">
                  <Swords className="h-4 w-4 text-[var(--shell-accent)]" />
                  경쟁사 언급
                </div>
                <Link to="geo-status" relative="path" className="text-xs text-[var(--shell-accent)] hover:underline">
                  경쟁사 비교 자세히 →
                </Link>
              </div>
              {!competitorMentions.sentimentAvailable && (
                <div className="mt-2 text-[11px] text-[var(--shell-text-soft)]">
                  sentiment 분석을 실행하면 각 경쟁사 답변 톤(긍정/부정/중립)이 함께 표시됩니다.
                </div>
              )}
              <div className="mt-3 space-y-1.5">
                {[...competitorMentions.userCompetitors, ...competitorMentions.autoDetected].slice(0, 5).map((c, i) => {
                  const total = c.sentimentBreakdown.positive + c.sentimentBreakdown.negative + c.sentimentBreakdown.neutral + c.sentimentBreakdown.unknown;
                  return (
                    <div key={i} className="flex items-center gap-3 rounded-lg bg-[var(--shell-panel-soft)] px-3 py-2 text-sm">
                      <span className="w-5 shrink-0 text-xs text-[var(--shell-text-soft)]">{i + 1}.</span>
                      {c.source === "user" && <Star className="h-3 w-3 shrink-0 fill-amber-300 text-amber-300" />}
                      <span className="flex-1 truncate text-[var(--shell-text)]">{c.name}</span>
                      <span className="shrink-0 text-xs text-[var(--shell-text-muted)]">{c.mentionCount} 회</span>
                      {total > 0 && (
                        <span className="hidden shrink-0 items-center gap-1 sm:flex">
                          {c.sentimentBreakdown.positive > 0 && <span className="text-[10px] text-emerald-300">+{c.sentimentBreakdown.positive}</span>}
                          {c.sentimentBreakdown.negative > 0 && <span className="text-[10px] text-red-300">−{c.sentimentBreakdown.negative}</span>}
                          {c.sentimentBreakdown.neutral > 0 && <span className="text-[10px] text-blue-300">·{c.sentimentBreakdown.neutral}</span>}
                        </span>
                      )}
                    </div>
                  );
                })}
              </div>
            </section>
          )}

          {recommendedActions.length > 0 && (
            <section className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
              <div className="flex items-center justify-between">
                <div>
                  <div className="text-sm font-semibold text-[var(--shell-text)]">
                    다음 액션 — 상시 우선순위 Top {Math.min(recommendedActions.length, 3)}
                  </div>
                  <div className="mt-0.5 text-[10px] text-[var(--shell-text-soft)]">
                    현재 점수·이슈를 기준으로 가장 영향이 큰 액션 — 주간 리포트의 'P0/P1/P2 추천' 과는 다른 시점의 권장입니다
                  </div>
                </div>
                <Link to="technical" relative="path" className="text-xs text-[var(--shell-accent)] hover:underline">
                  전체 액션 보기 →
                </Link>
              </div>
              <ol className="mt-3 space-y-2.5">
                {recommendedActions.slice(0, 3).map((act, i) => {
                  const tier = priorityToTier(act.priority);
                  const tierStyle = tier === "P0"
                    ? "border-red-500/40 bg-red-500/15 text-red-200"
                    : tier === "P1"
                      ? "border-amber-500/40 bg-amber-500/15 text-amber-200"
                      : "border-blue-500/40 bg-blue-500/15 text-blue-200";
                  return (
                    <li key={i} className="flex items-start gap-3 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
                      <div className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-[var(--shell-accent)]/15 text-xs font-semibold text-[var(--shell-accent)]">
                        {i + 1}
                      </div>
                      <div className="flex-1">
                        <div className="flex items-center gap-2">
                          <span className={`shrink-0 rounded-full border px-2 py-0.5 text-[10px] font-semibold ${tierStyle}`}>{tier}</span>
                          <span className="text-sm text-[var(--shell-text)]">{act.title}</span>
                        </div>
                        <div className="mt-1 flex items-center gap-2 text-[11px] text-[var(--shell-text-muted)]">
                          <span className="rounded-full bg-[var(--shell-panel)] px-2 py-0.5">{tierLabel(tier)}</span>
                          {act.impact && <span className="rounded-full bg-[var(--shell-panel)] px-2 py-0.5">영향: {act.impact}</span>}
                        </div>
                      </div>
                    </li>
                  );
                })}
              </ol>
            </section>
          )}
        </>
      )}
    </div>
  );
}
