export type SentimentLabel = "positive" | "negative" | "neutral" | "unknown";

export interface ProbeSentimentRecord {
  probeId: string;
  question: string;
  engine: string;
  ourSiteMentioned: boolean;
  overallSentiment: SentimentLabel;
  excerpt: string;
  answerLength: number;
  createdAt: string;
}

export interface CompetitorSentimentRecord {
  name: string;
  mentionCount: number;
  engines: string[];
  sentimentBreakdown: { positive: number; negative: number; neutral: number; unknown: number };
}

export interface ProbeSentimentsDoc {
  generatedAt: string;
  totalProbesAnalyzed: number;
  brandBreakdown: { positive: number; negative: number; neutral: number; unknown: number };
  records: ProbeSentimentRecord[];
  competitors: CompetitorSentimentRecord[];
  topAnswers: {
    positive: ProbeSentimentRecord[];
    negative: ProbeSentimentRecord[];
    neutral: ProbeSentimentRecord[];
  };
}

export interface ClientCompetitorMention {
  name: string;
  source: "user" | "auto";
  mentionCount: number;
  engines: string[];
  sentimentBreakdown: { positive: number; negative: number; neutral: number; unknown: number };
}

export interface ClientCompetitorMentionsResponse {
  userCompetitors: ClientCompetitorMention[];
  autoDetected: ClientCompetitorMention[];
  totalProbesAnalyzed: number;
  sentimentAvailable: boolean;
}

