// ─── Probe (GEO probe) ─────────────────────────────────────────────

export interface ProbeRecord {
  id: string;
  batchId: string;
  question: string;
  questionCategory: string;
  engine: string;
  status: string;
  answer: string | null;
  references: Array<{ url: string; title: string; domain: string; position: number }> | null;
  ourSiteInResults: boolean;
  ourSiteMentioned: boolean;
  ourMentionContext: string | null;
  ourMentionPosition: number | null;
  competitorsMentioned: Array<{ name: string; url: string; mentionCount: number }> | null;
  sourceKeywords: string[] | null;
  durationMs: number | null;
  createdAt: string;
  completedAt: string | null;
}

// ─── SEO ─────────────────────────────────────────────────────────────

export interface SeoCheck {
  checkId: string;
  title: string;
  status: string;
  score: number;
  maxScore: number;
  description: string;
  fixInstructions: string | null;
  affectedPages: string[];
  category: string;
  label?: string;
  localizedDescription?: string;
  action?: string;
  impact?: string;
  priority?: "high" | "medium" | "low";
  effort?: "easy" | "medium" | "hard";
  tier?: 1 | 2 | 3;
  geoPointsIfFixed?: number;
}

export interface Recommendation {
  ruleId: string;
  label: string;
  description: string;
  action: string;
  impact: string;
  priority: "high" | "medium" | "low";
  effort: "easy" | "medium" | "hard";
  category: "seo" | "geo" | "technical";
  tier?: 1 | 2 | 3;
  estimatedPoints: number;
  affectedPages: string[];
  pageCount: number;
  affectsGeo?: boolean;
}

export interface SeoData {
  score: number | null;
  categories: Record<string, unknown> | null;
  checks: SeoCheck[];
  recommendations: Recommendation[];
  pageScores?: Array<{ url: string; path: string; pageTitle: string | null; seoScore: number; geoScore: number; pageType: string }>;
}

