import { useState } from "react";
import type { Board, BoardDocument } from "../../db/collections";

type ModalType = "llmstxt" | "sitemap" | "robots" | "schema" | null;

interface DashboardModalsProps {
  activeModal: ModalType;
  onClose: () => void;
  docs: BoardDocument[];
  board?: Board | null;
}

export type { ModalType };

const MODAL_CONFIG: Record<Exclude<ModalType, null>, { title: string; docKey: string; description: string; filename: string; mime: string; installHint: string }> = {
  llmstxt: {
    title: "llms.txt",
    docKey: "llmstxt-recommendation",
    description: "AI crawler optimization file that helps LLMs understand your site.",
    filename: "llms.txt",
    mime: "text/plain",
    installHint: "Upload this file to your site root (e.g., yoursite.com/llms.txt). Most hosting providers allow this via FTP or file manager.",
  },
  sitemap: {
    title: "sitemap.xml",
    docKey: "sitemap-recommendation",
    description: "XML sitemap for search engine discovery.",
    filename: "sitemap.xml",
    mime: "application/xml",
    installHint: "Replace your existing sitemap.xml in the site root. Submit the URL in Google Search Console and Naver Search Advisor.",
  },
  robots: {
    title: "robots.txt",
    docKey: "robots-recommendation",
    description: "Robot access control for crawlers.",
    filename: "robots.txt",
    mime: "text/plain",
    installHint: "Replace your existing robots.txt in the site root. Ensure AI bots (GPTBot, ClaudeBot, etc.) are allowed for GEO visibility.",
  },
  schema: {
    title: "Structured Data",
    docKey: "schema-recommendation",
    description: "Schema.org structured data recommendations.",
    filename: "schema.json",
    mime: "application/json",
    installHint: "Add the JSON-LD scripts inside <head> or before </body> on each relevant page. Use Google Rich Results Test to validate.",
  },
};

export function DashboardModals({ activeModal, onClose, docs, board }: DashboardModalsProps) {
  if (!activeModal) return null;

  const config = MODAL_CONFIG[activeModal];
  const doc = docs.find((d) => d.key === config.docKey);

  const siteFiles = board?.siteInfo?.siteFiles;
  const aiCrawlers = board?.siteInfo?.aiCrawlers;

  let currentContent = "";
  if (activeModal === "robots") currentContent = siteFiles?.robots?.content || aiCrawlers?.robotsTxtContent || "";
  else if (activeModal === "sitemap") currentContent = siteFiles?.sitemap?.content || "";
  else if (activeModal === "llmstxt") currentContent = siteFiles?.llms?.content || aiCrawlers?.llmsTxtContent || "";

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60" onClick={onClose}>
      <div className="mx-4 w-full max-w-2xl rounded-[22px] border border-[var(--shell-border)] bg-[var(--shell-panel)] shadow-2xl" onClick={(e) => e.stopPropagation()}>
        <div className="flex items-center justify-between border-b border-[var(--shell-border)] px-6 py-4">
          <div>
            <div className="text-lg font-semibold text-[var(--shell-text)]">{config.title}</div>
            <div className="mt-0.5 text-xs text-[var(--shell-text-muted)]">{config.description}</div>
          </div>
          <button onClick={onClose} className="shell-transition grid h-8 w-8 place-items-center rounded-lg border border-[var(--shell-border)] text-[var(--shell-text-muted)] hover:text-[var(--shell-text)]">
            <svg viewBox="0 0 20 20" fill="currentColor" className="h-4 w-4"><path d="M6.28 5.22a.75.75 0 00-1.06 1.06L8.94 10l-3.72 3.72a.75.75 0 101.06 1.06L10 11.06l3.72 3.72a.75.75 0 101.06-1.06L11.06 10l3.72-3.72a.75.75 0 00-1.06-1.06L10 8.94 6.28 5.22z" /></svg>
          </button>
        </div>

        <div className="max-h-[60vh] overflow-y-auto px-6 py-5">
          {doc ? (
            <ModalContent
              doc={doc}
              currentContent={currentContent}
              filename={config.filename}
              mime={config.mime}
              installHint={config.installHint}
            />
          ) : (
            <div className="py-8 text-center text-sm text-[var(--shell-text-soft)]">
              No recommendations available yet. Run analysis to generate.
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

function ModalContent({ doc, currentContent, filename, mime, installHint }: {
  doc: BoardDocument;
  currentContent: string;
  filename: string;
  mime: string;
  installHint: string;
}) {
  const data = doc.data as Record<string, any> | undefined;
  const recCurrent = (data?.current as string) ?? "";
  const recommendedContent = (data?.recommended as string) ?? doc.body ?? "";
  const hasCurrent = !!(currentContent || recCurrent);
  const [showRecommended, setShowRecommended] = useState(true);

  const displayedContent = showRecommended ? recommendedContent : (currentContent || recCurrent || "No current content found.");

  const handleDownload = () => {
    const blob = new Blob([displayedContent], { type: mime });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = filename;
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div className="space-y-4">
      {hasCurrent && recommendedContent && (
        <div className="flex gap-1 border-b border-[var(--shell-border)]">
          <button onClick={() => setShowRecommended(false)}
            className={`border-b-2 px-3 py-2 text-xs ${!showRecommended ? "border-[var(--shell-accent)] text-[var(--shell-accent)]" : "border-transparent text-[var(--shell-text-muted)]"}`}
          >Current</button>
          <button onClick={() => setShowRecommended(true)}
            className={`border-b-2 px-3 py-2 text-xs ${showRecommended ? "border-[var(--shell-accent)] text-[var(--shell-accent)]" : "border-transparent text-[var(--shell-text-muted)]"}`}
          >Recommended</button>
        </div>
      )}

      <pre className="max-h-[400px] overflow-auto rounded-lg border border-[var(--shell-border)] bg-[var(--shell-main)] p-4 font-mono text-xs leading-5 text-[var(--shell-text)]">
        {displayedContent || "No content available."}
      </pre>

      <div className="flex items-center gap-2">
        <button onClick={() => navigator.clipboard.writeText(displayedContent)}
          className="shell-button-secondary rounded-lg px-4 py-2 text-xs"
        >Copy to Clipboard</button>
        <button onClick={handleDownload}
          className="shell-button-secondary rounded-lg px-4 py-2 text-xs"
        >Download {filename}</button>
      </div>

      <div className="rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-3">
        <div className="mb-1 text-[10px] uppercase tracking-[0.14em] text-[var(--shell-text-soft)]">Installation</div>
        <div className="text-xs leading-5 text-[var(--shell-text-muted)]">{installHint}</div>
      </div>
    </div>
  );
}
