import { useEffect, useMemo, useState } from "react";
import { useParams } from "react-router-dom";
import {
  AlertTriangle,
  Fingerprint,
  Globe,
  Hash,
  Lightbulb,
  MessageSquare,
  Tag,
  Users,
} from "lucide-react";
import { getDoc } from "firebase/firestore";
import { paths } from "../../../db/paths";
import { getDocument, getSummary, subscribeBoard, subscribeInsights } from "../../../db/boards";
import type { Board, InsightDoc } from "../../../db/collections";
import { MetricCard } from "../../../components/shared/MetricCard";
import { EmptyState } from "../../../components/shared/EmptyState";
import { InsightSection } from "../../../components/shared/InsightSection";
import { DataQualityBadge } from "../../../components/shared/DataQualityBadge";

interface BrandSummary {
  name?: string;
  title?: string;
  description?: string;
  overview?: string;
  industry?: string;
  tags?: string[];
  rawKeywords?: string[];
  tagline?: string;
  valueProp?: string;
  uniqueValue?: string;
  tone?: string;
  voice?: string;
  audience?: string | string[];
  targetAudience?: string | string[];
}

interface DomainEntity {
  canonicalHost?: string;
  entityName?: string;
  officialSources?: Array<{ type: string; url: string; verified: boolean }>;
}

export function BrandIdentityInsight() {
  const { id } = useParams<{ id: string }>();
  const [board, setBoard] = useState<Board | null>(null);
  const [brand, setBrand] = useState<BrandSummary | null>(null);
  const [domainEntity, setDomainEntity] = useState<DomainEntity | null>(null);
  const [brandDoc, setBrandDoc] = useState<Record<string, unknown> | null>(null);
  const [brandGap, setBrandGap] = useState<Record<string, unknown> | null>(null);
  const [insightCards, setInsightCards] = useState<InsightDoc[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!id) return;
    setLoading(true);
    const unsubBoard = subscribeBoard(id, setBoard);
    const unsubInsights = subscribeInsights(id, setInsightCards, {
      type: "brand_identity",
    });
    Promise.all([
      getDoc(paths.summary(id, "brand")).catch(() => null),
      getDoc(paths.summary(id, "domain-entity")).catch(() => null),
      getDocument(id, "brand-analysis").catch(() => null),
      getSummary(id, "brand-gap").catch(() => null),
    ]).then(([brandSnap, entitySnap, brandAnalysis, gap]) => {
      setBrand((brandSnap?.data()?.data as BrandSummary) ?? null);
      setDomainEntity((entitySnap?.data()?.data as DomainEntity) ?? null);
      setBrandDoc((brandAnalysis?.data as Record<string, unknown>) ?? null);
      setBrandGap((gap as Record<string, unknown>) ?? null);
      setLoading(false);
    });
    return () => {
      unsubBoard();
      unsubInsights();
    };
  }, [id]);

  const openInsightCards = useMemo(
    () => insightCards.filter((i) => i.status !== "resolved" && i.status !== "ignored"),
    [insightCards],
  );

  const identityName = brand?.name || board?.siteName || domainEntity?.entityName || "--";
  const industry = brand?.industry || board?.siteInfo?.industry || "--";
  const tagline = brand?.tagline || (brandDoc?.tagline as string | undefined) || "";
  const valueProp = brand?.valueProp || brand?.uniqueValue || (brandDoc?.valueProposition as string | undefined) || "";
  const description = brand?.description || brand?.overview || board?.siteInfo?.description || "";
  const tone = brand?.tone || (brandDoc?.tone as string | undefined) || "";
  const voice = brand?.voice || (brandDoc?.voice as string | undefined) || "";
  const rawKeywords = brand?.rawKeywords ?? board?.rawKeywords ?? [];
  const tags = brand?.tags ?? [];
  const audiences = normalizeAudience(brand?.audience ?? brand?.targetAudience ?? (brandDoc?.audience as unknown));
  const officialSources = domainEntity?.officialSources ?? [];
  const verifiedCount = officialSources.filter((s) => s.verified).length;

  const diagnosis = useMemo(() => {
    const items: Array<{ severity: "high" | "medium" | "low"; title: string; detail: string }> = [];
    if (!brand?.name && !board?.siteName) {
      items.push({ severity: "high", title: "Brand name missing", detail: "Run onboarding to capture your brand name and core identity." });
    }
    if (!description) {
      items.push({ severity: "medium", title: "No brand description", detail: "A concise description helps AI engines understand your brand." });
    }
    if (!tagline && !valueProp) {
      items.push({ severity: "medium", title: "No tagline or value proposition", detail: "Clarify what makes your brand unique in one sentence." });
    }
    if (rawKeywords.length === 0 && tags.length === 0) {
      items.push({ severity: "medium", title: "No brand keywords", detail: "Define keywords that represent your brand identity." });
    }
    if (officialSources.length > 0 && verifiedCount === 0) {
      items.push({ severity: "low", title: "Official sources unverified", detail: "Verify official profiles to strengthen brand entity signals." });
    }
    return items;
  }, [brand, board, description, tagline, valueProp, rawKeywords.length, tags.length, officialSources.length, verifiedCount]);

  const dataQuality = useMemo(() => {
    const signals = [
      { name: "Brand summary", ok: !!brand },
      { name: "Identity fields (name, description)", ok: !!(brand?.name || board?.siteName) && !!description },
      { name: "Keywords", ok: rawKeywords.length > 0 || tags.length > 0 },
      { name: "Domain entity", ok: !!domainEntity },
    ];
    const okCount = signals.filter((s) => s.ok).length;
    const score = Math.round((okCount / signals.length) * 100);
    const status: "ok" | "warning" | "degraded" | "invalid" =
      score >= 80 ? "ok" : score >= 50 ? "warning" : score > 0 ? "degraded" : "invalid";
    const notes = signals.filter((s) => !s.ok).map((s) => `${s.name} not available`);
    return { score, status, notes };
  }, [brand, board, description, rawKeywords.length, tags.length, domainEntity]);

  if (loading) {
    return (
      <div className="flex min-h-[30vh] items-center justify-center text-sm text-[var(--shell-text-muted)]">
        불러오는 중...
      </div>
    );
  }

  if (!brand && !board) {
    return (
      <EmptyState
        icon={Fingerprint}
        title="No brand identity data yet"
        description="온보딩과 전체 분석을 실행하면 브랜드명, 톤앤보이스, 타겟 고객, 엔티티 신호를 수집합니다."
      />
    );
  }

  return (
    <div className="space-y-6">
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <MetricCard icon={Fingerprint} label="Brand" value={identityName} color="text-blue-600" />
        <MetricCard icon={Tag} label="Industry" value={industry} color="text-teal-600" />
        <MetricCard icon={Hash} label="Keywords" value={String(rawKeywords.length)} color="text-cyan-600" />
        <MetricCard icon={Globe} label="Official Sources" value={`${verifiedCount}/${officialSources.length || 0}`} color="text-emerald-600" />
      </div>

      <DataQualityBadge score={dataQuality.score} status={dataQuality.status} notes={dataQuality.notes} />

      {openInsightCards.length > 0 && (
        <InsightSection title="Brand Gaps" icon={AlertTriangle} count={openInsightCards.length} defaultOpen>
          <div className="space-y-2">
            {openInsightCards.slice(0, 12).map((ins) => (
              <div key={ins.id} className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
                <div className="flex items-center justify-between gap-2">
                  <p className="text-sm font-medium text-[var(--shell-text)]">{ins.title}</p>
                  <span className={`rounded-md px-1.5 py-0.5 text-[10px] font-medium ${
                    ins.severity === "critical" ? "bg-rose-500/10 text-rose-500"
                      : ins.severity === "warning" ? "bg-amber-500/10 text-amber-500"
                      : "bg-blue-400/10 text-blue-500"
                  }`}>
                    {ins.severity}
                  </span>
                </div>
                {ins.summary && (
                  <p className="mt-1 text-xs text-[var(--shell-text-muted)]">{ins.summary}</p>
                )}
                {ins.suggestion && (
                  <p className="mt-1 text-xs text-[var(--shell-text)]">{ins.suggestion}</p>
                )}
              </div>
            ))}
          </div>
        </InsightSection>
      )}

      {brandGap && typeof (brandGap as { summary?: string }).summary === "string" && (
        <InsightSection title="Brand Gap Summary" icon={Lightbulb} defaultOpen={false}>
          <p className="text-sm leading-relaxed text-[var(--shell-text-muted)]">
            {(brandGap as { summary?: string }).summary}
          </p>
        </InsightSection>
      )}

      <InsightSection title="Brand Statement" icon={MessageSquare} defaultOpen>
        <div className="space-y-3">
          {tagline && <BrandField label="Tagline" value={tagline} />}
          {valueProp && <BrandField label="Value Proposition" value={valueProp} />}
          {description && <BrandField label="Description" value={description} />}
          {!tagline && !valueProp && !description && (
            <p className="text-sm text-[var(--shell-text-muted)]">
              No brand statement captured yet.
            </p>
          )}
        </div>
      </InsightSection>

      {(tone || voice) && (
        <InsightSection title="Voice & Tone" icon={MessageSquare} defaultOpen>
          <div className="grid gap-3 sm:grid-cols-2">
            {voice && <BrandField label="Voice" value={voice} />}
            {tone && <BrandField label="Tone" value={tone} />}
          </div>
        </InsightSection>
      )}

      {audiences.length > 0 && (
        <InsightSection title="Target Audience" icon={Users} count={audiences.length} defaultOpen>
          <div className="flex flex-wrap gap-2">
            {audiences.map((a, i) => (
              <span key={i} className="rounded-full border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-1 text-xs text-[var(--shell-text)]">
                {a}
              </span>
            ))}
          </div>
        </InsightSection>
      )}

      {(rawKeywords.length > 0 || tags.length > 0) && (
        <InsightSection title="Brand Keywords & Tags" icon={Hash} count={rawKeywords.length + tags.length} defaultOpen={false}>
          {rawKeywords.length > 0 && (
            <div className="mb-3">
              <p className="mb-2 text-xs font-semibold text-[var(--shell-text-muted)]">Keywords</p>
              <div className="flex flex-wrap gap-2">
                {rawKeywords.slice(0, 30).map((k, i) => (
                  <span key={i} className="rounded-full bg-blue-500/10 px-2.5 py-1 text-xs font-medium text-blue-600">
                    {k}
                  </span>
                ))}
              </div>
            </div>
          )}
          {tags.length > 0 && (
            <div>
              <p className="mb-2 text-xs font-semibold text-[var(--shell-text-muted)]">Tags</p>
              <div className="flex flex-wrap gap-2">
                {tags.map((t, i) => (
                  <span key={i} className="rounded-full bg-emerald-500/10 px-2.5 py-1 text-xs font-medium text-emerald-600">
                    {t}
                  </span>
                ))}
              </div>
            </div>
          )}
        </InsightSection>
      )}

      {officialSources.length > 0 && (
        <InsightSection title="Official Sources" icon={Globe} count={officialSources.length} defaultOpen={false}>
          <div className="grid gap-2 sm:grid-cols-2">
            {officialSources.map((s, i) => (
              <a
                key={i}
                href={s.url}
                target="_blank"
                rel="noopener noreferrer"
                className="flex items-start justify-between gap-3 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3 transition-colors hover:border-[var(--shell-accent)]"
              >
                <div className="min-w-0 flex-1">
                  <p className="text-xs font-semibold text-[var(--shell-text-muted)]">{s.type}</p>
                  <p className="mt-0.5 truncate text-sm text-[var(--shell-text)]">{s.url}</p>
                </div>
                <span className={`rounded-full px-2 py-0.5 text-[10px] font-medium ${s.verified ? "bg-emerald-500/10 text-emerald-600" : "bg-amber-500/10 text-amber-600"}`}>
                  {s.verified ? "Verified" : "Unverified"}
                </span>
              </a>
            ))}
          </div>
        </InsightSection>
      )}

      <InsightSection title="Diagnosis" icon={AlertTriangle} count={diagnosis.length} defaultOpen={diagnosis.length > 0}>
        {diagnosis.length > 0 ? (
          <div className="space-y-2">
            {diagnosis.map((item, i) => (
              <div key={i} className="flex items-start gap-3 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
                <SeverityDot severity={item.severity} />
                <div className="min-w-0 flex-1">
                  <p className="text-sm font-medium text-[var(--shell-text)]">{item.title}</p>
                  <p className="mt-0.5 text-xs text-[var(--shell-text-muted)]">{item.detail}</p>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="flex items-center gap-2 text-sm text-emerald-600">
            <Lightbulb className="h-4 w-4" />
            Brand identity is well-defined.
          </div>
        )}
      </InsightSection>
    </div>
  );
}

function BrandField({ label, value }: { label: string; value: string }) {
  return (
    <div className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-4">
      <p className="text-xs font-semibold text-[var(--shell-text-muted)]">{label}</p>
      <p className="mt-1.5 text-sm leading-relaxed text-[var(--shell-text)]">{value}</p>
    </div>
  );
}

function SeverityDot({ severity }: { severity: "high" | "medium" | "low" }) {
  const color = severity === "high" ? "bg-rose-500" : severity === "medium" ? "bg-amber-500" : "bg-blue-500";
  return <span className={`mt-1.5 inline-block h-2 w-2 shrink-0 rounded-full ${color}`} />;
}

function normalizeAudience(val: unknown): string[] {
  if (!val) return [];
  if (Array.isArray(val)) return val.map((v) => String(v)).filter(Boolean);
  if (typeof val === "string") return val.split(/[;,]/).map((s) => s.trim()).filter(Boolean);
  return [];
}
