import { useState } from "react";

interface StructuredDataModalProps {
  open: boolean;
  onClose: () => void;
  seoAudit: Record<string, any> | null;
}

interface MetaTag {
  name: string;
  content: string | null;
  exists: boolean;
}

interface SchemaRec {
  pageUrl: string;
  pageTitle?: string;
  metaTags: MetaTag[];
  jsonLd: Array<{ type: string; schema: Record<string, any> }>;
}

export function StructuredDataModal({ open, onClose, seoAudit }: StructuredDataModalProps) {
  const [selectedPage, setSelectedPage] = useState(0);
  const [activeTab, setActiveTab] = useState<"meta" | "jsonld">("meta");

  if (!open) return null;

  const schemaRecs: SchemaRec[] = (seoAudit as any)?.categories?.schemaRecommendations ?? [];
  const metaRecs = (seoAudit as any)?.categories?.metaRecommendations ?? [];

  const pages = schemaRecs.length > 0 ? schemaRecs : metaRecs.map((m: any) => ({
    pageUrl: m.pageUrl || m.url || "Unknown",
    pageTitle: m.pageTitle || m.title,
    metaTags: m.tags || [],
    jsonLd: m.schemas || [],
  }));

  const currentPage = pages[selectedPage] as SchemaRec | undefined;

  const handleCopyAll = () => {
    if (!currentPage) return;
    const schemas = currentPage.jsonLd.map((j) => JSON.stringify(j.schema, null, 2)).join("\n\n");
    navigator.clipboard.writeText(schemas);
  };

  const handleCopySchema = (schema: Record<string, any>) => {
    const script = `<script type="application/ld+json">\n${JSON.stringify(schema, null, 2)}\n</script>`;
    navigator.clipboard.writeText(script);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60" onClick={onClose}>
      <div className="mx-4 w-full max-w-3xl rounded-[22px] border border-[var(--shell-border)] bg-[var(--shell-panel)] shadow-2xl" onClick={(e) => e.stopPropagation()}>
        <div className="flex items-center justify-between border-b border-[var(--shell-border)] px-6 py-4">
          <div>
            <div className="text-lg font-semibold text-[var(--shell-text)]">Structured Data</div>
            <div className="mt-0.5 text-xs text-[var(--shell-text-muted)]">Meta tags and JSON-LD schema recommendations</div>
          </div>
          <button onClick={onClose} className="shell-transition grid h-8 w-8 place-items-center rounded-lg border border-[var(--shell-border)] text-[var(--shell-text-muted)] hover:text-[var(--shell-text)]">
            <svg viewBox="0 0 20 20" fill="currentColor" className="h-4 w-4"><path d="M6.28 5.22a.75.75 0 00-1.06 1.06L8.94 10l-3.72 3.72a.75.75 0 101.06 1.06L10 11.06l3.72 3.72a.75.75 0 101.06-1.06L11.06 10l3.72-3.72a.75.75 0 00-1.06-1.06L10 8.94 6.28 5.22z" /></svg>
          </button>
        </div>

        <div className="max-h-[70vh] overflow-y-auto px-6 py-5">
          {pages.length === 0 ? (
            <div className="py-8 text-center text-sm text-[var(--shell-text-soft)]">
              No structured data recommendations available yet.
            </div>
          ) : (
            <div className="space-y-4">
              {/* Page selector */}
              {pages.length > 1 && (
                <select
                  value={selectedPage}
                  onChange={(e) => setSelectedPage(Number(e.target.value))}
                  className="shell-input w-full rounded-lg px-3 py-2 text-sm"
                >
                  {pages.map((p: SchemaRec, i: number) => (
                    <option key={i} value={i}>{p.pageTitle || p.pageUrl}</option>
                  ))}
                </select>
              )}

              {currentPage && (
                <>
                  <div className="text-xs text-[var(--shell-text-muted)]">{currentPage.pageUrl}</div>

                  {/* Tabs */}
                  <div className="flex gap-1 border-b border-[var(--shell-border)]">
                    <button onClick={() => setActiveTab("meta")}
                      className={`border-b-2 px-3 py-2 text-xs ${activeTab === "meta" ? "border-[var(--shell-accent)] text-[var(--shell-accent)]" : "border-transparent text-[var(--shell-text-muted)]"}`}
                    >Meta Tags</button>
                    <button onClick={() => setActiveTab("jsonld")}
                      className={`border-b-2 px-3 py-2 text-xs ${activeTab === "jsonld" ? "border-[var(--shell-accent)] text-[var(--shell-accent)]" : "border-transparent text-[var(--shell-text-muted)]"}`}
                    >JSON-LD</button>
                  </div>

                  {activeTab === "meta" && (
                    <div className="space-y-2">
                      {currentPage.metaTags && currentPage.metaTags.length > 0 ? (
                        currentPage.metaTags.map((tag) => (
                          <div key={tag.name} className="flex items-center justify-between gap-3 rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-2">
                            <div>
                              <div className="text-xs font-medium text-[var(--shell-text)]">{tag.name}</div>
                              {tag.content && <div className="mt-0.5 text-[11px] text-[var(--shell-text-muted)] line-clamp-2">{tag.content}</div>}
                            </div>
                            <span className={`shrink-0 rounded px-1.5 py-0.5 text-[9px] font-medium ${
                              tag.exists
                                ? "bg-[color-mix(in_srgb,var(--shell-positive)_14%,transparent)] text-[var(--shell-positive)]"
                                : "bg-[color-mix(in_srgb,var(--shell-danger)_14%,transparent)] text-[var(--shell-danger)]"
                            }`}>
                              {tag.exists ? "Present" : "Missing"}
                            </span>
                          </div>
                        ))
                      ) : (
                        <div className="py-4 text-center text-xs text-[var(--shell-text-soft)]">No meta tag data for this page.</div>
                      )}
                    </div>
                  )}

                  {activeTab === "jsonld" && (
                    <div className="space-y-3">
                      {currentPage.jsonLd && currentPage.jsonLd.length > 0 ? (
                        <>
                          <div className="flex justify-end">
                            <button onClick={handleCopyAll} className="shell-button-secondary rounded-lg px-3 py-1.5 text-[11px]">
                              Copy All Schemas
                            </button>
                          </div>
                          {currentPage.jsonLd.map((j, i) => (
                            <div key={i} className="rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)]">
                              <div className="flex items-center justify-between border-b border-[var(--shell-border)] px-3 py-2">
                                <span className="text-xs font-medium text-[var(--shell-text)]">{j.type}</span>
                                <button onClick={() => handleCopySchema(j.schema)} className="rounded bg-[var(--shell-panel-strong)] px-2 py-0.5 text-[10px] text-[var(--shell-text-muted)] hover:text-[var(--shell-text)]">
                                  Copy
                                </button>
                              </div>
                              <pre className="max-h-[200px] overflow-auto p-3 font-mono text-[11px] leading-5 text-[var(--shell-text-muted)]">
                                {JSON.stringify(j.schema, null, 2)}
                              </pre>
                            </div>
                          ))}
                        </>
                      ) : (
                        <div className="py-4 text-center text-xs text-[var(--shell-text-soft)]">No JSON-LD schemas for this page.</div>
                      )}
                    </div>
                  )}
                </>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
