import { useEffect, useState, useRef } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { subscribeBoard, subscribeLiveEvents } from "../db/boards";
import type { Board, CommandDoc, StepName, StepStatus } from "../db/collections";
import type { LogLine } from "../hooks/useCommand";
import {
  query,
  where,
  orderBy,
  limit,
  onSnapshot,
} from "firebase/firestore";
import { paths } from "../db/paths";
import { CACHE_KEYS, LocalCache } from "../contexts/LocalCacheContext";
import { CheckCircle2, XCircle, Loader2 } from "lucide-react";

type Phase = "intro" | "crawling" | "analyzing" | "done" | "failed";

// Pipeline wave structure matching server orchestrator
interface PipelineStep {
  key: StepName;
  label: string;
  weight: number;
}

interface PipelineWave {
  key: string;
  label: string;
  steps: PipelineStep[];
}

// Weights roughly reflect relative runtime so progress grows smoothly.
// Total weight = 100.
const PIPELINE_WAVES: PipelineWave[] = [
  {
    key: "crawl",
    label: "수집",
    steps: [{ key: "crawl", label: "Crawl", weight: 10 }],
  },
  {
    key: "audit",
    label: "감사",
    steps: [
      { key: "seo", label: "SEO", weight: 10 },
      { key: "brand", label: "Brand", weight: 10 },
    ],
  },
  {
    key: "discover",
    label: "탐색",
    steps: [
      { key: "keywords", label: "Keywords", weight: 10 },
      { key: "competitors", label: "Competitors", weight: 10 },
      { key: "geoProbe", label: "GEO Probe", weight: 25 },
    ],
  },
  {
    key: "analyze",
    label: "분석",
    steps: [{ key: "external", label: "External", weight: 10 }],
  },
  {
    key: "synthesize",
    label: "종합",
    steps: [
      { key: "content", label: "Content", weight: 8 },
      { key: "harness", label: "Harness", weight: 7 },
    ],
  },
];

const ALL_STEPS: PipelineStep[] = PIPELINE_WAVES.flatMap((w) => w.steps);

// Parse log lines like "프로브 진행: 24/30 완료" and return a fractional
// progress (0..1) for steps that expose sub-progress in their logs.
function parseStepSubProgress(
  logLines: LogLine[],
): Partial<Record<StepName, number>> {
  const out: Partial<Record<StepName, number>> = {};
  // Walk newest-first so the latest fraction wins.
  for (let i = logLines.length - 1; i >= 0; i--) {
    const msg = logLines[i]?.message ?? "";
    if (out.geoProbe === undefined) {
      const m = msg.match(/프로브[\s\u00A0]*진행[:\s\u00A0]*(\d+)\s*\/\s*(\d+)/);
      if (m) {
        const done = Number(m[1]);
        const total = Number(m[2]);
        if (total > 0) out.geoProbe = Math.min(1, done / total);
      }
    }
    if (out.geoProbe !== undefined) break;
  }
  return out;
}

function computeTargetPct(
  phase: Phase,
  stepStatus: Partial<Record<StepName, StepStatus>>,
  subProgress: Partial<Record<StepName, number>>,
): number {
  if (phase === "done") return 100;
  if (phase === "intro") return 2;

  let acc = 0;
  for (const step of ALL_STEPS) {
    const s = stepStatus[step.key] ?? "idle";
    if (s === "complete" || s === "failed") {
      acc += step.weight;
    } else if (s === "running") {
      const frac = subProgress[step.key];
      // Use sub-progress when available; otherwise assume ~50% through the step.
      // Clamp to [0.1, 0.95] so we always show movement without looking done.
      const running = frac !== undefined ? Math.min(0.95, Math.max(0.1, frac)) : 0.5;
      acc += step.weight * running;
    } else if (s === "pending") {
      acc += step.weight * 0.1;
    }
  }
  if (phase === "crawling" && acc < 4) acc = 4;
  return Math.min(98, Math.round(acc));
}

const PHASE_MESSAGES: Record<Phase, string> = {
  intro: "사이트 분석을 준비하고 있습니다...",
  crawling: "사이트 페이지를 수집하고 있습니다",
  analyzing: "데이터를 분석하고 있습니다",
  done: "분석 완료! 잠시 후 대시보드로 이동합니다",
  failed: "분석 중 오류가 발생했습니다",
};

function getWaveStatus(
  wave: PipelineWave,
  stepStatus: Partial<Record<StepName, StepStatus>>,
): StepStatus {
  const statuses = wave.steps.map((s) => stepStatus[s.key] ?? "idle");
  if (statuses.some((s) => s === "running")) return "running";
  if (statuses.every((s) => s === "complete")) return "complete";
  if (statuses.some((s) => s === "failed")) {
    return statuses.every((s) => s === "complete" || s === "failed")
      ? "failed"
      : "running";
  }
  if (statuses.some((s) => s === "pending")) return "pending";
  return "idle";
}

export function Onboarding() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [phase, setPhase] = useState<Phase>("intro");
  const [board, setBoard] = useState<Board | null>(null);
  const [displayPct, setDisplayPct] = useState(0);
  const [cmdMessage, setCmdMessage] = useState("");
  const [cmdError, setCmdError] = useState<string | null>(null);
  const fallbackRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const [logLines, setLogLines] = useState<LogLine[]>([]);
  const [visibleLine, setVisibleLine] = useState<LogLine | null>(null);
  const [lineFade, setLineFade] = useState(true);
  const lastLogCountRef = useRef(0);

  useEffect(() => {
    if (!id) return;

    const introTimer = setTimeout(() => {
      setPhase((prev) => (prev === "intro" ? "crawling" : prev));
    }, 1500);

    const unsubBoard = subscribeBoard(id, (b) => {
      if (!b) return;
      setBoard(b);

      if (b.status === "complete") {
        setPhase("done");
        setTimeout(() => navigate(`/board/${id}/portal`, { replace: true }), 1200);
      } else if (b.status === "failed") {
        setPhase("failed");
      } else if (b.status === "analyzing") {
        setPhase("analyzing");
      } else if (b.status === "crawling") {
        setPhase("crawling");
      }
    });

    const cmdQuery = query(
      paths.commands(id),
      where("type", "==", "onboard"),
      orderBy("createdAt", "desc"),
      limit(1),
    );
    const unsubCmd = onSnapshot(cmdQuery, (snap) => {
      if (snap.empty) return;
      const data = snap.docs[0].data() as Omit<CommandDoc, "id">;
      setCmdMessage(data.message ?? "");
      if (data.status === "failed") {
        setCmdError(data.error ?? "알 수 없는 오류가 발생했습니다.");
        setPhase("failed");
      }
      if (data.status === "complete") {
        setPhase("done");
        setTimeout(() => navigate(`/board/${id}/portal`, { replace: true }), 1200);
      }
    });

    const unsubLive = subscribeLiveEvents(id, (data) => {
      if (!data) return;
      setLogLines((data.logLines ?? []) as LogLine[]);
    });

    fallbackRef.current = setTimeout(() => {
      navigate(`/board/${id}/portal`, { replace: true });
    }, 180_000);

    return () => {
      clearTimeout(introTimer);
      if (fallbackRef.current) clearTimeout(fallbackRef.current);
      unsubBoard();
      unsubCmd();
      unsubLive();
    };
  }, [id, navigate]);

  // When new log lines arrive, show the latest one with a fade-in transition
  useEffect(() => {
    if (logLines.length === 0) return;
    if (logLines.length === lastLogCountRef.current) return;
    lastLogCountRef.current = logLines.length;
    const latest = logLines[logLines.length - 1];
    setLineFade(false);
    const fadeInTimer = setTimeout(() => {
      setVisibleLine(latest);
      setLineFade(true);
    }, 150);
    return () => clearTimeout(fadeInTimer);
  }, [logLines]);

  const stepStatus: Partial<Record<StepName, StepStatus>> =
    board?.stepStatus ?? {};
  const subProgress = parseStepSubProgress(logLines);
  const targetPct = computeTargetPct(phase, stepStatus, subProgress);

  // Smoothly interpolate displayPct toward targetPct. Monotonic non-decreasing.
  useEffect(() => {
    if (displayPct >= targetPct) return;
    const id = setInterval(() => {
      setDisplayPct((prev) => {
        if (prev >= targetPct) return prev;
        const gap = targetPct - prev;
        const step = Math.max(1, Math.ceil(gap / 12));
        return Math.min(targetPct, prev + step);
      });
    }, 120);
    return () => clearInterval(id);
  }, [targetPct, displayPct]);

  return (
    <div className="flex min-h-screen flex-col items-center justify-center bg-[var(--shell-main)] px-4 text-[var(--shell-text)]">
      <div className="w-full max-w-xl">
        {/* Title */}
        <div className="mb-10 text-center">
          <div className="text-[10px] uppercase tracking-[0.28em] text-[var(--shell-text-soft)]">
            AI Analysis Engine
          </div>
          {board?.siteName && phase !== "intro" && (
            <h1 className="mt-3 text-lg font-medium text-[var(--shell-text)]">
              {board.siteName}
            </h1>
          )}
          {board?.domain && phase !== "intro" && (
            <p className="mt-0.5 text-xs text-[var(--shell-text-muted)]">
              {board.domain}
            </p>
          )}
        </div>

        {/* Intro spinner */}
        {phase === "intro" && (
          <div className="flex flex-col items-center gap-5 animate-in fade-in">
            <Loader2 className="h-8 w-8 animate-spin text-[var(--shell-accent)]" />
            <p className="text-sm text-[var(--shell-text-muted)]">
              {PHASE_MESSAGES.intro}
            </p>
          </div>
        )}

        {/* Active pipeline (crawling / analyzing / done) */}
        {(phase === "crawling" ||
          phase === "analyzing" ||
          phase === "done") && (
          <div className="space-y-8">
            {/* Percentage + progress bar */}
            <div className="text-center">
              <div className="flex items-baseline justify-center gap-0.5">
                <span className="text-5xl font-extralight tabular-nums tracking-tight text-[var(--shell-text)]">
                  {displayPct}
                </span>
                <span className="text-base font-light text-[var(--shell-text-soft)]">
                  %
                </span>
              </div>
              <div className="mx-auto mt-3 h-0.5 w-48 overflow-hidden rounded-full bg-[var(--shell-panel-strong)]">
                <div
                  className="h-full rounded-full bg-[var(--shell-accent)] transition-all duration-700 ease-out"
                  style={{ width: `${Math.max(displayPct, 2)}%` }}
                />
              </div>
            </div>

            {/* Pipeline tracker */}
            <div className="mx-auto max-w-lg">
              <div className="flex items-start">
                {PIPELINE_WAVES.map((wave, wi) => {
                  const ws = getWaveStatus(wave, stepStatus);
                  const isLast = wi === PIPELINE_WAVES.length - 1;

                  return (
                    <div
                      key={wave.key}
                      className="flex items-start"
                      style={{ flex: 1 }}
                    >
                      {/* Wave column */}
                      <div
                        className="flex flex-col items-center"
                        style={{ minWidth: 0, flex: 1 }}
                      >
                        {/* Wave label */}
                        <span
                          className={`mb-2 text-[10px] font-semibold uppercase tracking-wider transition-colors duration-500 ${
                            ws === "running"
                              ? "text-[var(--shell-accent)]"
                              : ws === "complete"
                                ? "text-[var(--shell-positive)]"
                                : ws === "failed"
                                  ? "text-[var(--shell-danger)]"
                                  : "text-[var(--shell-text-soft)]"
                          }`}
                        >
                          {wave.label}
                        </span>

                        {/* Node circle */}
                        <div
                          className={`relative flex h-9 w-9 items-center justify-center rounded-full border-2 transition-all duration-500 ${
                            ws === "running"
                              ? "border-[var(--shell-accent)] bg-[var(--shell-accent-soft)] shadow-[0_0_12px_var(--shell-accent-soft)]"
                              : ws === "complete"
                                ? "border-[var(--shell-positive)] bg-[var(--shell-positive)]/10"
                                : ws === "failed"
                                  ? "border-[var(--shell-danger)] bg-[var(--shell-danger)]/10"
                                  : ws === "pending"
                                    ? "border-[var(--shell-text-soft)] bg-[var(--shell-text-soft)]/5"
                                    : "border-[var(--shell-border)] bg-transparent"
                          }`}
                        >
                          {ws === "complete" && (
                            <CheckCircle2 className="h-4 w-4 text-[var(--shell-positive)]" />
                          )}
                          {ws === "failed" && (
                            <XCircle className="h-4 w-4 text-[var(--shell-danger)]" />
                          )}
                          {ws === "running" && (
                            <div className="h-3 w-3 animate-spin rounded-full border-2 border-[var(--shell-accent)] border-t-transparent" />
                          )}
                          {ws === "pending" && (
                            <div className="h-2 w-2 rounded-full bg-[var(--shell-text-soft)]/40" />
                          )}
                          {ws === "idle" && (
                            <div className="h-2 w-2 rounded-full bg-[var(--shell-border)]" />
                          )}
                        </div>

                        {/* Step pills */}
                        <div className="mt-2 flex flex-wrap justify-center gap-0.5">
                          {wave.steps.map((step) => {
                            const ss = stepStatus[step.key] ?? "idle";
                            return (
                              <span
                                key={step.key}
                                className={`rounded px-1.5 py-px text-[8px] font-medium tracking-wide transition-all duration-300 ${
                                  ss === "running"
                                    ? "bg-[var(--shell-accent-soft)] text-[var(--shell-accent)]"
                                    : ss === "complete"
                                      ? "bg-[var(--shell-positive)]/10 text-[var(--shell-positive)]"
                                      : ss === "failed"
                                        ? "bg-[var(--shell-danger)]/10 text-[var(--shell-danger)]"
                                        : "bg-transparent text-[var(--shell-text-muted)]"
                                }`}
                              >
                                {step.label}
                              </span>
                            );
                          })}
                        </div>
                      </div>

                      {/* Connector */}
                      {!isLast && (
                        <div
                          className="mt-[34px] flex items-center"
                          style={{ width: 20, flexShrink: 0 }}
                        >
                          <div
                            className={`h-px w-full transition-colors duration-500 ${
                              ws === "complete" || ws === "failed"
                                ? "bg-[var(--shell-positive)]/40"
                                : ws === "running"
                                  ? "bg-[var(--shell-accent)]/40"
                                  : "bg-[var(--shell-border)]"
                            }`}
                          />
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            </div>

            {/* Skip to dashboard */}
            {phase !== "done" && (
              <div className="flex justify-center">
                <button
                  type="button"
                  onClick={() => navigate(`/board/${id}/portal`, { replace: true })}
                  className="shell-transition group inline-flex items-center gap-1.5 rounded-full border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-1.5 text-[11px] font-medium text-[var(--shell-text-muted)] hover:border-[color-mix(in_srgb,var(--shell-accent)_40%,var(--shell-border))] hover:text-[var(--shell-text)]"
                >
                  <span>백그라운드에서 계속 분석, 대시보드로 이동</span>
                  <span aria-hidden="true" className="transition-transform duration-300 group-hover:translate-x-0.5">
                    →
                  </span>
                </button>
              </div>
            )}

            {/* Live console ticker */}
            <div className="mx-auto max-w-lg">
              <div className="overflow-hidden rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel)] px-4 py-3">
                <div className="mb-2 flex items-center gap-1.5">
                  <span className="h-1.5 w-1.5 rounded-full bg-[var(--shell-danger)]/60" />
                  <span className="h-1.5 w-1.5 rounded-full bg-[var(--shell-secondary)]/60" />
                  <span className="h-1.5 w-1.5 rounded-full bg-[var(--shell-positive)]/60" />
                </div>
                <div className="h-5 font-mono text-[11px]">
                  {visibleLine ? (
                    <p
                      className={`truncate transition-opacity duration-300 ${
                        lineFade ? "opacity-100" : "opacity-0"
                      } ${
                        visibleLine.type === "error"
                          ? "text-[var(--shell-danger)]"
                          : visibleLine.type === "warning"
                            ? "text-[var(--shell-warning)]"
                            : visibleLine.type === "step"
                              ? "text-[var(--shell-accent)]"
                              : "text-[var(--shell-text-muted)]"
                      }`}
                    >
                      <span className="mr-1.5 text-[var(--shell-text-soft)]">{">"}</span>
                      {visibleLine.message}
                    </p>
                  ) : (
                    <p className="text-[var(--shell-text-soft)]">
                      <span className="mr-1.5">{">"}</span>
                      {cmdMessage || PHASE_MESSAGES[phase]}
                    </p>
                  )}
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Failed state */}
        {phase === "failed" && (
          <div className="flex flex-col items-center gap-6">
            <div className="flex h-14 w-14 items-center justify-center rounded-full border border-[var(--shell-danger)]/30 bg-[var(--shell-danger)]/10">
              <XCircle className="h-6 w-6 text-[var(--shell-danger)]" />
            </div>
            <p className="text-sm text-[var(--shell-danger)]">
              {cmdError ?? PHASE_MESSAGES.failed}
            </p>
            <button
              onClick={async () => {
                await LocalCache.remove(CACHE_KEYS.SELECTED_BOARD_ID);
                navigate("/", { replace: true });
              }}
              className="shell-transition rounded-2xl border border-[var(--shell-border)] px-6 py-3 text-sm text-[var(--shell-text-muted)] hover:text-[var(--shell-text)]"
            >
              돌아가기
            </button>
          </div>
        )}
      </div>
    </div>
  );
}
