function BenchmarkTrendChart({ points, engineView, selectedQuery }: { points: BenchmarkTrendPoint[]; engineView: BenchmarkEngineView; selectedQuery: string | null }) {
  if (points.length === 0) {
    return (
      <div className="mt-5 grid h-44 place-items-center rounded-[14px] border border-dashed border-[var(--shell-border)] bg-[var(--shell-panel-soft)] text-center text-sm leading-6 text-[var(--shell-text-muted)]">
        아직 누적 벤치마크가 없습니다.<br />
        AI Answers에서 선택 쿼리와 지역 샘플링을 설정하세요.
      </div>
    );
  }

  const width = 720;
  const height = 190;
  const paddingX = 34;
  const paddingTop = 18;
  const plotHeight = 124;
  const dateLabelY = height - 14;
  const xFor = (index: number) => {
    if (points.length === 1) return width / 2;
    return paddingX + (index / (points.length - 1)) * (width - paddingX * 2);
  };
  const yFor = (value: number) => paddingTop + ((100 - Math.max(0, Math.min(100, value))) / 100) * plotHeight;

  // 쿼리 선택 시: 해당 쿼리의 mentionRate 사용, 미선택 시: 전체 쿼리 평균
  const getQueryMentionRate = (point: BenchmarkTrendPoint): number => {
    if (selectedQuery) {
      const q = (point.queries || []).find((q) => q.query === selectedQuery);
      return q?.mentionRate ?? 0;
    }
    // 전체 쿼리 평균
    const queries = point.queries || [];
    if (queries.length === 0) return point.mentionRate || 0;
    return Math.round(queries.reduce((sum, q) => sum + q.mentionRate, 0) / queries.length);
  };

  const engineOptions = BENCHMARK_ENGINE_OPTIONS.filter((option) => option.key !== "all");
  const series = engineView === "all" ? engineOptions : engineOptions.filter((option) => option.key === engineView);
  const getValue = (point: BenchmarkTrendPoint, key: BenchmarkEngineView) =>
    key === "all" ? getQueryMentionRate(point) : point.byEngine?.[key]?.mentionRate ?? 0;
  const linePath = (key: BenchmarkEngineView) =>
    points.map((point, index) => `${index === 0 ? "M" : "L"} ${xFor(index)} ${yFor(getValue(point, key))}`).join(" ");

  // area fill path for the primary line
  const areaPath = (key: BenchmarkEngineView) => {
    const line = points.map((point, index) => `${index === 0 ? "M" : "L"} ${xFor(index)} ${yFor(getValue(point, key))}`).join(" ");
    const lastX = xFor(points.length - 1);
    const firstX = xFor(0);
    const bottom = paddingTop + plotHeight;
    return `${line} L ${lastX} ${bottom} L ${firstX} ${bottom} Z`;
  };

  const chartTitle = selectedQuery ? `"${selectedQuery}" 멘션 추이` : "전체 쿼리 평균 멘션 추이";

  return (
    <div className="mt-5 rounded-[14px] border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-4">
      <div className="mb-2 flex flex-wrap items-center justify-between gap-3">
        <div className="text-xs font-semibold text-[var(--shell-text)]">{chartTitle}</div>
        <div className="flex flex-wrap items-center gap-3">
          {series.map((item) => (
            <div key={item.key} className="flex items-center gap-1.5 text-[10px] uppercase tracking-[0.1em] text-[var(--shell-text-muted)]">
              <span className="h-2 w-2 rounded-full" style={{ backgroundColor: item.color }} />
              {item.label}
            </div>
          ))}
        </div>
      </div>
      <svg viewBox={`0 0 ${width} ${height}`} className="h-48 w-full overflow-visible">
        <defs>
          {series.map((item) => (
            <linearGradient key={`grad-${item.key}`} id={`area-grad-${item.key}`} x1="0" x2="0" y1="0" y2="1">
              <stop offset="0%" stopColor={item.color} stopOpacity="0.18" />
              <stop offset="100%" stopColor={item.color} stopOpacity="0" />
            </linearGradient>
          ))}
        </defs>
        {[0, 25, 50, 75, 100].map((tick) => {
          const y = yFor(tick);
          return (
            <g key={tick}>
              <line x1={paddingX} x2={width - paddingX} y1={y} y2={y} stroke="var(--shell-border)" strokeDasharray={tick === 0 ? "0" : "4 6"} />
              <text x={8} y={y + 4} fill="var(--shell-text-muted)" fontSize="11">{tick}%</text>
            </g>
          );
        })}
        {series.map((item) => (
          <g key={item.key}>
            <path d={areaPath(item.key)} fill={`url(#area-grad-${item.key})`} />
            <path d={linePath(item.key)} fill="none" stroke={item.color} strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" vectorEffect="non-scaling-stroke" />
            {points.map((point, index) => (
              <circle key={`${item.key}-${point.date}`} cx={xFor(index)} cy={yFor(getValue(point, item.key))} r="4" fill="var(--shell-panel)" stroke={item.color} strokeWidth="2" />
            ))}
          </g>
        ))}
        {points.map((point, index) => (
          <g key={point.date}>
            <line x1={xFor(index)} x2={xFor(index)} y1={paddingTop} y2={paddingTop + plotHeight} stroke="var(--shell-border)" strokeWidth="1" />
            <text x={xFor(index)} y={dateLabelY} textAnchor="middle" fill="var(--shell-text-muted)" fontSize="11">{point.date.slice(5)}</text>
          </g>
        ))}
      </svg>
    </div>
  );
}

function downloadBenchmarkRawData(points: BenchmarkTrendPoint[], latest: BenchmarkTrendPoint | null) {
  const rows: Array<Array<string | number>> = [["type", "date", "query", "totalSamples", "mentionRate", "recommendedRate", "regionCoverageRate"]];
  const sourcePoints = points.length > 0 ? points : latest ? [latest] : [];

  sourcePoints.forEach((point) => {
    rows.push(["daily", point.date, "", point.totalSamples, point.mentionRate, point.recommendedRate, point.regionCoverageRate]);
    (point.queries || []).forEach((query) => {
      rows.push([
        "query",
        point.date,
        query.query,
        query.totalSamples || 0,
        query.mentionRate,
        query.recommendedRate || 0,
        query.regionCoverageRate,
      ]);
    });
  });

  const csv = rows.map((row) => row.map(formatCsvCell).join(",")).join("\n");
  const blob = new Blob([`\uFEFF${csv}`], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = `benchmark-raw-${latest?.date || new Date().toISOString().slice(0, 10)}.csv`;
  document.body.appendChild(anchor);
  anchor.click();
  document.body.removeChild(anchor);
  URL.revokeObjectURL(url);
}

function formatCsvCell(value: string | number) {
  const text = String(value ?? "");
  return /[",\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
}

