function SeedButtonPortal({
  seeding,
  disabled,
  onSeed,
  status,
  error,
}: {
  seeding: boolean;
  disabled: boolean;
  onSeed: () => void;
  status: "idle" | "success" | "error";
  error: string | null;
}) {
  const [target, setTarget] = useState<HTMLElement | null>(null);

  useEffect(() => {
    const findSlot = () => document.getElementById("shell-header-slot");
    const initial = findSlot();
    if (initial) {
      setTarget(initial);
      return;
    }
    const observer = new MutationObserver(() => {
      const slot = findSlot();
      if (slot) {
        setTarget(slot);
        observer.disconnect();
      }
    });
    observer.observe(document.body, { childList: true, subtree: true });
    return () => observer.disconnect();
  }, []);

  if (!target) return null;

  return createPortal(
    <>
      <button
        type="button"
        onClick={onSeed}
        disabled={disabled}
        className="inline-flex items-center gap-2 rounded-lg border border-dashed border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-1.5 text-xs font-medium text-[var(--shell-text)] transition hover:border-[var(--shell-accent)] hover:text-[var(--shell-accent)] disabled:cursor-not-allowed disabled:opacity-50"
        title="Inject sample executiveSummary / benchmarkTrend / externalSources"
      >
        <Database className="h-3.5 w-3.5" />
        {seeding ? "Seeding..." : "Seed Sample Data"}
      </button>
      {status === "success" && <span className="text-[11px] text-emerald-600">Seed applied</span>}
      {status === "error" && (
        <span className="text-[11px] text-rose-600" title={error ?? undefined}>Seed failed</span>
      )}
    </>,
    target
  );
}
