import { createContext, useContext, useEffect, useMemo, useState } from "react";

export type UiTheme = "dark" | "light";

type ShellPreferencesValue = {
  theme: UiTheme;
  setTheme: (theme: UiTheme) => void;
  toggleTheme: () => void;
  sidebarCollapsed: boolean;
  setSidebarCollapsed: (collapsed: boolean) => void;
  toggleSidebar: () => void;
};

const THEME_STORAGE_KEY = "dk:ui-theme";
const SIDEBAR_STORAGE_KEY = "dk:sidebar-collapsed";

const ShellPreferencesContext = createContext<ShellPreferencesValue | null>(null);

function readStoredTheme(): UiTheme {
  if (typeof window === "undefined") return "dark";
  const stored = window.localStorage.getItem(THEME_STORAGE_KEY);
  return stored === "light" ? "light" : "dark";
}

function readStoredSidebarState(): boolean {
  if (typeof window === "undefined") return false;
  return window.localStorage.getItem(SIDEBAR_STORAGE_KEY) === "1";
}

export function ShellPreferencesProvider({ children }: { children: React.ReactNode }) {
  const [theme, setTheme] = useState<UiTheme>(readStoredTheme);
  const [sidebarCollapsed, setSidebarCollapsed] = useState<boolean>(readStoredSidebarState);

  useEffect(() => {
    if (typeof window === "undefined") return;
    window.localStorage.setItem(THEME_STORAGE_KEY, theme);
    document.documentElement.dataset.theme = theme;
  }, [theme]);

  useEffect(() => {
    if (typeof window === "undefined") return;
    window.localStorage.setItem(SIDEBAR_STORAGE_KEY, sidebarCollapsed ? "1" : "0");
  }, [sidebarCollapsed]);

  const value = useMemo<ShellPreferencesValue>(
    () => ({
      theme,
      setTheme,
      toggleTheme: () => setTheme((current) => (current === "dark" ? "light" : "dark")),
      sidebarCollapsed,
      setSidebarCollapsed,
      toggleSidebar: () => setSidebarCollapsed((current) => !current),
    }),
    [sidebarCollapsed, theme],
  );

  return (
    <ShellPreferencesContext.Provider value={value}>
      {children}
    </ShellPreferencesContext.Provider>
  );
}

export function useShellPreferences() {
  const context = useContext(ShellPreferencesContext);
  if (!context) {
    throw new Error("useShellPreferences must be used within ShellPreferencesProvider");
  }
  return context;
}
