/**
 * Competitors are a single raw collection. `type` distinguishes manual entries
 * from auto-detected ones.
 */
export interface RawCompetitor extends CompetitorV2Doc {
  id: string;
  type?: "manual" | "auto";
}

export async function listCompetitors(
  boardId: string,
  filter?: { type?: "manual" | "auto" },
): Promise<RawCompetitor[]> {
  const snap = await getDocs(paths.rawCompetitors(boardId));
  const rows = snap.docs.map((d) => ({ id: d.id, ...(d.data() as CompetitorV2Doc & { type?: "manual" | "auto" }) }));
  if (filter?.type) return rows.filter((r) => (r.type ?? "auto") === filter.type);
  return rows;
}

