// ── Runs ──────────────────────────────────────────────────

function toDate(v: unknown): Date | null {
  if (!v) return null;
  if (typeof (v as { toDate?: unknown }).toDate === "function") {
    return (v as { toDate: () => Date }).toDate();
  }
  return null;
}

function toRunDoc(id: string, data: Record<string, unknown>): RunDoc {
  return {
    id,
    commandId: data.commandId as string,
    commandType: data.commandType as RunDoc["commandType"],
    status: data.status as RunDoc["status"],
    steps: (data.steps ?? {}) as RunDoc["steps"],
    progress: (data.progress as number) ?? 0,
    message: (data.message as string) ?? "",
    errorCount: (data.errorCount as number) ?? 0,
    warningCount: (data.warningCount as number) ?? 0,
    userId: data.userId as string,
    startedAt: toDate(data.startedAt) ?? new Date(),
    completedAt: toDate(data.completedAt),
    durationMs: (data.durationMs as number) ?? null,
  } as RunDoc;
}

export async function listRuns(boardId: string, count = 30): Promise<RunDoc[]> {
  const q = query(paths.runs(boardId), orderBy("startedAt", "desc"), limit(count));
  const snap = await getDocs(q);
  return snap.docs.map((d) => toRunDoc(d.id, d.data() as Record<string, unknown>));
}

export function subscribeRuns(
  boardId: string,
  callback: (runs: RunDoc[]) => void,
): Unsubscribe {
  const q = query(paths.runs(boardId), orderBy("startedAt", "desc"), limit(30));
  return onSnapshot(q, (snap) => {
    callback(snap.docs.map((d) => toRunDoc(d.id, d.data() as Record<string, unknown>)));
  });
}

// ── Insights ───────────────────────────────────────────────

function toDateOrNull(v: unknown): Date | null {
  if (!v) return null;
  if (typeof (v as { toDate?: unknown }).toDate === "function") {
    return (v as { toDate: () => Date }).toDate();
  }
  return null;
}

function toInsight(id: string, data: Record<string, unknown>): InsightDoc {
  return {
    id,
    type: (data.type as InsightDoc["type"]) || undefined,
    ownerKey: (data.ownerKey as string) || undefined,
    source: data.source as InsightDoc["source"],
    title: String(data.title ?? ""),
    summary: (data.summary as string) || undefined,
    detail: (data.detail as string) || undefined,
    suggestion: (data.suggestion as string) || undefined,
    severity: (data.severity as InsightDoc["severity"]) ?? "warning",
    status: (data.status as InsightStatus) ?? "open",
    priorityScore:
      typeof data.priorityScore === "number" ? data.priorityScore : undefined,
    rule: (data.rule as string) || undefined,
    file: (data.file as string) || undefined,
    affectedPages: (data.affectedPages as string[]) || undefined,
    evidence: (data.evidence as InsightDoc["evidence"]) || undefined,
    diagnosis: (data.diagnosis as InsightDoc["diagnosis"]) || undefined,
    recommendedActions:
      (data.recommendedActions as InsightDoc["recommendedActions"]) || undefined,
    sourceRefs: (data.sourceRefs as InsightDoc["sourceRefs"]) || undefined,
    dataQuality: (data.dataQuality as InsightDoc["dataQuality"]) || undefined,
    linkedActionId: (data.linkedActionId as string) || undefined,
    linkedActionTitle: (data.linkedActionTitle as string) || undefined,
    firstDetectedAt: toDateOrNull(data.firstDetectedAt),
    lastDetectedAt: toDateOrNull(data.lastDetectedAt),
    lastSyncId: (data.lastSyncId as string) || undefined,
    resolvedAt: toDateOrNull(data.resolvedAt),
    updatedAt: toDateOrNull(data.updatedAt),
  };
}

export interface InsightQueryFilter {
  type?: InsightDoc["type"] | InsightDoc["type"][];
  status?: InsightStatus | InsightStatus[];
  ownerKey?: string;
}

function matchesFilter(doc: InsightDoc, filter?: InsightQueryFilter): boolean {
  if (!filter) return true;
  if (filter.type) {
    const types = Array.isArray(filter.type) ? filter.type : [filter.type];
    if (!doc.type || !types.includes(doc.type)) return false;
  }
  if (filter.status) {
    const statuses = Array.isArray(filter.status) ? filter.status : [filter.status];
    if (!statuses.includes(doc.status)) return false;
  }
  if (filter.ownerKey && doc.ownerKey !== filter.ownerKey) return false;
  return true;
}

export function subscribeInsights(
  boardId: string,
  callback: (insights: InsightDoc[]) => void,
  filter?: InsightQueryFilter,
): Unsubscribe {
  return onSnapshot(paths.insights(boardId), (snap) => {
    const rows: InsightDoc[] = [];
    snap.forEach((d) => {
      const ins = toInsight(d.id, d.data() as Record<string, unknown>);
      if (matchesFilter(ins, filter)) rows.push(ins);
    });
    callback(rows);
  });
}

export async function listInsights(
  boardId: string,
  filter?: InsightQueryFilter,
): Promise<InsightDoc[]> {
  const snap = await getDocs(paths.insights(boardId));
  return snap.docs
    .map((d) => toInsight(d.id, d.data() as Record<string, unknown>))
    .filter((ins) => matchesFilter(ins, filter));
}

export async function updateInsightStatus(
  boardId: string,
  insightId: string,
  status: InsightStatus,
  extra: Partial<Pick<InsightDoc, "linkedActionId" | "linkedActionTitle">> = {},
): Promise<void> {
  const patch: Record<string, unknown> = {
    status,
    updatedAt: serverTimestamp(),
  };
  if (status === "resolved") patch.resolvedAt = serverTimestamp();
  if (extra.linkedActionId) patch.linkedActionId = extra.linkedActionId;
  if (extra.linkedActionTitle) patch.linkedActionTitle = extra.linkedActionTitle;
  await updateDoc(paths.insight(boardId, insightId), patch);
}

export interface DerivedInsight {
  id: string;
  source: InsightDoc["source"];
  title: string;
  detail?: string;
  suggestion?: string;
  severity: InsightDoc["severity"];
  rule?: string;
  file?: string;
  affectedPages?: string[];
}

export async function syncInsights(
  boardId: string,
  derived: DerivedInsight[],
  sources: InsightDoc["source"][],
): Promise<void> {
  const syncId = `sync-${Date.now()}`;
  const existingSnap = await getDocs(paths.insights(boardId));
  const existing = new Map<string, Record<string, unknown>>();
  existingSnap.forEach((d) => existing.set(d.id, d.data() as Record<string, unknown>));

  const seenIds = new Set<string>();
  const batch = writeBatch(db);
  let writes = 0;

  for (const ins of derived) {
    seenIds.add(ins.id);
    const ref = paths.insight(boardId, ins.id);
    const prior = existing.get(ins.id);
    const payload: Record<string, unknown> = {
      source: ins.source,
      title: ins.title,
      severity: ins.severity,
      lastDetectedAt: serverTimestamp(),
      lastSyncId: syncId,
      updatedAt: serverTimestamp(),
    };
    if (ins.detail !== undefined) payload.detail = ins.detail;
    if (ins.suggestion !== undefined) payload.suggestion = ins.suggestion;
    if (ins.rule !== undefined) payload.rule = ins.rule;
    if (ins.file !== undefined) payload.file = ins.file;
    if (ins.affectedPages !== undefined) payload.affectedPages = ins.affectedPages;

    if (!prior) {
      payload.firstDetectedAt = serverTimestamp();
      payload.status = "open";
    } else {
      const priorStatus = (prior.status as InsightStatus) || "open";
      if (priorStatus === "resolved") {
        payload.status = "open";
      }
    }
    batch.set(ref, payload, { merge: true });
    writes++;
  }

  for (const [id, data] of existing) {
    if (seenIds.has(id)) continue;
    const src = data.source as InsightDoc["source"];
    if (!sources.includes(src)) continue;
    const status = (data.status as InsightStatus) || "open";
    if (status === "ignored" || status === "resolved") continue;
    if (status === "action-created") continue;
    const ref = paths.insight(boardId, id);
    batch.update(ref, {
      status: "resolved",
      resolvedAt: serverTimestamp(),
      updatedAt: serverTimestamp(),
    });
    writes++;
  }

  if (writes > 0) await batch.commit();
}

// ── Active run ─────────────────────────────────────────────

export function subscribeActiveRun(
  boardId: string,
  callback: (run: RunDoc | null) => void,
): Unsubscribe {
  const q = query(
    paths.runs(boardId),
    where("status", "==", "running"),
    orderBy("startedAt", "desc"),
    limit(1),
  );
  return onSnapshot(q, (snap) => {
    if (snap.empty) {
      callback(null);
      return;
    }
    const d = snap.docs[0];
    callback(toRunDoc(d.id, d.data() as Record<string, unknown>));
  });
}

