import { useMemo, useState } from "react";
import { Link } from "react-router-dom";
import {
  Bot,
  ArrowRight,
  CheckCircle2,
  XCircle,
  Sparkles,
  Download,
  RefreshCw,
  ThumbsUp,
  ThumbsDown,
  Minus,
  Star,
} from "lucide-react";
import {
  usePortalDashboard,
  usePortalProbes,
  usePortalBrandTruth,
  usePortalSentiment,
} from "./dataHub";
import type { SentimentLabel, ProbeSentimentRecord, ProbeRecord } from "./dataHub/types";

const ENGINE_LABELS: Record<string, string> = {
  gpt: "ChatGPT",
  openai: "ChatGPT",
  gemini: "Gemini",
  claude: "Claude",
  perplexity: "Perplexity",
};

type Tab = "brand" | "keyword" | "competitor" | "answers";

const TAB_DEFS: Array<{ key: Tab; label: string; description: string }> = [
  { key: "brand", label: "브랜드 인식", description: "AI 가 우리 브랜드를 얼마나 자주 언급하는지 + 답변의 톤(긍정/부정/중립)" },
  { key: "keyword", label: "키워드 가시성", description: "고객이 입력한 must-win 쿼리 + 자동 추천 쿼리의 답변 매칭" },
  { key: "competitor", label: "경쟁사 비교", description: "경쟁사 대비 노출·언급 빈도 + sentiment" },
  { key: "answers", label: "주요 답변", description: "긍정 / 부정 / 중립 답변 Top 3 + 전체 raw 데이터 다운로드" },
];

const SENT_LABEL: Record<SentimentLabel, string> = {
  positive: "긍정",
  negative: "부정",
  neutral: "중립",
  unknown: "미분류",
};
const SENT_TONE: Record<SentimentLabel, string> = {
  positive: "text-emerald-300 border-emerald-500/30 bg-emerald-500/5",
  negative: "text-red-300 border-red-500/30 bg-red-500/5",
  neutral: "text-blue-300 border-blue-500/30 bg-blue-500/5",
  unknown: "text-neutral-400 border-neutral-500/30 bg-neutral-500/5",
};

export function PortalGeoStatus() {
  const [tab, setTab] = useState<Tab>("brand");
  const [isRerunning, setIsRerunning] = useState(false);

  const { data: dashboardData } = usePortalDashboard();
  const { data: probeData } = usePortalProbes();
  const { data: truthData } = usePortalBrandTruth();
  const { data: sentimentData } = usePortalSentiment();

  const handleRunSentiment = () => {
    // Mock rerun — 실제 API 연동 시 dataHub 에 mutation 추가.
    setIsRerunning(true);
    setTimeout(() => setIsRerunning(false), 800);
  };

  const probes = probeData?.probes || [];
  const generic = dashboardData?.genericEngine;
  const competitors = dashboardData?.competitors;
  const truth = truthData?.truth;
  const sentiment = sentimentData?.summary;

  const overallScore = useMemo(() => {
    if (!generic) return 0;
    return Math.round(generic.mentionRate * 0.7 + generic.exposureRate * 0.3);
  }, [generic]);

  const engines = generic?.engineBreakdown || [];

  const queryGroups = useMemo(() => {
    const map = new Map<string, ProbeRecord[]>();
    for (const p of probes) {
      if (!map.has(p.question)) map.set(p.question, []);
      map.get(p.question)!.push(p);
    }
    return [...map.entries()]
      .map(([question, items]) => {
        const mentioned = items.filter((p) => p.ourSiteMentioned).length;
        return {
          question,
          items,
          mentioned,
          total: items.length,
          rate: items.length > 0 ? Math.round((mentioned / items.length) * 100) : 0,
          isMustWin: !!truth?.mustWinQueries?.some((q) => q.trim() === question.trim()),
        };
      })
      .sort((a, b) => {
        if (a.isMustWin !== b.isMustWin) return a.isMustWin ? -1 : 1;
        return b.rate - a.rate;
      });
  }, [probes, truth]);

  const downloadCsv = () => {
    // Mock — 실제 API 연동 시 CSV endpoint 로 교체.
    alert("원시 답변 CSV 다운로드 (목업) — 실제 연동 시 파일이 내려받아집니다.");
  };

  return (
    <div className="mx-auto max-w-6xl space-y-6 px-4 py-6">
      <header>
        <div className="text-xs uppercase tracking-[0.28em] text-[var(--shell-text-soft)]">Portal / GEO 현황</div>
        <h1 className="mt-2 text-3xl font-semibold tracking-tight text-[var(--shell-text)]">AI 답변 가시성</h1>
        <p className="mt-2 text-sm text-[var(--shell-text-muted)]">
          ChatGPT / Claude / Gemini / Perplexity 가 사용자 질문에 답할 때, 우리 브랜드가 답변과 출처에 얼마나 자주 포함되는지 확인합니다.
          아래 탭에서 답변의 톤(긍정/부정/중립) 까지 확인할 수 있습니다.
        </p>
      </header>

      <section className="rounded-3xl border border-[var(--shell-border)] bg-gradient-to-br from-[var(--shell-panel-strong)] to-[var(--shell-panel)] px-7 py-6">
        <div className="flex items-end justify-between gap-6">
          <div>
            <div className="text-[11px] uppercase tracking-[0.22em] text-[var(--shell-text-soft)]">AI 검색 언급률</div>
            <div className="mt-2 flex items-baseline gap-2">
              <div className="text-6xl font-semibold tracking-tight text-[var(--shell-text)]">{generic?.mentionRate ?? 0}</div>
              <div className="text-2xl text-[var(--shell-text-muted)]">%</div>
            </div>
            <div className="mt-2 text-xs leading-5 text-[var(--shell-text-muted)]">
              AI 가 답변 본문에 우리 브랜드를 직접 적은 비율입니다.
              <span className="ml-2 text-[var(--shell-text-soft)]">
                · 출처 노출률 {generic?.exposureRate ?? 0}% (출처 링크에 우리 사이트 포함)
                · 가중 점수 {overallScore}/100
              </span>
            </div>
          </div>
          <Link
            to="../queries"
            relative="path"
            className="hidden items-center gap-2 rounded-full border border-[var(--shell-border)] bg-[var(--shell-panel)] px-4 py-2 text-xs text-[var(--shell-text)] hover:bg-[var(--shell-panel-soft)] sm:flex"
          >
            쿼리·답변 자세히 보기 <ArrowRight className="h-3.5 w-3.5" />
          </Link>
        </div>
      </section>

      <section className="grid gap-3 md:grid-cols-2 lg:grid-cols-4">
        {engines.length === 0 ? (
          <div className="rounded-2xl border border-amber-500/30 bg-amber-500/5 px-5 py-6 text-sm text-amber-200 md:col-span-2 lg:col-span-4">
            아직 측정된 AI 엔진이 없습니다. 쿼리 설정에서 측정을 시작해주세요.
          </div>
        ) : (
          engines.map((eng) => {
            const engineRecords = (sentiment?.records || []).filter((r) => r.engine === eng.engine);
            const engSent = {
              positive: engineRecords.filter((r) => r.overallSentiment === "positive").length,
              negative: engineRecords.filter((r) => r.overallSentiment === "negative").length,
              neutral: engineRecords.filter((r) => r.overallSentiment === "neutral").length,
            };
            const engTotal = engSent.positive + engSent.negative + engSent.neutral;
            return (
              <div key={eng.engine} className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] px-5 py-4">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <Bot className="h-4 w-4 text-[var(--shell-accent)]" />
                    <span className="text-sm font-medium text-[var(--shell-text)]">{ENGINE_LABELS[eng.engine] || eng.engine}</span>
                  </div>
                  <div className="text-[10px] text-[var(--shell-text-soft)]">
                    {eng.mentionedCount}/{eng.totalQuestions}
                  </div>
                </div>
                <div className="mt-3 flex items-baseline gap-2">
                  <div className="text-2xl font-semibold text-[var(--shell-text)]">{eng.mentionRate}%</div>
                  <div className="text-[10px] text-[var(--shell-text-soft)]">언급률 · 노출 {eng.exposureRate}%</div>
                </div>
                <div className="mt-2 h-1.5 w-full overflow-hidden rounded-full bg-[var(--shell-panel-soft)]">
                  <div className="h-full bg-[var(--shell-accent)] transition-all" style={{ width: `${eng.mentionRate}%` }} />
                </div>
                {engTotal > 0 && (
                  <>
                    <div className="mt-3 text-[10px] text-[var(--shell-text-soft)]">답변 톤 ({engTotal})</div>
                    <div className="mt-1 flex h-1.5 overflow-hidden rounded-full bg-[var(--shell-panel-soft)]">
                      <div className="bg-emerald-500" style={{ width: `${(engSent.positive / engTotal) * 100}%` }} />
                      <div className="bg-blue-500" style={{ width: `${(engSent.neutral / engTotal) * 100}%` }} />
                      <div className="bg-red-500" style={{ width: `${(engSent.negative / engTotal) * 100}%` }} />
                    </div>
                    <div className="mt-1 flex gap-2 text-[10px]">
                      {engSent.positive > 0 && <span className="text-emerald-300">+{engSent.positive}</span>}
                      {engSent.neutral > 0 && <span className="text-blue-300">·{engSent.neutral}</span>}
                      {engSent.negative > 0 && <span className="text-red-300">−{engSent.negative}</span>}
                    </div>
                  </>
                )}
              </div>
            );
          })
        )}
      </section>

      <section className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
        <div className="flex items-start justify-between gap-3">
          <div className="flex-1">
            <div className="flex items-center gap-2 text-sm font-semibold text-[var(--shell-text)]">
              <Sparkles className="h-4 w-4 text-[var(--shell-accent)]" />
              답변 sentiment 분석
            </div>
            <div className="mt-1 text-xs text-[var(--shell-text-muted)]">
              {sentiment ? (
                <>
                  {new Date(sentiment.generatedAt).toLocaleString()} · {sentiment.totalProbesAnalyzed}개 답변 분석됨 ·
                  <span className="ml-1 text-emerald-300">긍정 {sentiment.brandBreakdown.positive}</span> /
                  <span className="ml-1 text-red-300">부정 {sentiment.brandBreakdown.negative}</span> /
                  <span className="ml-1 text-blue-300">중립 {sentiment.brandBreakdown.neutral}</span>
                </>
              ) : (
                "아직 분석되지 않았습니다. 분석을 실행하면 답변마다 긍정/부정/중립 톤을 추출하고 주요 답변 Top 3 를 보여드립니다."
              )}
            </div>
          </div>
          <button
            type="button"
            onClick={handleRunSentiment}
            disabled={isRerunning}
            className="flex shrink-0 items-center gap-1.5 rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-1.5 text-xs text-[var(--shell-text)] hover:bg-[var(--shell-panel-strong)] disabled:opacity-50"
          >
            <RefreshCw className={`h-3.5 w-3.5 ${isRerunning ? "animate-spin" : ""}`} />
            {isRerunning ? "분석 중..." : sentiment ? "재분석" : "분석 실행"}
          </button>
        </div>
      </section>

      <section className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
        <div className="flex flex-wrap border-b border-[var(--shell-border)]">
          {TAB_DEFS.map((t) => (
            <button
              key={t.key}
              type="button"
              onClick={() => setTab(t.key)}
              className={`px-4 py-2 text-sm transition-colors ${
                tab === t.key
                  ? "border-b-2 border-[var(--shell-accent)] text-[var(--shell-text)]"
                  : "text-[var(--shell-text-muted)] hover:text-[var(--shell-text)]"
              }`}
            >
              {t.label}
            </button>
          ))}
        </div>
        <div className="mt-2 text-[11px] text-[var(--shell-text-soft)]">{TAB_DEFS.find((t) => t.key === tab)?.description}</div>

        <div className="mt-4">
          {tab === "brand" && (
            <BrandTab
              mentionRate={generic?.mentionRate ?? 0}
              exposureRate={generic?.exposureRate ?? 0}
              totalProbes={probes.length}
              brandBreakdown={sentiment?.brandBreakdown}
            />
          )}
          {tab === "keyword" && <KeywordTab groups={queryGroups} mustWinCount={truth?.mustWinQueries?.length || 0} />}
          {tab === "competitor" && (
            <CompetitorTab
              topCompetitors={competitors?.topFive || []}
              ourGeoScore={competitors?.ourScores?.geoScore ?? 0}
              userCompetitors={truth?.importantCompetitors || []}
              competitorSentiments={sentiment?.competitors || []}
            />
          )}
          {tab === "answers" && (
            <AnswersTab topAnswers={sentiment?.topAnswers} hasSentiment={!!sentiment} onDownloadCsv={downloadCsv} />
          )}
        </div>
      </section>
    </div>
  );
}

function BrandTab({
  mentionRate,
  exposureRate,
  totalProbes,
  brandBreakdown,
}: {
  mentionRate: number;
  exposureRate: number;
  totalProbes: number;
  brandBreakdown?: { positive: number; negative: number; neutral: number; unknown: number };
}) {
  const totalSent = brandBreakdown
    ? brandBreakdown.positive + brandBreakdown.negative + brandBreakdown.neutral + brandBreakdown.unknown
    : 0;
  return (
    <div className="space-y-3 text-sm text-[var(--shell-text-muted)]">
      <p className="text-[var(--shell-text)]">
        AI 가 사용자에게 답할 때 우리 브랜드를 <strong>{mentionRate}%</strong> 비율로 직접 언급합니다. 그리고 출처 링크에 우리 사이트가 포함되는 비율은 <strong>{exposureRate}%</strong> 입니다. 총 <strong>{totalProbes}</strong> 개의 측정이 진행되었습니다.
      </p>
      {brandBreakdown && totalSent > 0 && (
        <div className="rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-3">
          <div className="mb-2 text-xs font-medium text-[var(--shell-text)]">답변 톤 분포 ({totalSent}개 분석)</div>
          <div className="flex h-3 overflow-hidden rounded-full">
            <div className="bg-emerald-500" style={{ width: `${(brandBreakdown.positive / totalSent) * 100}%` }} title={`긍정 ${brandBreakdown.positive}`} />
            <div className="bg-blue-500" style={{ width: `${(brandBreakdown.neutral / totalSent) * 100}%` }} title={`중립 ${brandBreakdown.neutral}`} />
            <div className="bg-red-500" style={{ width: `${(brandBreakdown.negative / totalSent) * 100}%` }} title={`부정 ${brandBreakdown.negative}`} />
            <div className="bg-neutral-500" style={{ width: `${(brandBreakdown.unknown / totalSent) * 100}%` }} title={`미분류 ${brandBreakdown.unknown}`} />
          </div>
          <div className="mt-2 flex flex-wrap gap-3 text-[11px]">
            <span className="text-emerald-300">
              긍정 {brandBreakdown.positive} ({Math.round((brandBreakdown.positive / totalSent) * 100)}%)
            </span>
            <span className="text-blue-300">
              중립 {brandBreakdown.neutral} ({Math.round((brandBreakdown.neutral / totalSent) * 100)}%)
            </span>
            <span className="text-red-300">
              부정 {brandBreakdown.negative} ({Math.round((brandBreakdown.negative / totalSent) * 100)}%)
            </span>
            {brandBreakdown.unknown > 0 && <span className="text-neutral-400">미분류 {brandBreakdown.unknown}</span>}
          </div>
        </div>
      )}
      {mentionRate < 30 && (
        <p className="rounded-lg border border-amber-500/30 bg-amber-500/5 px-3 py-2 text-xs text-amber-200">
          AI 답변에서 브랜드 언급이 낮은 편입니다. 콘텐츠 보강 + 외부 신뢰소스 (위키, 언론, 커뮤니티) 확보가 가장 큰 영향을 줄 수 있습니다.
        </p>
      )}
    </div>
  );
}

function KeywordTab({
  groups,
  mustWinCount,
}: {
  groups: Array<{ question: string; items: ProbeRecord[]; mentioned: number; total: number; rate: number; isMustWin: boolean }>;
  mustWinCount: number;
}) {
  if (groups.length === 0) {
    return <div className="text-sm text-[var(--shell-text-muted)]">측정된 쿼리가 없습니다.</div>;
  }
  return (
    <>
      {mustWinCount > 0 && (
        <div className="mb-3 flex items-center gap-2 rounded-lg border border-[var(--shell-accent)]/30 bg-[var(--shell-accent)]/5 px-3 py-2 text-xs text-[var(--shell-text)]">
          <Star className="h-3 w-3 fill-amber-300 text-amber-300" /> 표시 = 고객이 입력한 must-win 쿼리 (총 {mustWinCount}개) — 분석 결과를 우선 정렬해 보여드립니다.
        </div>
      )}
      <ul className="space-y-2">
        {groups.slice(0, 16).map((g, i) => {
          const enginesMap = new Map<string, boolean>();
          for (const it of g.items) {
            const label = ENGINE_LABELS[it.engine] || it.engine;
            const hit = enginesMap.get(label);
            enginesMap.set(label, hit || !!it.ourSiteMentioned);
          }
          return (
            <li key={i} className="flex items-center gap-3 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
              {g.isMustWin && <Star className="h-3.5 w-3.5 shrink-0 fill-amber-300 text-amber-300" />}
              <div className="min-w-0 flex-1 truncate text-sm text-[var(--shell-text)]">{g.question}</div>
              <div className="hidden shrink-0 items-center gap-2 text-[11px] sm:flex">
                {[...enginesMap.entries()].map(([eng, ok]) => (
                  <span key={eng} className={`flex items-center gap-1 ${ok ? "text-emerald-300" : "text-red-300"}`}>
                    {eng} {ok ? <CheckCircle2 className="h-3 w-3" /> : <XCircle className="h-3 w-3" />}
                  </span>
                ))}
              </div>
              <div className="shrink-0 text-xs text-[var(--shell-text-muted)] sm:hidden">
                {g.mentioned}/{g.total}
              </div>
            </li>
          );
        })}
      </ul>
    </>
  );
}

function CompetitorTab({
  topCompetitors,
  ourGeoScore,
  userCompetitors,
  competitorSentiments,
}: {
  topCompetitors: Array<{ name: string; geoScore: number; geoMentionCount: number }>;
  ourGeoScore: number;
  userCompetitors: string[];
  competitorSentiments: Array<{
    name: string;
    mentionCount: number;
    engines: string[];
    sentimentBreakdown: { positive: number; negative: number; neutral: number; unknown: number };
  }>;
}) {
  if (topCompetitors.length === 0 && userCompetitors.length === 0) {
    return <div className="text-sm text-[var(--shell-text-muted)]">경쟁사 데이터가 아직 준비되지 않았습니다.</div>;
  }
  const norm = (s: string) => s.trim().toLowerCase().replace(/[\s.\-_,()[\]]/g, "");
  const sentByName = new Map<string, { positive: number; negative: number; neutral: number; unknown: number }>();
  for (const cs of competitorSentiments) sentByName.set(norm(cs.name), cs.sentimentBreakdown);
  const sentMentionByName = new Map<string, number>();
  for (const cs of competitorSentiments) sentMentionByName.set(norm(cs.name), cs.mentionCount);

  const maxScore = Math.max(ourGeoScore, ...topCompetitors.map((c) => c.geoScore || 0), 1);
  return (
    <div className="space-y-4">
      <div className="rounded-xl border border-[var(--shell-accent)]/30 bg-[var(--shell-accent)]/5 px-4 py-3">
        <div className="flex items-center justify-between text-sm">
          <span className="font-medium text-[var(--shell-text)]">우리 브랜드</span>
          <span className="text-[var(--shell-accent)]">GEO {ourGeoScore}</span>
        </div>
        <div className="mt-2 h-1.5 w-full overflow-hidden rounded-full bg-[var(--shell-panel-soft)]">
          <div className="h-full bg-[var(--shell-accent)]" style={{ width: `${(ourGeoScore / maxScore) * 100}%` }} />
        </div>
      </div>

      {userCompetitors.length > 0 && (
        <div>
          <div className="mb-2 flex items-center gap-2 text-xs font-semibold text-[var(--shell-text)]">
            <Star className="h-3 w-3 fill-amber-300 text-amber-300" /> 고객 등록 경쟁사 ({userCompetitors.length})
          </div>
          <div className="space-y-2">
            {userCompetitors.map((cName, i) => {
              const sent = sentByName.get(norm(cName));
              const mentions = sentMentionByName.get(norm(cName)) ?? 0;
              return <CompetitorRow key={i} name={cName} mentions={mentions} sent={sent} highlight />;
            })}
          </div>
        </div>
      )}

      {topCompetitors.length > 0 && (
        <div>
          <div className="mb-2 text-xs font-semibold text-[var(--shell-text)]">자동 탐지 Top 5</div>
          <div className="space-y-2">
            {topCompetitors.slice(0, 5).map((c, i) => {
              const sent = sentByName.get(norm(c.name));
              return <CompetitorRow key={i} name={c.name} mentions={c.geoMentionCount} sent={sent} score={c.geoScore} />;
            })}
          </div>
        </div>
      )}
    </div>
  );
}

function CompetitorRow({
  name,
  mentions,
  sent,
  highlight,
  score,
}: {
  name: string;
  mentions: number;
  sent?: { positive: number; negative: number; neutral: number; unknown: number };
  highlight?: boolean;
  score?: number;
}) {
  const total = sent ? sent.positive + sent.negative + sent.neutral + sent.unknown : 0;
  return (
    <div
      className={`rounded-xl border px-4 py-3 ${
        highlight ? "border-amber-500/30 bg-amber-500/5" : "border-[var(--shell-border)] bg-[var(--shell-panel-soft)]"
      }`}
    >
      <div className="flex items-center justify-between text-sm">
        <span className="flex items-center gap-1.5 text-[var(--shell-text)]">
          {highlight && <Star className="h-3 w-3 fill-amber-300 text-amber-300" />}
          {name}
        </span>
        <span className="text-[var(--shell-text-muted)]">
          {score !== undefined && `GEO ${score} · `}언급 {mentions}
          {sent ? ` 회 (분석 ${total})` : " 회"}
        </span>
      </div>
      {sent && total > 0 && (
        <div className="mt-2 flex h-1.5 overflow-hidden rounded-full bg-[var(--shell-panel)]">
          <div className="bg-emerald-500" style={{ width: `${(sent.positive / total) * 100}%` }} />
          <div className="bg-blue-500" style={{ width: `${(sent.neutral / total) * 100}%` }} />
          <div className="bg-red-500" style={{ width: `${(sent.negative / total) * 100}%` }} />
        </div>
      )}
    </div>
  );
}

function AnswersTab({
  topAnswers,
  hasSentiment,
  onDownloadCsv,
}: {
  topAnswers?: { positive: ProbeSentimentRecord[]; negative: ProbeSentimentRecord[]; neutral: ProbeSentimentRecord[] };
  hasSentiment: boolean;
  onDownloadCsv: () => void;
}) {
  if (!hasSentiment || !topAnswers) {
    return (
      <div className="rounded-lg border border-amber-500/30 bg-amber-500/5 px-4 py-4 text-sm text-amber-200">
        Sentiment 분석 결과가 없습니다. 위 'sentiment 분석' 버튼을 실행해주세요.
      </div>
    );
  }
  return (
    <div className="space-y-4">
      <div className="flex items-center justify-end">
        <button
          type="button"
          onClick={onDownloadCsv}
          className="flex items-center gap-1.5 rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-1.5 text-xs text-[var(--shell-text)] hover:bg-[var(--shell-panel-strong)]"
        >
          <Download className="h-3.5 w-3.5" />
          전체 답변 CSV 다운로드
        </button>
      </div>
      <AnswerSection
        label="긍정 답변 Top 3"
        icon={<ThumbsUp className="h-4 w-4 text-emerald-400" />}
        items={topAnswers.positive}
        sentiment="positive"
      />
      <AnswerSection
        label="부정 답변 Top 3"
        icon={<ThumbsDown className="h-4 w-4 text-red-400" />}
        items={topAnswers.negative}
        sentiment="negative"
      />
      <AnswerSection
        label="중립 답변 Top 3"
        icon={<Minus className="h-4 w-4 text-blue-400" />}
        items={topAnswers.neutral}
        sentiment="neutral"
      />
    </div>
  );
}

function AnswerSection({
  label,
  icon,
  items,
  sentiment,
}: {
  label: string;
  icon: React.ReactNode;
  items: ProbeSentimentRecord[];
  sentiment: SentimentLabel;
}) {
  if (!items || items.length === 0) return null;
  return (
    <div>
      <div className="mb-2 flex items-center gap-2 text-sm font-semibold text-[var(--shell-text)]">
        {icon} {label}
      </div>
      <div className="space-y-2">
        {items.map((r, i) => (
          <div key={i} className={`rounded-xl border p-3 ${SENT_TONE[sentiment]}`}>
            <div className="flex items-center justify-between text-[10px] text-[var(--shell-text-soft)]">
              <span className="flex items-center gap-1">
                {ENGINE_LABELS[r.engine] || r.engine} ·
                {r.ourSiteMentioned ? (
                  <span className="flex items-center gap-0.5 text-emerald-300">
                    <CheckCircle2 className="h-3 w-3" /> 우리 브랜드 언급됨
                  </span>
                ) : (
                  <span className="flex items-center gap-0.5 text-red-300">
                    <XCircle className="h-3 w-3" /> 미언급
                  </span>
                )}
              </span>
              <span>
                {new Date(r.createdAt).toLocaleDateString()} · {SENT_LABEL[r.overallSentiment]}
              </span>
            </div>
            <div className="mt-1 text-xs font-medium text-[var(--shell-text)]">Q. {r.question}</div>
            <div className="mt-1 text-xs leading-6 text-[var(--shell-text-muted)]">{r.excerpt || "(요약 없음)"}</div>
          </div>
        ))}
      </div>
    </div>
  );
}
