// Portal 데이터 허브 — Phase 3: Firestore read only. mock 폴백 없음.
// 훅 시그니처는 zero-arg 유지. boardId 는 라우트에서 읽고, 없으면 쿼리 비활성.

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useParams } from "react-router-dom";
import {
  getPortalActions,
  getPortalBrandTruth,
  getPortalCompetitorMentions,
  getPortalDashboard,
  getPortalManualActions,
  getPortalProbes,
  getPortalSeo,
  getPortalSentiment,
  getPortalTrendSnapshots,
  getPortalWeeklyReport,
  savePortalBrandTruth,
} from "../../../db/portal";
import type { BrandTruth } from "./types";

function useBoardId(): string | undefined {
  const { id } = useParams<{ id: string }>();
  return id;
}

const STALE = 60_000;

export function usePortalDashboard() {
  const boardId = useBoardId();
  return useQuery({
    queryKey: ["portal", "dashboard", boardId],
    queryFn: () => getPortalDashboard(boardId!),
    enabled: !!boardId,
    staleTime: STALE,
  });
}

