export function useSavePortalBrandTruth() {
  const boardId = useBoardId();
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (data: Partial<BrandTruth>) => {
      if (!boardId) throw new Error("No board selected");
      await savePortalBrandTruth(boardId, data);
    },
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ["portal", "brand-truth", boardId] });
      qc.invalidateQueries({ queryKey: ["portal", "dashboard", boardId] });
    },
  });
}

