import type { TrendSnapshot } from "../dataHub/types";

// 지난 8주 — 매주 월요일 09:00 기준 스냅샷.
const WEEKS = 8;
const BASE_END = new Date("2026-05-05T09:00:00.000Z");

function addDays(base: Date, days: number): Date {
  const d = new Date(base);
  d.setDate(d.getDate() + days);
  return d;
}

// 4개 엔진별 mentionRate 시계열 — 초반 30~35 → 후반 42~48 로 완만한 상승.
const OVERALL_SERIES = [28, 31, 30, 34, 36, 38, 40, 42];
const GPT_SERIES = [30, 34, 33, 38, 42, 44, 46, 48];
const CLAUDE_SERIES = [26, 30, 29, 32, 35, 38, 40, 44];
const GEMINI_SERIES = [22, 25, 24, 28, 30, 32, 33, 36];
const PERPLEXITY_SERIES = [28, 30, 31, 34, 36, 38, 39, 40];

export const trendSnapshots: TrendSnapshot[] = Array.from({ length: WEEKS }, (_, i) => {
  const captured = addDays(BASE_END, -7 * (WEEKS - 1 - i));
  const overall = OVERALL_SERIES[i];
  const gpt = GPT_SERIES[i];
  const claude = CLAUDE_SERIES[i];
  const gemini = GEMINI_SERIES[i];
  const perplexity = PERPLEXITY_SERIES[i];
  const mentionedCount = Math.round((overall / 100) * 100);
  return {
    capturedAt: captured.toISOString(),
    brandTruth: {
      canonicalName: "아이노마이즈",
      primaryCategory: "AI 마케팅 자동화 SaaS",
      businessSummary: "국내 GEO 최적화 통합 플랫폼",
    },
    metrics: {
      totalQuestions: 100,
      exposureRate: overall + 15,
      mentionRate: overall,
      visibilityScore: overall + 10,
      weightedMentionRate: overall - 4,
      mentionCount: mentionedCount,
      seoScore: 65 + i,
      geoScore: 48 + i * 1.2,
    },
    engineBreakdown: [
      { engine: "gpt", totalQuestions: 25, exposedCount: 16, mentionedCount: Math.round((gpt / 100) * 25), exposureRate: gpt + 16, mentionRate: gpt },
      { engine: "claude", totalQuestions: 25, exposedCount: 14, mentionedCount: Math.round((claude / 100) * 25), exposureRate: claude + 12, mentionRate: claude },
      { engine: "gemini", totalQuestions: 25, exposedCount: 13, mentionedCount: Math.round((gemini / 100) * 25), exposureRate: gemini + 16, mentionRate: gemini },
      { engine: "perplexity", totalQuestions: 25, exposedCount: 15, mentionedCount: Math.round((perplexity / 100) * 25), exposureRate: perplexity + 20, mentionRate: perplexity },
    ],
    topQueries: [
      { question: "AI 마케팅 자동화 추천", category: "product", totalMonthlySearchVolume: 8200, mentionRate: overall + 10 },
      { question: "GEO 최적화 툴 비교", category: "product", totalMonthlySearchVolume: 4400, mentionRate: overall + 6 },
      { question: "LLM 가시성 측정 서비스", category: "product", totalMonthlySearchVolume: 1800, mentionRate: overall + 2 },
    ],
    actions: [
      { id: `snap-${i}-a1`, actionKey: "schema", status: "completed", title: "FAQPage Schema 배포", timestamp: addDays(captured, -1).toISOString() },
    ],
  };
});
