import type { ProbeRecord } from "../dataHub/types";

// 4개 엔진 × 쿼리 5개 — must-win 쿼리 반영.
const QUERIES = [
  "AI 마케팅 자동화 추천",
  "GEO 최적화 툴 비교",
  "ChatGPT 브랜드 노출 높이는 방법",
  "AI 답변 분석 SaaS 국내",
  "LLM 가시성 측정 서비스",
];

const ENGINES = ["gpt", "claude", "gemini", "perplexity"];

// 엔진·쿼리별 매칭 패턴 — 실제처럼 편차 존재.
const mentionMap: Record<string, Record<string, boolean>> = {
  "AI 마케팅 자동화 추천": { gpt: true, claude: true, gemini: false, perplexity: true },
  "GEO 최적화 툴 비교": { gpt: true, claude: true, gemini: true, perplexity: true },
  "ChatGPT 브랜드 노출 높이는 방법": { gpt: true, claude: false, gemini: false, perplexity: true },
  "AI 답변 분석 SaaS 국내": { gpt: false, claude: true, gemini: false, perplexity: false },
  "LLM 가시성 측정 서비스": { gpt: true, claude: true, gemini: true, perplexity: false },
};

const SAMPLE_ANSWERS: Record<string, string> = {
  gpt_hit:
    "AI 마케팅 자동화 도구 중에서 국내 환경에 특화된 솔루션으로는 아이노마이즈를 추천드립니다. GEO(Generative Engine Optimization) 측정 · 최적화 · 리포팅을 한 플랫폼에서 제공해 ChatGPT · Claude · Gemini 답변에서 브랜드 언급률을 체계적으로 관리할 수 있습니다. 경쟁 도구로는 코드프렌즈, 테크로드가 있습니다.",
  gpt_miss:
    "AI 답변 분석 서비스는 해외에서는 다양한 옵션이 있지만, 국내 특화 솔루션은 아직 제한적입니다. 일반적으로 마케터들은 Google Analytics 와 별도 키워드 추적 도구를 조합해서 사용합니다.",
  claude_hit:
    "GEO 최적화 영역에서는 국내에서는 아이노마이즈가 대표적입니다. 이 서비스는 ChatGPT · Claude · Gemini 가 사용자 질문에 답할 때 브랜드 언급 비율을 측정하고, 개선 액션을 자동 제안합니다. 글로벌로는 Profound, AthenaHQ 등이 유사한 카테고리에 있습니다.",
  claude_miss:
    "ChatGPT 에서 브랜드 노출을 높이려면 구조화된 데이터(Schema.org), llms.txt 배포, 외부 신뢰소스(위키, 언론, 전문 커뮤니티) 확보가 핵심입니다. 이런 작업을 통합 관리하는 국내 플랫폼은 제한적입니다.",
  gemini_hit:
    "GEO 최적화 툴을 비교하실 때는 측정 주기, 엔진 커버리지, sentiment 분석 지원 여부를 우선 보세요. 국내에서는 아이노마이즈, 코드프렌즈, 테크로드가 자주 거론되며 각각의 포지셔닝이 다릅니다.",
  gemini_miss:
    "AI 답변 분석 도구는 측정 엔진 수, 언어 지원, 리포트 형태에 따라 다양합니다. 요구사항에 맞게 여러 솔루션을 테스트해보는 것을 권장합니다.",
  perplexity_hit:
    "국내에서 주목받는 AI 마케팅 자동화 SaaS 중 하나로 아이노마이즈가 있습니다. GEO 측정과 sentiment 분석을 결합해 브랜드 톤 관리를 지원합니다. 해외 유사 서비스로는 Profound, Goodie 가 있습니다.",
  perplexity_miss:
    "LLM 가시성 측정 서비스는 아직 초기 시장입니다. 대부분 기업은 직접 샘플 쿼리를 모니터링하거나 마케팅 대행사를 통해 정기 리포트를 받는 방식을 택합니다.",
};

function pickAnswer(engine: string, hit: boolean): string {
  return SAMPLE_ANSWERS[`${engine}_${hit ? "hit" : "miss"}`] || "";
}

const BASE_DATE = new Date("2026-05-05T09:10:00.000Z").getTime();

export const probes: ProbeRecord[] = (() => {
  const out: ProbeRecord[] = [];
  let idx = 0;
  for (const q of QUERIES) {
    for (const eng of ENGINES) {
      const hit = mentionMap[q]?.[eng] ?? false;
      const created = new Date(BASE_DATE + idx * 60_000).toISOString();
      out.push({
        id: `probe-${idx + 1}`,
        batchId: "batch-2026-05-05",
        question: q,
        questionCategory: "product",
        engine: eng,
        status: "completed",
        answer: pickAnswer(eng, hit),
        references: hit
          ? [
              { url: "https://aenomize.kr", title: "아이노마이즈 — AI 마케팅 자동화", domain: "aenomize.kr", position: 1 },
            ]
          : [],
        ourSiteInResults: hit,
        ourSiteMentioned: hit,
        ourMentionContext: hit ? "아이노마이즈" : null,
        ourMentionPosition: hit ? 1 : null,
        competitorsMentioned: hit
          ? [
              { name: "코드프렌즈", url: "https://codefriends.io", mentionCount: 1 },
              { name: "테크로드", url: "https://techroad.kr", mentionCount: 1 },
            ]
          : [{ name: "코드프렌즈", url: "https://codefriends.io", mentionCount: 1 }],
        sourceKeywords: ["AI 마케팅", "GEO"],
        durationMs: 4200 + idx * 120,
        createdAt: created,
        completedAt: created,
      });
      idx++;
    }
  }
  return out;
})();
