import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { onSnapshot, query } from "firebase/firestore";
import { ArrowLeft, CheckCircle2, ShieldCheck, UserRound } from "lucide-react";
import { paths } from "../db/paths";
import { resolveUserRole, setUserRole, UserDoc } from "../db/users";
import { useAuth } from "../contexts/AuthContext";

export function AdminUsers() {
  const { isAdmin } = useAuth();
  const [users, setUsers] = useState<UserDoc[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [approvingUid, setApprovingUid] = useState<string | null>(null);

  useEffect(() => {
    if (!isAdmin) return;

    const q = query(paths.users());
    const unsub = onSnapshot(
      q,
      (snap) => {
        const list: UserDoc[] = [];
        snap.forEach((doc) => {
          const data = doc.data() as UserDoc;
          list.push({ ...data, uid: data.uid || doc.id });
        });
        setUsers(list);
        setLoading(false);
      },
      (err) => {
        console.error("Error loading users:", err);
        setError(err instanceof Error ? err.message : "사용자 목록을 불러오지 못했습니다.");
        setLoading(false);
      },
    );
    return unsub;
  }, [isAdmin]);

  if (!isAdmin) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-[var(--shell-main)] text-[var(--shell-text-muted)]">
        관리자 권한이 필요합니다.
      </div>
    );
  }

  const pendingUsers = users.filter((u) => resolveUserRole(u) === "pending");
  const memberUsers = users.filter((u) => resolveUserRole(u) === "member");

  const handleApprove = async (uid: string) => {
    setApprovingUid(uid);
    try {
      await setUserRole(uid, "member");
    } catch (err) {
      alert(err instanceof Error ? err.message : "승인에 실패했습니다.");
    } finally {
      setApprovingUid(null);
    }
  };

  return (
    <div className="min-h-screen bg-[var(--shell-main)] text-[var(--shell-text)]">
      <div className="mx-auto max-w-[960px] px-4 py-8 sm:px-6">
        <header className="mb-8 flex items-center justify-between gap-4">
          <div className="flex items-center gap-3">
            <Link
              to="/"
              className="shell-transition grid h-10 w-10 place-items-center rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] text-[var(--shell-text-muted)] hover:text-[var(--shell-text)]"
              title="Back"
            >
              <ArrowLeft className="h-4 w-4" />
            </Link>
            <div>
              <div className="flex items-center gap-2 text-[11px] uppercase tracking-[0.24em] text-[var(--shell-text-soft)]">
                <ShieldCheck className="h-3.5 w-3.5" />
                Admin
              </div>
              <h1 className="mt-1 text-2xl font-semibold tracking-[-0.03em]">User approvals</h1>
            </div>
          </div>
        </header>

        {error && (
          <div className="mb-6 rounded-2xl border border-[var(--shell-danger)]/30 bg-[var(--shell-danger)]/10 px-4 py-3 text-sm text-[var(--shell-danger)]">
            {error}
          </div>
        )}

        <section className="shell-panel rounded-[28px] p-6">
          <div className="mb-4 flex items-baseline justify-between">
            <div className="text-[11px] uppercase tracking-[0.22em] text-[var(--shell-text-soft)]">
              Pending approval
            </div>
            <div className="text-sm text-[var(--shell-text-muted)]">{pendingUsers.length}명</div>
          </div>

          {loading ? (
            <div className="py-8 text-center text-sm text-[var(--shell-text-soft)]">불러오는 중...</div>
          ) : pendingUsers.length === 0 ? (
            <div className="rounded-[22px] border border-dashed border-[var(--shell-border)] px-4 py-8 text-center text-sm text-[var(--shell-text-soft)]">
              승인 대기 중인 사용자가 없습니다.
            </div>
          ) : (
            <div className="space-y-3">
              {pendingUsers.map((u) => (
                <div
                  key={u.uid}
                  className="flex items-center justify-between gap-3 rounded-[20px] border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-4"
                >
                  <div className="flex min-w-0 items-center gap-3">
                    <div className="grid h-10 w-10 shrink-0 place-items-center rounded-full bg-[var(--shell-panel-strong)] text-[var(--shell-text-muted)]">
                      <UserRound className="h-4 w-4" />
                    </div>
                    <div className="min-w-0">
                      <div className="truncate text-base font-medium">
                        {u.displayName || u.email || u.uid}
                      </div>
                      <div className="mt-0.5 truncate text-xs text-[var(--shell-text-soft)]">
                        {u.email}
                      </div>
                    </div>
                  </div>
                  <button
                    onClick={() => handleApprove(u.uid)}
                    disabled={approvingUid === u.uid}
                    className="shell-transition flex shrink-0 items-center gap-2 rounded-2xl border border-[var(--shell-accent)] bg-[var(--shell-accent)] px-4 py-2 text-sm font-medium text-white hover:opacity-90 disabled:cursor-not-allowed disabled:opacity-50"
                  >
                    <CheckCircle2 className="h-4 w-4" />
                    {approvingUid === u.uid ? "승인 중..." : "멤버로 승인"}
                  </button>
                </div>
              ))}
            </div>
          )}
        </section>

        <section className="shell-panel mt-6 rounded-[28px] p-6">
          <div className="mb-4 flex items-baseline justify-between">
            <div className="text-[11px] uppercase tracking-[0.22em] text-[var(--shell-text-soft)]">
              Members
            </div>
            <div className="text-sm text-[var(--shell-text-muted)]">{memberUsers.length}명</div>
          </div>

          {memberUsers.length === 0 ? (
            <div className="rounded-[22px] border border-dashed border-[var(--shell-border)] px-4 py-8 text-center text-sm text-[var(--shell-text-soft)]">
              아직 승인된 멤버가 없습니다.
            </div>
          ) : (
            <div className="space-y-2">
              {memberUsers.map((u) => (
                <div
                  key={u.uid}
                  className="flex items-center justify-between gap-3 rounded-[20px] border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3"
                >
                  <div className="flex min-w-0 items-center gap-3">
                    <div className="grid h-9 w-9 shrink-0 place-items-center rounded-full bg-[var(--shell-panel-strong)] text-[var(--shell-text-muted)]">
                      <UserRound className="h-4 w-4" />
                    </div>
                    <div className="min-w-0">
                      <div className="truncate text-sm font-medium">
                        {u.displayName || u.email || u.uid}
                      </div>
                      <div className="mt-0.5 truncate text-xs text-[var(--shell-text-soft)]">
                        {u.email}
                      </div>
                    </div>
                  </div>
                  <span className="shrink-0 rounded-full bg-[var(--shell-positive)]/15 px-2.5 py-1 text-[11px] font-medium text-[var(--shell-positive)]">
                    member
                  </span>
                </div>
              ))}
            </div>
          )}
        </section>
      </div>
    </div>
  );
}
